"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  EMPTY_DOCUMENTATION_PROGRESS,
  clearDocumentationProgress,
  getDocumentationProgressPercent,
  loadDocumentationProgress,
  saveDocumentationProgress,
  toggleProgressValue,
  type DocumentationProgress,
} from "../../../lib/utils/documentationProgress";

export function useDocumentationProgress(slugs: string[]) {
  const validSlugs = useMemo(() => new Set(slugs), [slugs]);
  const [progress, setProgress] = useState<DocumentationProgress>(
    EMPTY_DOCUMENTATION_PROGRESS,
  );
  const [hasLoaded, setHasLoaded] = useState(false);

  useEffect(() => {
    setProgress(loadDocumentationProgress(validSlugs));
    setHasLoaded(true);
  }, [validSlugs]);

  const update = useCallback(
    (updater: (current: DocumentationProgress) => DocumentationProgress) => {
      setProgress((current) => {
        const next = updater(current);
        saveDocumentationProgress(next);
        return next;
      });
    },
    [],
  );

  const toggleBookmark = useCallback(
    (slug: string) => {
      update((current) => ({
        ...current,
        bookmarks: toggleProgressValue(current.bookmarks, slug),
      }));
    },
    [update],
  );

  const toggleCompleted = useCallback(
    (slug: string) => {
      update((current) => ({
        ...current,
        completed: toggleProgressValue(current.completed, slug),
      }));
    },
    [update],
  );

  const clear = useCallback(() => {
    clearDocumentationProgress();
    setProgress(EMPTY_DOCUMENTATION_PROGRESS);
  }, []);

  return {
    progress,
    hasLoaded,
    toggleBookmark,
    toggleCompleted,
    clear,
    percent: getDocumentationProgressPercent(
      progress.completed.length,
      slugs.length,
    ),
  };
}

'use client';

import React, { useState, useMemo } from 'react';
import Navbar from '@/components/layout/Navbar';
import Footer from '@/components/layout/footer';
import MythCard from '@/components/myth-busters/MythCard';
import MythQuiz from '@/components/myth-busters/MythQuiz';
import MythDetailModal from '@/components/myth-busters/MythDetailModal';
import { searchMyths } from '@/lib/myth-busters/mythData';
import { MythItem, MythCategory } from '@/lib/myth-busters/types';
import { Search, Flame, ShieldAlert } from 'lucide-react';

export default function MythBustersPage() {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<MythCategory>('All');
  const [selectedMyth, setSelectedMyth] = useState<MythItem | null>(null);

  const filteredMyths = useMemo(() => {
    return searchMyths(searchQuery, selectedCategory);
  }, [searchQuery, selectedCategory]);

  const categories: MythCategory[] = [
    'All',
    'Encoding vs Encryption',
    'Hashing vs Encryption',
    'Key Management & Sizes',
    'Password Security',
    'Quantum & Future Tech',
    'Security Principles',
  ];

  return (
    <div className="min-h-screen flex flex-col bg-white dark:bg-[#060816] text-zinc-900 dark:text-white transition-colors duration-300">
      <Navbar />

      <main id="main-content" className="flex-1 mx-auto w-full max-w-7xl px-4 py-10 sm:px-6 lg:px-8 space-y-12">
        {/* Hero Section */}
        <section aria-labelledby="myth-hero-title" className="relative overflow-hidden rounded-3xl border border-zinc-200/80 dark:border-zinc-800/80 bg-gradient-to-br from-red-500/10 via-amber-500/5 to-transparent p-8 sm:p-12 backdrop-blur-2xl">
          <div className="max-w-3xl space-y-4">
            <div className="inline-flex items-center gap-2 rounded-full border border-red-500/30 bg-red-500/10 px-3.5 py-1 text-xs font-bold text-red-600 dark:text-red-400">
              <Flame className="h-3.5 w-3.5 animate-pulse" />
              CRYPTOGRAPHY MYTH BUSTERS #495
            </div>
            <h1 id="myth-hero-title" className="text-3xl sm:text-5xl font-black tracking-tight text-zinc-900 dark:text-white">
              Busting Cryptography <span className="text-red-500">Misconceptions</span>
            </h1>
            <p className="text-base sm:text-lg text-zinc-600 dark:text-zinc-300 leading-relaxed">
              Correcting widespread crypto security myths with rigorous mathematical analysis, technical realities, and Kerckhoffs's principle benchmarks.
            </p>
          </div>
        </section>

        {/* Interactive Reality Check Quiz Section */}
        <section aria-labelledby="myth-quiz-title">
          <MythQuiz />
        </section>

        {/* Search & Category Filters */}
        <section aria-labelledby="myths-grid-heading" className="space-y-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h2 id="myths-grid-heading" className="text-2xl sm:text-3xl font-extrabold text-zinc-900 dark:text-white">
                Exploded Security Myths
              </h2>
              <p className="text-sm text-zinc-500 dark:text-zinc-400 mt-1">
                Explore debunked misconceptions and technical realities.
              </p>
            </div>

            {/* Search Input */}
            <div className="relative w-full sm:w-80">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400" />
              <input
                type="text"
                placeholder="Search myths or concepts..."
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                aria-label="Search cryptography myths or security topics"
                className="w-full rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 pl-10 pr-4 py-2.5 text-sm text-zinc-900 dark:text-white placeholder-zinc-400 focus:border-teal-500 focus:outline-none focus:ring-1 focus:ring-teal-500 transition-colors"
              />
            </div>
          </div>

          {/* Category Filter Pills */}
          <div className="flex flex-wrap items-center gap-2 overflow-x-auto pb-2" role="tablist" aria-label="Myth category filter">
            {categories.map(cat => (
              <button
                key={cat}
                role="tab"
                aria-selected={selectedCategory === cat}
                onClick={() => setSelectedCategory(cat)}
                className={`rounded-xl px-4 py-2 text-xs font-semibold transition-all ${
                  selectedCategory === cat
                    ? 'bg-teal-500 text-black shadow-md shadow-teal-500/20'
                    : 'bg-zinc-100 dark:bg-zinc-800/80 text-zinc-700 dark:text-zinc-300 hover:bg-zinc-200 dark:hover:bg-zinc-800'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Myth Grid */}
          {filteredMyths.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredMyths.map(myth => (
                <MythCard
                  key={myth.id}
                  myth={myth}
                  onOpenDetails={m => setSelectedMyth(m)}
                />
              ))}
            </div>
          ) : (
            <div className="rounded-2xl border border-dashed border-zinc-300 dark:border-zinc-800 p-12 text-center">
              <ShieldAlert className="mx-auto h-8 w-8 text-zinc-400 mb-2" />
              <p className="text-zinc-500 dark:text-zinc-400 font-medium">
                No cryptography myths found matching "{searchQuery}".
              </p>
              <button
                onClick={() => {
                  setSearchQuery('');
                  setSelectedCategory('All');
                }}
                className="mt-3 text-xs font-bold text-teal-500 hover:underline"
              >
                Reset Search Filters
              </button>
            </div>
          )}
        </section>
      </main>

      {/* Myth Detail Modal */}
      <MythDetailModal
        myth={selectedMyth}
        isOpen={Boolean(selectedMyth)}
        onClose={() => setSelectedMyth(null)}
      />

      <Footer />
    </div>
  );
}

'use client'

import { useEffect, useRef, useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import Navbar from '../components/layout/Navbar'

const CIPHER_CHARS = '01アイウエオカキクケコABCDEF!@#$%^&*'
const COUNTDOWN_START = 10

function GlitchText({ text }: { text: string }) {
    const [display, setDisplay] = useState(text)
    const iterRef = useRef(0)

    useEffect(() => {
        const chars = text.split('')
        const interval = setInterval(() => {
            iterRef.current += 1
            setDisplay(
                chars
                    .map((char, i) =>
                        i < iterRef.current
                            ? char
                            : CIPHER_CHARS[Math.floor(Math.random() * CIPHER_CHARS.length)]
                    )
                    .join('')
            )
            if (iterRef.current >= chars.length) {
                clearInterval(interval)
                setDisplay(text)
            }
        }, 40)
        return () => clearInterval(interval)
    }, [text])

    useEffect(() => {
        // Periodic re-glitch on a random character
        const glitch = setInterval(() => {
            const idx = Math.floor(Math.random() * text.length)
            setDisplay((prev) => {
                const arr = prev.split('')
                arr[idx] = CIPHER_CHARS[Math.floor(Math.random() * CIPHER_CHARS.length)]
                return arr.join('')
            })
            setTimeout(() => setDisplay(text), 80)
        }, 2800)
        return () => clearInterval(glitch)
    }, [text])

    return <span aria-label={text}>{display}</span>
}

function MatrixRain() {
    const canvasRef = useRef<HTMLCanvasElement>(null)

    useEffect(() => {
        const canvas = canvasRef.current
        if (!canvas) return
        const ctx = canvas.getContext('2d')
        if (!ctx) return

        const resize = () => {
            canvas.width = canvas.offsetWidth
            canvas.height = canvas.offsetHeight
        }
        resize()
        const ro = new ResizeObserver(resize)
        ro.observe(canvas)

        const fontSize = 13
        const cols = Math.floor(canvas.width / fontSize)
        const drops = Array.from({ length: cols }, () => Math.random() * -50)

        // Caps the redraw rate (~24fps is plenty for a background effect
        // and cuts idle CPU/GPU work well below a full 60fps loop).
        const FRAME_INTERVAL = 1000 / 24
        let lastFrameTime = 0
        let prevIsDark: boolean | null = null
        let paused = document.hidden

        let raf: number
        const draw = (time: number) => {
            raf = requestAnimationFrame(draw)
            if (paused) return
            if (time - lastFrameTime < FRAME_INTERVAL) return
            lastFrameTime = time

            // Theme is read per-frame so the rain recolors itself when the
            // user toggles light/dark without needing a remount.
            const isDark = document.documentElement.classList.contains('dark')

            // On an actual theme change, hard-clear instead of fading, so
            // the switch reads as instant rather than a slow crossfade.
            if (prevIsDark !== null && prevIsDark !== isDark) {
                ctx.clearRect(0, 0, canvas.width, canvas.height)
            }
            prevIsDark = isDark

            // Trailing fade wash behind the falling characters.
            ctx.fillStyle = isDark ? 'rgba(9,9,11,0.18)' : 'rgba(250,250,251,0.06)'
            ctx.fillRect(0, 0, canvas.width, canvas.height)
            ctx.font = `${fontSize}px monospace`

            drops.forEach((y, i) => {
                const char = CIPHER_CHARS[Math.floor(Math.random() * CIPHER_CHARS.length)]
                const isBright = Math.random() > 0.92
                // Light mode needs more alpha to read as "bright" against a
                // white page; dark mode is unchanged from before.
                const alpha = isDark ? (isBright ? 1 : 0.35) : (isBright ? 1 : 0.85)
                ctx.fillStyle = isDark ? `rgba(45,212,191,${alpha})` : `rgba(13,148,136,${alpha})`
                ctx.fillText(char, i * fontSize, y * fontSize)
                drops[i] = y > canvas.height / fontSize + Math.random() * 20 ? 0 : y + 1.1
            })
        }
        raf = requestAnimationFrame(draw)

        // Stop drawing entirely when the tab isn't visible.
        const handleVisibility = () => {
            paused = document.hidden
        }
        document.addEventListener('visibilitychange', handleVisibility)

        return () => {
            cancelAnimationFrame(raf)
            ro.disconnect()
            document.removeEventListener('visibilitychange', handleVisibility)
        }
    }, [])

    return (
        <canvas
            ref={canvasRef}
            className="absolute inset-0 h-full w-full opacity-40 dark:opacity-40"
            aria-hidden="true"
        />
    )
}

export default function NotFound() {
    const router = useRouter()
    const [countdown, setCountdown] = useState(COUNTDOWN_START)
    const [cancelled, setCancelled] = useState(false)
    const redirectRef = useRef<ReturnType<typeof setTimeout> | null>(null)
    const tickRef = useRef<ReturnType<typeof setInterval> | null>(null)

    useEffect(() => {
        if (cancelled) return

        tickRef.current = setInterval(() => {
            setCountdown((n) => {
                if (n <= 1) {
                    clearInterval(tickRef.current!)
                    return 0
                }
                return n - 1
            })
        }, 1000)

        redirectRef.current = setTimeout(() => {
            router.push('/')
        }, COUNTDOWN_START * 1000)

        return () => {
            clearInterval(tickRef.current!)
            clearTimeout(redirectRef.current!)
        }
    }, [cancelled])

    const handleReturn = () => {
        // Intentionally not calling setCancelled here: doing so unmounts the
        // countdown block immediately, and since navigation isn't instant,
        // that caused a visible flash of the card shrinking before the
        // browser actually left the page.
        clearInterval(tickRef.current!)
        clearTimeout(redirectRef.current!)
        // router.push (client-side nav) instead of window.location.href:
        // a hard reload was briefly showing the page in light mode before
        // the dark class was reapplied.
        router.push('/')
