                            : "border-rose-500 bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.3)] animate-pulse",
                      )}
                      title={`Hash 0x${index.toString(16).toUpperCase().padStart(2, "0")} — Hits: ${hits}`}
