"use client";

import { useMemo, useRef, useState } from "react";
import {
  type AttackStep,
  type OracleMode,
  BLOCK_SIZE,
} from "@/lib/attacks/paddingOracle";
import { useAttackWorker } from "@/lib/hooks/useAttackWorker";
import { toByteArray, fromByteArray } from "@/lib/utils";

// Ciphertext/IV fields are always hex here (that's the format the AES/CBC
// visualizer already produces). The key field is passed straight through
// as a string to PaddingOracle/decrypt(), since the app's own decrypt()
// accepts either a hex key or a utf8 passphrase and sniffs which one it
// got — we don't need to know which here.
function hexToBytes(hex: string): Uint8Array {
  const clean = hex.trim().replace(/\s+/g, "");
  if (clean.length % 2 !== 0 || !/^[0-9a-fA-F]*$/.test(clean)) {
    throw new Error("Ciphertext/IV must be valid hex.");
  }
  return toByteArray(clean, "hex");
}
function bytesToHex(bytes: Uint8Array): string {
  return fromByteArray(bytes, "hex");
}
function bytesToPrintable(bytes: Uint8Array): string {
  return Array.from(bytes)
    .map((b) => (b >= 0x20 && b < 0x7f ? String.fromCharCode(b) : "."))
    .join("");
}

const PLAYBACK_MS = 4; // per-step animation delay; total steps can be large

type RunState = "idle" | "running" | "done" | "error";

export default function PaddingOracleSimulator() {
  const [keyHex, setKeyHex] = useState("");
  const [ivHex, setIvHex] = useState("");
  const [ciphertextHex, setCiphertextHex] = useState("");
  const [mode, setMode] = useState<OracleMode>("vulnerable");

  const [runState, setRunState] = useState<RunState>("idle");
  const [error, setError] = useState<string | null>(null);
  const [visibleSteps, setVisibleSteps] = useState<AttackStep[]>([]);
  const [recoveredHex, setRecoveredHex] = useState<string | null>(null);
  const [queryCount, setQueryCount] = useState(0);

  const cancelRef = useRef(false);

  const allSteps = useMemo(() => [] as AttackStep[], []); // populated per-run below

  const { recoverPlaintextConcurrently, cancel, loading } = useAttackWorker();

  async function runAttack() {
    setError(null);
    setVisibleSteps([]);
    setRecoveredHex(null);
    setQueryCount(0);
    cancelRef.current = false;

    let iv: Uint8Array, ciphertext: Uint8Array;
    const key = keyHex; // passed through as-is; decrypt() accepts hex or a utf8 passphrase
    try {
      iv = hexToBytes(ivHex);
      ciphertext = hexToBytes(ciphertextHex);
    } catch (e) {
      setError((e as Error).message);
      setRunState("error");
      return;
    }
    if (ciphertext.length % BLOCK_SIZE !== 0 || ciphertext.length === 0) {
      setError(`Ciphertext must be a positive multiple of ${BLOCK_SIZE} bytes.`);
      setRunState("error");
      return;
    }
    if (iv.length !== BLOCK_SIZE) {
      setError(`IV must be exactly ${BLOCK_SIZE} bytes.`);
      setRunState("error");
      return;
    }

    setRunState("running");

    const steps: AttackStep[] = [];

    try {
      const { plaintext, queryCount: totalQueries } = await recoverPlaintextConcurrently(
        key,
        iv,
        ciphertext,
        mode,
        (step) => {
          if (!cancelRef.current) {
            steps.push(step);
            // Throttle updates or just add to array. Realtime updates for all blocks in parallel!
            // To keep React from choking, we can update visible steps periodically.
          }
        }
      );

      setQueryCount(totalQueries);
      await playback(steps, cancelRef);
      setRecoveredHex(bytesToHex(plaintext));
      setRunState("done");
    } catch (e) {
      setError((e as Error).message);
      setRunState("error");
      await playback(steps, cancelRef);
      return;
    }

    async function playback(stepsToShow: AttackStep[], cancelled: { current: boolean }) {
      const sortedSteps = [...stepsToShow].sort((a, b) => {
        if (a.blockIndex !== b.blockIndex) return a.blockIndex - b.blockIndex;
        // Inner blocks logic (wait, the steps are from parallel workers, so we just sort them roughly by progress)
        return 0;
      });
      const chunkSize = Math.max(1, Math.floor(sortedSteps.length / 400)); // cap animation frames
      for (let i = 0; i < sortedSteps.length; i += chunkSize) {
        if (cancelled.current) return;
        const next = sortedSteps.slice(0, i + chunkSize);
        setVisibleSteps(next);
        await new Promise((r) => setTimeout(r, PLAYBACK_MS));
      }
      setVisibleSteps(sortedSteps);
    }
  }

  function stop() {
    cancelRef.current = true;
    cancel();
  }

  const lastStep = visibleSteps[visibleSteps.length - 1];
  const recoveredBytesSoFar = visibleSteps.filter((s) => s.recoveredPlaintextByte !== undefined).length;

  return (
    <div className="flex flex-col gap-6 max-w-3xl">
      <div className="rounded-lg border border-amber-300 bg-amber-50 p-4 text-sm text-amber-900">
        <strong>Educational simulation only.</strong> This attack runs entirely in your
        browser against CryptoViz&apos;s own sandboxed <code>decrypt()</code> function.
        It has no network component and cannot be used against a real server —
        it exists to make the CBC padding-oracle vulnerability (the class behind
        POODLE and related TLS/SSL exploits) tangible, not to attack anything.
      </div>

      <div className="grid gap-3">
        <label className="flex flex-col gap-1 text-sm">
          Key (same value used to encrypt — hex or passphrase)
          <input
            className="rounded border px-2 py-1 font-mono"
            value={keyHex}
            onChange={(e) => setKeyHex(e.target.value)}
            placeholder="e.g. 000102030405060708090a0b0c0d0e0f, or a passphrase"
          />
        </label>
        <label className="flex flex-col gap-1 text-sm">
          IV (hex, {BLOCK_SIZE} bytes)
          <input
            className="rounded border px-2 py-1 font-mono"
            value={ivHex}
            onChange={(e) => setIvHex(e.target.value)}
          />
        </label>
        <label className="flex flex-col gap-1 text-sm">
          Ciphertext (hex, from the AES/CBC visualizer)
          <textarea
            className="rounded border px-2 py-1 font-mono"
            rows={3}
            value={ciphertextHex}
            onChange={(e) => setCiphertextHex(e.target.value)}
          />
        </label>

        <div className="flex items-center gap-3 text-sm">
          <span>Oracle:</span>
          <label className="flex items-center gap-1">
            <input
              type="radio"
              checked={mode === "vulnerable"}
              onChange={() => setMode("vulnerable")}
            />
            Vulnerable (distinct padding errors)
          </label>
          <label className="flex items-center gap-1">
            <input
              type="radio"
              checked={mode === "fixed"}
              onChange={() => setMode("fixed")}
            />
            Fixed (constant-time)
          </label>
        </div>

        <div className="flex gap-2">
          <button
            className="rounded bg-slate-900 px-4 py-2 text-sm text-white disabled:opacity-50"
            onClick={runAttack}
            disabled={runState === "running"}
          >
            {runState === "running" ? "Attacking…" : "Run attack"}
          </button>
          {runState === "running" && (
            <button className="rounded border px-4 py-2 text-sm" onClick={stop}>
              Stop
            </button>
          )}
        </div>
      </div>

      {error && (
        <div className="rounded border border-red-300 bg-red-50 p-3 text-sm text-red-800">
          {mode === "fixed" ? (
            <>
              <strong>Attack defeated.</strong> {error}
            </>
          ) : (
            error
          )}
        </div>
      )}

      {runState !== "idle" && (
        <div className="rounded-lg border p-4">
          <div className="mb-2 flex justify-between text-sm text-slate-600">
            <span>
              Oracle queries so far: <strong>{queryCount || visibleSteps.length}</strong>
            </span>
            <span>
              Plaintext bytes recovered: <strong>{recoveredBytesSoFar}</strong>
            </span>
          </div>

          {lastStep && (
            <div className="mb-3 font-mono text-xs text-slate-700">
              block {lastStep.blockIndex} · byte from end {lastStep.byteIndexFromEnd} ·
              guess 0x{lastStep.guess.toString(16).padStart(2, "0")} →{" "}
              {lastStep.isValidPadding ? "valid padding" : "invalid padding"}
              {lastStep.recoveredPlaintextByte !== undefined && (
                <> ✓ recovered 0x{lastStep.recoveredPlaintextByte.toString(16).padStart(2, "0")}</>
              )}
            </div>
          )}

          <div className="max-h-48 overflow-y-auto rounded bg-slate-950 p-2 font-mono text-[11px] leading-5 text-green-400">
            {visibleSteps.slice(-200).map((s, i) => (
              <div key={i}>
                [blk {s.blockIndex}][byte {17 - s.byteIndexFromEnd}] guess=0x
                {s.guess.toString(16).padStart(2, "0")} →{" "}
                {s.isValidPadding ? "VALID" : "invalid"}
                {s.recoveredPlaintextByte !== undefined &&
                  ` -> plaintext byte 0x${s.recoveredPlaintextByte
                    .toString(16)
                    .padStart(2, "0")}`}
              </div>
            ))}
          </div>

          {recoveredHex && (
            <div className="mt-4 rounded bg-slate-100 p-3">
              <div className="text-xs uppercase text-slate-500">Recovered plaintext</div>
              <div className="font-mono text-sm">{recoveredHex}</div>
              <div className="font-mono text-sm text-slate-600">
                {bytesToPrintable(hexToBytes(recoveredHex))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client'

/**
 * AvalancheVisualizer — type an input, flip a single bit, and watch the output
 * cascade. Two runs of the same algorithm (original input vs. bit-flipped
 * input) go through the shared cipher worker; the two hex outputs are diffed
 * bit-for-bit and rendered as a Hamming-distance meter plus a ByteHeatmap.
 *
 * No cipher-engine changes: this reuses the existing hash/cipher registry via
 * `useCipherWorker` and only diffs `CipherResult.output`.
 */

import { useEffect, useMemo, useRef, useState } from 'react'
import type { CipherResult } from '../../lib/cipher/types'
import { useCipherWorker } from '../../lib/hooks/useCipherWorker'
import {
  computeByteCells,
  diffStats,
  flipInputBit,
} from '../../lib/utils/bitDiff'
import ByteHeatmap from '../ui/ByteHeatmap'

type SecurityStatus = 'secure' | 'deprecated' | 'broken'

interface AvalancheAlgorithm {
  id: string
  name: string
  securityStatus: SecurityStatus
  /** Key material passed to the worker (empty for keyless hashes). */
  key: string
  /** Worker options; hashes need none, AES runs over UTF-8 text in ECB. */
  options: Record<string, unknown>
  /** Short line explaining what to expect from this primitive. */
  note: string
}

/**
 * The subset of the registry that produces a fixed-width hex digest/ciphertext
 * where the avalanche effect is meaningful to visualise.
 */
const ALGORITHMS: AvalancheAlgorithm[] = [
  {
    id: 'sha256',
    name: 'SHA-256',
    securityStatus: 'secure',
    key: '',
    options: {},
    note: 'Modern hash — a 1-bit change should scramble ~50% of the 256-bit digest.',
  },
  {
    id: 'sha512',
    name: 'SHA-512',
    securityStatus: 'secure',
    key: '',
    options: {},
    note: 'Wider 512-bit digest with the same strong diffusion.',
  },
  {
    id: 'sha3',
    name: 'SHA3-256',
    securityStatus: 'secure',
    key: '',
    options: {},
    note: 'Keccak sponge construction — strong, uniform diffusion.',
  },
  {
    id: 'sm3',
    name: 'SM3',
    securityStatus: 'secure',
    key: '',
    options: {},
    note: 'Chinese Commercial Cryptography standard (GB/T 32905-2016) — 256-bit digest with 64 ARX compression rounds.',
  },
  {
    id: 'ripemd160',
    name: 'RIPEMD-160',
    securityStatus: 'secure',
    key: '',
    options: {},
    note: 'Twin parallel compression lines over a 160-bit digest.',
  },
  {
    id: 'md5',
    name: 'MD5',
    securityStatus: 'broken',
    key: '',
    options: {},
    note: 'Broken hash — good diffusion here does not make it collision-resistant.',
  },
  {
    id: 'aes',
    name: 'AES-128 (ECB)',
    securityStatus: 'secure',
    key: '000102030405060708090a0b0c0d0e0f',
    options: { encoding: 'utf8', mode: 'ECB' },
    note: 'Block cipher — each 16-byte block diffuses a 1-bit change across the whole block.',
  },
]

const securityStyles: Record<SecurityStatus, string> = {
  secure:
    'border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900 dark:bg-emerald-950/30 dark:text-emerald-400',
  deprecated:
    'border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-400',
  broken:
    'border-red-200 bg-red-50 text-red-700 dark:border-red-900 dark:bg-red-950/30 dark:text-red-400',
}

const DEFAULT_INPUT = 'The quick brown fox'

/** Colour the meter by how close the change rate is to the ideal 50%. */
function meterTone(percent: number): string {
  const distanceFromIdeal = Math.abs(percent - 50)
  if (distanceFromIdeal <= 10) return 'bg-emerald-500'
  if (distanceFromIdeal <= 25) return 'bg-amber-500'
  return 'bg-red-500'
}

export default function AvalancheVisualizer() {
  const { runCipher, error: workerError } = useCipherWorker()

  const [input, setInput] = useState(DEFAULT_INPUT)
  const [algorithmId, setAlgorithmId] = useState(ALGORITHMS[0].id)
  const [charIndex, setCharIndex] = useState(0)
  const [bitIndex, setBitIndex] = useState(0)

  const [originalOutput, setOriginalOutput] = useState<string | null>(null)
  const [modifiedOutput, setModifiedOutput] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const resultRef = useRef<HTMLDivElement | null>(null)
  const runTokenRef = useRef(0)

  const algorithm = useMemo(
    () => ALGORITHMS.find((item) => item.id === algorithmId) ?? ALGORITHMS[0],
    [algorithmId],
  )

  // Keep the selected character in range as the input shrinks.
  const safeCharIndex = Math.min(charIndex, Math.max(0, input.length - 1))

  const flippedInput = useMemo(() => {
    if (input.length === 0) return ''
    return flipInputBit(input, safeCharIndex, bitIndex)
  }, [input, safeCharIndex, bitIndex])

  useEffect(() => {
    if (input.length === 0) {
      setOriginalOutput(null)
      setModifiedOutput(null)
      setError(null)
      return
    }

    const token = ++runTokenRef.current
    let cancelled = false
    setLoading(true)
    setError(null)

    const compute = async () => {
      try {
        // Sequential: the worker cancels overlapping requests, so we must let
        // the first run finish before starting the second.
        const first: CipherResult = await runCipher(
          'encrypt',
          algorithm.id,
          input,
          algorithm.key,
          algorithm.options,
        )
        const second: CipherResult = await runCipher(
          'encrypt',
          algorithm.id,
          flippedInput,
          algorithm.key,
          algorithm.options,
        )
        if (cancelled || token !== runTokenRef.current) return
        setOriginalOutput(first.output)
        setModifiedOutput(second.output)
      } catch (runError) {
        if (runError instanceof DOMException && runError.name === 'AbortError') {
          return
        }
        if (cancelled || token !== runTokenRef.current) return
        setOriginalOutput(null)
        setModifiedOutput(null)
        setError(
          runError instanceof Error
            ? runError.message
            : 'The avalanche computation failed.',
        )
      } finally {
        if (!cancelled && token === runTokenRef.current) {
          setLoading(false)
        }
      }
    }

    void compute()
    return () => {
      cancelled = true
    }
  }, [input, flippedInput, algorithm, runCipher])

  const stats = useMemo(() => {
    if (!originalOutput || !modifiedOutput) return null
    try {
      return diffStats(originalOutput, modifiedOutput)
    } catch {
      return null
    }
  }, [originalOutput, modifiedOutput])

  const cells = useMemo(() => {
    if (!originalOutput || !modifiedOutput) return []
    try {
      return computeByteCells(originalOutput, modifiedOutput)
    } catch {
      return []
    }
  }, [originalOutput, modifiedOutput])

  const hasResult = Boolean(originalOutput && modifiedOutput && stats)

  // Move focus to the results once a fresh computation lands.
  useEffect(() => {
    if (hasResult && !loading) {
      resultRef.current?.focus()
    }
  }, [hasResult, loading])

  const percent = stats?.percentChanged ?? 0

  return (
    <div className="space-y-8">
      <section className="grid gap-6 rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-zinc-900/40">
        <label className="grid gap-1.5 text-xs font-semibold text-zinc-600 dark:text-zinc-300">
          Input message
          <input
            type="text"
            value={input}
            onChange={(event) => setInput(event.target.value)}
            placeholder="Type something to hash…"
            className="rounded-lg border border-zinc-200 bg-zinc-50 p-2.5 font-mono text-sm font-normal text-zinc-900 outline-none focus:border-teal-500 dark:border-zinc-700 dark:bg-zinc-950/50 dark:text-white"
          />
        </label>

        <div className="grid gap-2">
          <span className="text-xs font-semibold text-zinc-600 dark:text-zinc-300">
            Algorithm
          </span>
          <div className="flex flex-wrap gap-2">
            {ALGORITHMS.map((item) => {
              const active = item.id === algorithmId
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => setAlgorithmId(item.id)}
                  aria-pressed={active}
                  className={`rounded-lg border px-3 py-1.5 text-xs font-semibold transition-colors ${
                    active
                      ? 'border-teal-500 bg-teal-500 text-white'
                      : 'border-zinc-200 bg-white text-zinc-600 hover:border-teal-400 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-300'
                  }`}
                >
                  {item.name}
                </button>
              )
            })}
          </div>
          <p className="text-xs text-zinc-500 dark:text-zinc-400">
            {algorithm.note}
          </p>
        </div>

        {input.length > 0 && (
          <div className="grid gap-3">
            <span className="text-xs font-semibold text-zinc-600 dark:text-zinc-300">
              Flip one bit — pick a character, then a bit
            </span>
            <div className="flex flex-wrap gap-1" role="group" aria-label="Character to flip">
              {Array.from(input).map((char, index) => {
                const active = index === safeCharIndex
                return (
                  <button
                    key={index}
                    type="button"
                    onClick={() => setCharIndex(index)}
                    aria-pressed={active}
                    aria-label={`Character ${index}: ${char === ' ' ? 'space' : char}`}
                    className={`h-8 min-w-8 rounded-md border px-1.5 font-mono text-sm transition-colors ${
                      active
                        ? 'border-teal-500 bg-teal-500 text-white'
                        : 'border-zinc-200 bg-zinc-50 text-zinc-700 hover:border-teal-400 dark:border-zinc-700 dark:bg-zinc-950/50 dark:text-zinc-300'
                    }`}
                  >
                    {char === ' ' ? '␣' : char}
                  </button>
                )
              })}
            </div>
            <div className="flex flex-wrap items-center gap-2" role="group" aria-label="Bit to flip">
              <span className="text-xs text-zinc-500 dark:text-zinc-400">Bit</span>
              {Array.from({ length: 8 }, (_, bit) => {
                const active = bit === bitIndex
                return (
                  <button
                    key={bit}
                    type="button"
                    onClick={() => setBitIndex(bit)}
                    aria-pressed={active}
                    aria-label={`Bit ${bit}`}
                    className={`h-8 w-8 rounded-md border font-mono text-xs transition-colors ${
                      active
                        ? 'border-teal-500 bg-teal-500 text-white'
                        : 'border-zinc-200 bg-zinc-50 text-zinc-700 hover:border-teal-400 dark:border-zinc-700 dark:bg-zinc-950/50 dark:text-zinc-300'
                    }`}
                  >
                    {bit}
                  </button>
                )
              })}
            </div>
            <p className="font-mono text-xs text-zinc-500 dark:text-zinc-400">
              original: <span className="text-zinc-700 dark:text-zinc-200">{JSON.stringify(input)}</span>
              {'  →  '}
              flipped: <span className="text-teal-600 dark:text-teal-400">{JSON.stringify(flippedInput)}</span>
            </p>
          </div>
        )}
      </section>

      {(error || workerError) && (
        <div
          role="alert"
          className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-900/40 dark:bg-red-950/20"
        >
          <div className="flex gap-3">
            <svg
              className="mt-0.5 h-5 w-5 shrink-0 text-red-500 dark:text-red-400"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              aria-hidden="true"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
            <div>
              <h3 className="text-sm font-bold text-red-800 dark:text-red-300">Computation Error</h3>
              <p className="mt-1 text-sm text-red-700 dark:text-red-400">
                {error || workerError?.message || workerError?.code || 'The cipher worker reported an error.'}
              </p>
            </div>
          </div>
        </div>
      )}

      <section
        ref={resultRef}
        tabIndex={-1}
        aria-label="Avalanche results"
        aria-busy={loading}
        className="space-y-6 outline-none"
      >
        {loading && !hasResult && (
          <p className="text-sm text-zinc-500 dark:text-zinc-400">Computing…</p>
        )}

        {hasResult && stats && (
          <>
            <div className="grid gap-4 rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-zinc-900/40">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                  <h2 className="text-lg font-bold text-zinc-950 dark:text-white">
                    Hamming distance
                  </h2>
                  <span
                    className={`rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide ${securityStyles[algorithm.securityStatus]}`}
                  >
                    {algorithm.securityStatus}
                  </span>
                </div>
                <p className="font-mono text-sm text-zinc-600 dark:text-zinc-300">
                  {stats.changedBits} / {stats.totalBits} bits changed
                </p>
              </div>

              <div className="grid gap-1.5">
                <div
                  className="relative h-4 w-full overflow-hidden rounded-full bg-zinc-100 dark:bg-zinc-800"
                  role="meter"
                  aria-label="Percentage of output bits changed"
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-valuenow={Math.round(percent)}
                  aria-valuetext={`${percent.toFixed(1)}% of bits changed`}
                >
                  <div
                    className={`h-full rounded-full transition-all ${meterTone(percent)}`}
                    style={{ width: `${percent}%` }}
                  />
                  {/* Marker for the ideal 50% target. */}
                  <div className="absolute inset-y-0 left-1/2 w-px -translate-x-1/2 bg-zinc-400 dark:bg-zinc-500" />
                </div>
                <div className="flex items-center justify-between text-xs text-zinc-500 dark:text-zinc-400">
                  <span className="font-mono text-base font-bold text-zinc-900 dark:text-white">
                    {percent.toFixed(1)}%
                  </span>
                  <span>ideal ≈ 50%</span>
                </div>
              </div>
            </div>

            <div className="grid gap-4 rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-zinc-900/40">
              <div className="grid gap-2 font-mono text-xs">
                <p className="break-all text-zinc-500 dark:text-zinc-400">
                  <span className="font-semibold text-zinc-700 dark:text-zinc-200">original </span>
                  {originalOutput}
                </p>
                <p className="break-all text-zinc-500 dark:text-zinc-400">
                  <span className="font-semibold text-zinc-700 dark:text-zinc-200">flipped  </span>
                  {modifiedOutput}
                </p>
              </div>
              <div>
                <h3 className="mb-3 text-sm font-semibold text-zinc-700 dark:text-zinc-200">
                  Byte heatmap
                  <span className="ml-2 font-normal text-zinc-500 dark:text-zinc-400">
                    (highlighted = changed)
                  </span>
                </h3>
                <ByteHeatmap bytes={cells} label="Output byte diff heatmap" />
              </div>
            </div>
          </>
        )}
      </section>
    </div>
  )
}

"use client";

import { useState, useMemo } from "react";
import type { AlgorithmDiff } from "@/lib/utils/sessionComparison";
import { Search, ArrowUpDown } from "lucide-react";

interface AlgorithmDiffTableProps {
  algorithmDiffs: AlgorithmDiff[];
  sessionALabel?: string;
  sessionBLabel?: string;
}

type SortField = "cipherName" | "category" | "opsPerSecA" | "opsPerSecB" | "speedupFactor" | "avgTimeDeltaMs";
type SortOrder = "asc" | "desc";

export default function AlgorithmDiffTable({
  algorithmDiffs,
  sessionALabel = "Session A",
  sessionBLabel = "Session B",
}: AlgorithmDiffTableProps) {
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState<string>("all");
  const [sortField, setSortField] = useState<SortField>("speedupFactor");
  const [sortOrder, setSortOrder] = useState<SortOrder>("desc");

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortOrder("desc");
    }
  };

  const filteredAndSorted = useMemo(() => {
    return algorithmDiffs
      .filter((diff) => {
        const matchesSearch =
          diff.cipherName.toLowerCase().includes(searchTerm.toLowerCase()) ||
          diff.cipherId.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory =
          categoryFilter === "all" || diff.category === categoryFilter;
        return matchesSearch && matchesCategory;
      })
      .sort((a, b) => {
        let valA: number | string = 0;
        let valB: number | string = 0;

        switch (sortField) {
          case "cipherName":
            valA = a.cipherName;
            valB = b.cipherName;
            break;
          case "category":
            valA = a.category;
            valB = b.category;
            break;
          case "opsPerSecA":
            valA = a.opsPerSecA ?? -1;
            valB = b.opsPerSecA ?? -1;
            break;
          case "opsPerSecB":
            valA = a.opsPerSecB ?? -1;
            valB = b.opsPerSecB ?? -1;
            break;
          case "speedupFactor":
            valA = a.speedupFactor ?? -1;
            valB = b.speedupFactor ?? -1;
            break;
          case "avgTimeDeltaMs":
            valA = a.avgTimeDeltaMs ?? 0;
            valB = b.avgTimeDeltaMs ?? 0;
            break;
        }

        if (typeof valA === "string" && typeof valB === "string") {
          return sortOrder === "asc"
            ? valA.localeCompare(valB)
            : valB.localeCompare(valA);
        }

        return sortOrder === "asc"
          ? (valA as number) - (valB as number)
          : (valB as number) - (valA as number);
      });
  }, [algorithmDiffs, searchTerm, categoryFilter, sortField, sortOrder]);

  return (
    <div className="space-y-4">
      {/* Controls: Search and Category Filter */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-400" />
          <input
            type="text"
            placeholder="Search cipher algorithm..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full rounded-lg border border-zinc-200 bg-white pl-9 pr-4 py-2 text-sm text-zinc-900 focus:border-teal-500 focus:outline-none dark:border-zinc-800 dark:bg-zinc-900 dark:text-white"
          />
        </div>

        <div className="flex flex-wrap gap-2">
          {["all", "classical", "symmetric", "asymmetric", "hash", "kdf"].map(
            (cat) => (
              <button
                key={cat}
                type="button"
                onClick={() => setCategoryFilter(cat)}
                className={`rounded-lg px-3 py-1.5 text-xs font-semibold capitalize transition-all ${
                  categoryFilter === cat
                    ? "bg-teal-600 text-white dark:bg-teal-500"
                    : "bg-zinc-100 text-zinc-600 hover:bg-zinc-200 dark:bg-zinc-800 dark:text-zinc-400 dark:hover:bg-zinc-700"
                }`}
              >
                {cat}
              </button>
            ),
          )}
        </div>
      </div>

      {/* Comparison Grid Table */}
      <div className="overflow-x-auto rounded-xl border border-zinc-200 bg-white shadow-sm dark:border-zinc-800 dark:bg-zinc-900">
        <table className="w-full text-left text-sm">
          <thead className="border-b border-zinc-200 bg-zinc-50 font-semibold text-zinc-600 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-300">
            <tr>
              <th
                onClick={() => handleSort("cipherName")}
                className="cursor-pointer px-4 py-3.5 hover:text-teal-600 dark:hover:text-teal-400"
              >
                <div className="flex items-center gap-1.5">
                  <span>Algorithm</span>
                  <ArrowUpDown className="h-3.5 w-3.5" />
                </div>
              </th>
              <th
                onClick={() => handleSort("category")}
                className="cursor-pointer px-4 py-3.5 hover:text-teal-600 dark:hover:text-teal-400"
              >
                Category
              </th>
              <th
                onClick={() => handleSort("opsPerSecA")}
                className="cursor-pointer px-4 py-3.5 text-right hover:text-teal-600 dark:hover:text-teal-400"
              >
                {sessionALabel} (ops/s)
              </th>
              <th
                onClick={() => handleSort("opsPerSecB")}
                className="cursor-pointer px-4 py-3.5 text-right hover:text-teal-600 dark:hover:text-teal-400"
              >
                {sessionBLabel} (ops/s)
              </th>
              <th
                onClick={() => handleSort("speedupFactor")}
                className="cursor-pointer px-4 py-3.5 text-center hover:text-teal-600 dark:hover:text-teal-400"
              >
                <div className="flex items-center justify-center gap-1.5">
                  <span>Speedup Delta</span>
                  <ArrowUpDown className="h-3.5 w-3.5" />
                </div>
              </th>
              <th
                onClick={() => handleSort("avgTimeDeltaMs")}
                className="cursor-pointer px-4 py-3.5 text-right hover:text-teal-600 dark:hover:text-teal-400"
              >
                Avg Latency (ms)
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800">
            {filteredAndSorted.length === 0 ? (
              <tr>
                <td
                  colSpan={6}
                  className="px-4 py-8 text-center text-sm text-zinc-500 dark:text-zinc-400"
                >
                  No algorithms match the selected search or filter criteria.
                </td>
              </tr>
            ) : (
              filteredAndSorted.map((diff) => {
                const isFaster = diff.status === "faster";
                const isSlower = diff.status === "slower";
                const isSimilar = diff.status === "similar";

                return (
                  <tr
                    key={diff.cipherId}
                    className="transition-colors hover:bg-zinc-50/80 dark:hover:bg-zinc-800/40"
                  >
                    <td className="px-4 py-3 font-semibold text-zinc-900 dark:text-white">
                      <div className="flex items-center gap-2">
                        <span>{diff.cipherName}</span>
                        {diff.resultB?.implementation && (
                          <span className="rounded bg-zinc-100 px-1.5 py-0.5 text-[10px] font-mono font-normal text-zinc-600 dark:bg-zinc-800 dark:text-zinc-400">
                            {diff.resultB.implementation}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-xs capitalize text-zinc-500 dark:text-zinc-400">
                      <span
                        className={`inline-block rounded-full px-2 py-0.5 font-medium ${
                          diff.category === "classical"
                            ? "bg-teal-50 text-teal-700 dark:bg-teal-950/40 dark:text-teal-300"
                            : diff.category === "symmetric"
                              ? "bg-blue-50 text-blue-700 dark:bg-blue-950/40 dark:text-blue-300"
                              : diff.category === "asymmetric"
                                ? "bg-pink-50 text-pink-700 dark:bg-pink-950/40 dark:text-pink-300"
                                : diff.category === "hash"
                                  ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300"
                                  : "bg-purple-50 text-purple-700 dark:bg-purple-950/40 dark:text-purple-300"
                        }`}
                      >
                        {diff.category}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right font-mono text-xs text-zinc-700 dark:text-zinc-300">
                      {diff.opsPerSecA !== null
                        ? diff.opsPerSecA.toLocaleString(undefined, {
                            maximumFractionDigits: 1,
                          })
                        : "—"}
                    </td>
                    <td className="px-4 py-3 text-right font-mono text-xs font-semibold text-zinc-900 dark:text-white">
                      {diff.opsPerSecB !== null
                        ? diff.opsPerSecB.toLocaleString(undefined, {
                            maximumFractionDigits: 1,
                          })
                        : "—"}
                    </td>
                    <td className="px-4 py-3 text-center">
                      {diff.speedupFactor !== null ? (
                        <span
                          className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-bold font-mono ${
                            isFaster
                              ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-300"
                              : isSlower
                                ? "bg-rose-100 text-rose-800 dark:bg-rose-950/60 dark:text-rose-300"
                                : "bg-zinc-100 text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300"
                          }`}
                        >
                          {diff.speedupFactor.toFixed(2)}x
                          {diff.opsPerSecDeltaPercent !== null && (
                            <span className="text-[10px] opacity-80">
                              ({diff.opsPerSecDeltaPercent > 0 ? "+" : ""}
                              {diff.opsPerSecDeltaPercent.toFixed(0)}%)
                            </span>
                          )}
                        </span>
                      ) : (
                        <span className="text-xs text-zinc-400">N/A</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-right font-mono text-xs text-zinc-600 dark:text-zinc-400">
                      {diff.avgTimeA !== null && diff.avgTimeB !== null ? (
                        <div>
                          <span>
                            {diff.avgTimeB.toFixed(3)} ms
                          </span>
                          <div className="text-[10px] text-zinc-400">
                            vs {diff.avgTimeA.toFixed(3)} ms
                          </div>
                        </div>
                      ) : (
                        "—"
                      )}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client'

import React, { useMemo, useCallback, useState, useEffect, useRef } from 'react'
import { BenchmarkResult } from '@/types/benchmark'
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  LineChart,
  Line,
  ScatterChart,
  Scatter,
  LabelList,
  Cell,
  Brush,
} from 'recharts'

const getCategoryColor = (category: string) => {
  switch (category) {
    case 'classical':
      return '#0d9488' // Teal-600
    case 'symmetric':
      return '#2563eb' // Blue-600
    case 'asymmetric':
      return '#db2777' // Pink-600
    case 'hash':
      return '#16a34a' // Green-600
    default:
      return '#7c3aed' // Purple-600
  }
}

interface TooltipPayloadItem {
  payload: {
    name: string
    fullName: string
    category: string
    avgTime: number
    minTime: number
    maxTime: number
    opsPerSec: number
    workerExecutionTime?: number
    memoryUsage?: number
  }
}

interface CustomChartTooltipProps {
  active?: boolean
  payload?: TooltipPayloadItem[]
  label?: string
}

const CustomChartTooltip = ({ active, payload, label }: CustomChartTooltipProps) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload
    if (!data) return null
    return (
      <div className="rounded-xl border border-zinc-200 bg-white/95 p-4 shadow-xl backdrop-blur-md dark:border-zinc-800 dark:bg-zinc-950/95 font-sans min-w-[220px]">
        <div className="flex items-center justify-between gap-3 border-b border-zinc-100 pb-2 mb-2 dark:border-zinc-800">
          <p className="font-bold text-zinc-900 dark:text-white text-sm truncate max-w-[130px]">
            {data.fullName || label}
          </p>
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full capitalize ${
            data.category === 'classical' ? 'bg-teal-100 text-teal-800 dark:bg-teal-900/30 dark:text-teal-400' :
            data.category === 'symmetric' ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400' :
            data.category === 'asymmetric' ? 'bg-pink-100 text-pink-800 dark:bg-pink-900/30 dark:text-pink-400' :
            'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400'
          }`}>
            {data.category}
          </span>
        </div>
        <div className="space-y-1.5 text-xs">
          <div className="flex justify-between gap-4">
            <span className="text-zinc-500 dark:text-zinc-400 font-sans">Avg Time:</span>
            <span className="font-mono font-semibold text-zinc-900 dark:text-zinc-100">
              {data.avgTime !== undefined ? `${data.avgTime.toFixed(4)} ms` : 'N/A'}
            </span>
          </div>
          <div className="flex justify-between gap-4">
            <span className="text-zinc-500 dark:text-zinc-400 font-sans">Min / Max:</span>
            <span className="font-mono text-zinc-700 dark:text-zinc-300">
              {data.minTime !== undefined ? `${data.minTime.toFixed(4)}` : 'N/A'} / {data.maxTime !== undefined ? `${data.maxTime.toFixed(4)} ms` : 'N/A'}
            </span>
          </div>
          <div className="flex justify-between gap-4 border-t border-zinc-100 pt-1.5 mt-1.5 dark:border-zinc-800">
            <span className="text-zinc-500 dark:text-zinc-400 font-sans">Throughput:</span>
            <span className="font-bold text-teal-600 dark:text-teal-400">
              {data.opsPerSec !== undefined ? `${data.opsPerSec.toLocaleString()} ops/s` : 'N/A'}
            </span>
          </div>
          {data.workerExecutionTime !== undefined && (
            <div className="flex justify-between gap-4">
              <span className="text-zinc-500 dark:text-zinc-400 font-sans">Worker RTT:</span>
              <span className="font-mono text-zinc-700 dark:text-zinc-300">
                {data.workerExecutionTime.toFixed(4)} ms
              </span>
            </div>
          )}
          {data.memoryUsage !== undefined && (
            <div className="flex justify-between gap-4">
              <span className="text-zinc-500 dark:text-zinc-400 font-sans">Mem Growth:</span>
              <span className="font-mono text-zinc-700 dark:text-zinc-300">
                {data.memoryUsage > 1024 * 1024
                  ? `${(data.memoryUsage / (1024 * 1024)).toFixed(2)} MB`
                  : data.memoryUsage > 1024
                  ? `${(data.memoryUsage / 1024).toFixed(1)} KB`
                  : `${data.memoryUsage.toFixed(0)} B`}
              </span>
            </div>
          )}
        </div>
      </div>
    )
  }
  return null
}

interface ComparisonChartProps {
  results: BenchmarkResult[]
  chartType?: 'bar' | 'line' | 'scatter'
}

export default React.memo(function ComparisonChart({
  results,
  chartType = 'bar',
}: ComparisonChartProps) {
  const chartRef = useRef<HTMLDivElement>(null)
  const [isDark, setIsDark] = useState(false)
  const [activeKeys, setActiveKeys] = useState<Record<string, boolean>>({
    avgTime: true,
    minTime: true,
    maxTime: true,
  })
  const [activeCategories, setActiveCategories] = useState<Record<string, boolean>>({
    classical: true,
    symmetric: true,
    asymmetric: true,
    hash: true,
  })

  // Track isDark class changes
  useEffect(() => {
    const syncTheme = () => {
      setIsDark(document.documentElement.classList.contains('dark'))
    }
    syncTheme()
    const observer = new MutationObserver(syncTheme)
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class'],
    })
    return () => observer.disconnect()
  }, [])

  const chartData = useMemo(() => results.map((result) => ({
    name: result.cipherName.substring(0, 15), // Truncate long names
    avgTime: parseFloat(result.averageTime.toFixed(4)),
    minTime: parseFloat(result.minTime.toFixed(4)),
    maxTime: parseFloat(result.maxTime.toFixed(4)),
    opsPerSec: parseFloat(result.operationsPerSecond.toFixed(0)),
    fullName: result.cipherName,
    category: result.category,
    workerExecutionTime: result.workerExecutionTime,
    memoryUsage: result.memoryUsage,
  })), [results])

  const sortedData = useMemo(() => [...chartData].sort((a, b) => a.avgTime - b.avgTime), [chartData])

  const filteredData = useMemo(() => {
    return sortedData.filter((item) => activeCategories[item.category] !== false)
  }, [sortedData, activeCategories])

  const toggleCategory = useCallback((category: string) => {
    setActiveCategories((prev) => ({
      ...prev,
      [category]: !prev[category],
    }))
  }, [])

  const toggleKey = useCallback((key: string) => {
    setActiveKeys((prev) => ({
      ...prev,
      [key]: !prev[key],
    }))
  }, [])

  const handleExport = useCallback((format: 'png' | 'svg') => {
    if (!chartRef.current) return
    const svgElement = chartRef.current.querySelector('svg')
    if (!svgElement) return

    const width = svgElement.clientWidth || 800
    const height = svgElement.clientHeight || 450

    // Clone SVG Node
    const svgClone = svgElement.cloneNode(true) as SVGElement
    if (!svgClone.getAttribute('xmlns')) {
      svgClone.setAttribute('xmlns', 'http://www.w3.org/2000/svg')
    }

    svgClone.setAttribute('width', width.toString())
    svgClone.setAttribute('height', height.toString())
    svgClone.setAttribute('viewBox', `0 0 ${width} ${height}`)

    const isDarkTheme = document.documentElement.classList.contains('dark')
    const bgColor = isDarkTheme ? '#09090b' : '#ffffff'
    const fgColor = isDarkTheme ? '#e4e4e7' : '#27272a'
    const gridColor = isDarkTheme ? '#27272a' : '#e4e4e7'

    // Add background rectangle
    const bgRect = document.createElementNS('http://www.w3.org/2000/svg', 'rect')
    bgRect.setAttribute('width', '100%')
    bgRect.setAttribute('height', '100%')
    bgRect.setAttribute('fill', bgColor)
    svgClone.insertBefore(bgRect, svgClone.firstChild)

    // Inject SVG Inline Styles for correct colors outside the browser context
    const styleElement = document.createElementNS('http://www.w3.org/2000/svg', 'style')
    styleElement.textContent = `
      svg { background-color: ${bgColor}; font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
      text { fill: ${fgColor} !important; font-size: 10px; }
      .recharts-text { fill: ${fgColor} !important; }
      .recharts-cartesian-axis-line { stroke: ${gridColor} !important; }
      .recharts-cartesian-axis-tick-line { stroke: ${gridColor} !important; }
      .recharts-cartesian-grid-horizontal line, .recharts-cartesian-grid-vertical line { stroke: ${isDarkTheme ? '#18181b' : '#f4f4f5'} !important; stroke-opacity: 0.8; }
      .recharts-brush-slide { fill: ${isDarkTheme ? '#27272a' : '#e4e4e7'} !important; fill-opacity: 0.15; }
      .recharts-brush-traveller rect { fill: ${isDarkTheme ? '#52525b' : '#a1a1aa'} !important; }
      .recharts-label-list text { fill: ${isDarkTheme ? '#a1a1aa' : '#71717a'} !important; font-size: 9px; font-weight: 500; }
    `
    svgClone.appendChild(styleElement)

    const svgString = new XMLSerializer().serializeToString(svgClone)
    const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' })
    const svgUrl = URL.createObjectURL(svgBlob)
    const filename = `cryptoviz-benchmark-chart-${Date.now()}`

    if (format === 'svg') {
      const downloadLink = document.createElement('a')
      downloadLink.href = svgUrl
      downloadLink.download = `${filename}.svg`
      document.body.appendChild(downloadLink)
      downloadLink.click()
      document.body.removeChild(downloadLink)
      URL.revokeObjectURL(svgUrl)
    } else {
      const image = new Image()
      image.onload = () => {
        const canvas = document.createElement('canvas')
        canvas.width = width
        canvas.height = height
        const context = canvas.getContext('2d')
        if (context) {
          context.fillStyle = bgColor
          context.fillRect(0, 0, width, height)
          context.drawImage(image, 0, 0)
          try {
            const pngUrl = canvas.toDataURL('image/png')
            const downloadLink = document.createElement('a')
            downloadLink.href = pngUrl
            downloadLink.download = `${filename}.png`
            document.body.appendChild(downloadLink)
            downloadLink.click()
            document.body.removeChild(downloadLink)
          } catch (err) {
            console.error('Error generating PNG:', err)
          }
        }
        URL.revokeObjectURL(svgUrl)
      }
      image.onerror = (e) => {
        console.error('Image load error for PNG:', e)
        URL.revokeObjectURL(svgUrl)
      }
      image.src = svgUrl
    }
  }, [])

  const gridStroke = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)'
  const textColor = isDark ? '#a1a1aa' : '#71717a'
  const brushStroke = isDark ? '#27272a' : '#e4e4e7'
  const brushFill = isDark ? '#09090b' : '#fafafa'

  const renderChart = useCallback(() => {
    if (filteredData.length === 0) {
      return (
        <div className="flex h-full items-center justify-center">
          <p className="text-sm text-zinc-500 dark:text-zinc-400 italic font-sans">
            No algorithms to display. Toggle categories in the legend below to show data.
          </p>
        </div>
      )
    }

    switch (chartType) {
      case 'line':
        return (
          <LineChart data={filteredData} margin={{ top: 15, right: 15, left: 10, bottom: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
            <XAxis
              dataKey="name"
              stroke={textColor}
              fontSize={10}
              tickLine={false}
              axisLine={false}
              dy={8}
              angle={-45}
              textAnchor="end"
              height={65}
            />
            <YAxis
              stroke={textColor}
              fontSize={10}
              tickLine={false}
              axisLine={false}
              tickFormatter={(val) => `${val}ms`}
            />
            <Tooltip content={<CustomChartTooltip />} />
            {activeKeys.avgTime && (
              <Line
                type="monotone"
                dataKey="avgTime"
                stroke="#14b8a6"
                name="Average Time"
                dot={{ fill: '#14b8a6', r: 3 }}
                activeDot={{ r: 6 }}
              />
            )}
            {activeKeys.minTime && (
              <Line
                type="monotone"
                dataKey="minTime"
                stroke="#22c55e"
                name="Min Time"
                strokeDasharray="5 5"
                dot={{ fill: '#22c55e', r: 2 }}
              />
            )}
            {activeKeys.maxTime && (
              <Line
                type="monotone"
                dataKey="maxTime"
                stroke="#ef4444"
                name="Max Time"
                strokeDasharray="5 5"
                dot={{ fill: '#ef4444', r: 2 }}
              />
            )}
            {filteredData.length > 4 && (
              <Brush
                dataKey="name"
                height={26}
                stroke={brushStroke}
                fill={brushFill}
                className="text-[10px] text-zinc-500 font-sans"
                travellerWidth={8}
              />
            )}
          </LineChart>
        )

      case 'scatter':
        return (
          <ScatterChart margin={{ top: 20, right: 20, bottom: 25, left: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
            <XAxis
              type="number"
              dataKey="opsPerSec"
              name="Ops/Second"
              stroke={textColor}
              fontSize={10}
              tickLine={false}
              axisLine={false}
              domain={['auto', 'auto']}
              tickFormatter={(val) =>
                val >= 1000000
                  ? `${(val / 1000000).toFixed(1)}M`
                  : val >= 1000
                  ? `${(val / 1000).toFixed(1)}k`
                  : val.toString()
              }
            />
            <YAxis
              type="number"
              dataKey="avgTime"
              name="Avg Time (ms)"
              stroke={textColor}
              fontSize={10}
              tickLine={false}
              axisLine={false}
              domain={['auto', 'auto']}
              tickFormatter={(val) => `${val}ms`}
            />
            <Tooltip content={<CustomChartTooltip />} cursor={{ strokeDasharray: '3 3' }} />
            <Scatter name="Algorithms" data={filteredData} fill="#14b8a6">
              {filteredData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={getCategoryColor(entry.category)} />
              ))}
              <LabelList
                dataKey="name"
                position="top"
                offset={10}
                style={{ fill: textColor, fontSize: '9px', fontWeight: 500 }}
              />
            </Scatter>
            {filteredData.length > 4 && (
              <Brush
                dataKey="name"
                height={26}
                stroke={brushStroke}
                fill={brushFill}
                className="text-[10px] text-zinc-500 font-sans"
                travellerWidth={8}
              />
            )}
          </ScatterChart>
        )

      default:
        return (
          <BarChart data={filteredData} margin={{ top: 15, right: 15, left: 10, bottom: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
            <XAxis
              dataKey="name"
              stroke={textColor}
              fontSize={10}
              tickLine={false}
              axisLine={false}
              dy={8}
              angle={-45}
              textAnchor="end"
              height={65}
            />
            <YAxis
              stroke={textColor}
              fontSize={10}
              tickLine={false}
              axisLine={false}
              tickFormatter={(val) => `${val}ms`}
            />
            <Tooltip content={<CustomChartTooltip />} />
            {activeKeys.avgTime && (
              <Bar dataKey="avgTime" fill="#14b8a6" name="Average Time" radius={[4, 4, 0, 0]} />
            )}
            {activeKeys.minTime && (
              <Bar dataKey="minTime" fill="#22c55e" name="Min Time" radius={[4, 4, 0, 0]} />
            )}
            {activeKeys.maxTime && (
              <Bar dataKey="maxTime" fill="#ef4444" name="Max Time" radius={[4, 4, 0, 0]} />
            )}
            {filteredData.length > 4 && (
              <Brush
                dataKey="name"
                height={26}
                stroke={brushStroke}
                fill={brushFill}
                className="text-[10px] text-zinc-500 font-sans"
                travellerWidth={8}
              />
            )}
          </BarChart>
        )
    }
  }, [chartType, filteredData, activeKeys, activeCategories, gridStroke, textColor, brushStroke, brushFill])

  if (results.length === 0) {
    return (
      <div className="flex h-80 items-center justify-center rounded-lg border border-zinc-200 bg-white dark:border-zinc-800 dark:bg-zinc-900">
        <p className="text-zinc-500 dark:text-zinc-400 font-sans">No data to display. Run a benchmark first.</p>
      </div>
    )
  }

  return (
    <div
      ref={chartRef}
      className="space-y-4 rounded-xl border border-zinc-200 bg-white p-6 shadow-sm transition-all duration-300 dark:border-zinc-800 dark:bg-zinc-900"
    >
      <div className="flex flex-wrap items-center justify-between gap-4">
        <h3 className="text-lg font-semibold text-zinc-900 dark:text-white font-sans">
          Performance Comparison
        </h3>
        <div className="flex items-center gap-2">
          <span className="text-[11px] text-zinc-500 dark:text-zinc-400 font-sans mr-1">
            Export Chart:
          </span>
          <button
