"use client";

import { useMemo, useState, useEffect } from "react";
import type { BenchmarkSession } from "@/types/benchmark";
import {
  computeSessionComparison,
  type SessionPreset,
} from "@/lib/utils/sessionComparison";
import SessionDeltaCard from "./SessionDeltaCard";
import AlgorithmDiffTable from "./AlgorithmDiffTable";
import SessionEnvironmentComparison from "./SessionEnvironmentComparison";
import EducationalSessionInsights from "./EducationalSessionInsights";
import SessionPresetSelector from "./SessionPresetSelector";
import SessionExportImport from "./SessionExportImport";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";
import { BarChart3, Layers, Sliders, HelpCircle } from "lucide-react";

interface SessionComparisonVisualizerProps {
  sessionA: BenchmarkSession;
  sessionB: BenchmarkSession;
  sessionALabel?: string;
  sessionBLabel?: string;
  onImportSession?: (session: BenchmarkSession) => void;
}

export default function SessionComparisonVisualizer({
  sessionA: initialSessionA,
  sessionB: initialSessionB,
  sessionALabel = "Session A (Baseline)",
  sessionBLabel = "Session B (Candidate)",
  onImportSession,
}: SessionComparisonVisualizerProps) {
  const [currentSessionA, setCurrentSessionA] = useState<BenchmarkSession>(initialSessionA);
  const [currentSessionB, setCurrentSessionB] = useState<BenchmarkSession>(initialSessionB);
  const [activePresetId, setActivePresetId] = useState<string | undefined>(undefined);
  const [activeMetric, setActiveMetric] = useState<"throughput" | "latency" | "worker" | "memory">("throughput");
  const [activeTab, setActiveTab] = useState<"charts" | "table" | "environment" | "educational">("charts");

  // Keep state synced if props change
  useEffect(() => {
    setCurrentSessionA(initialSessionA);
    setCurrentSessionB(initialSessionB);
  }, [initialSessionA, initialSessionB]);

  const delta = useMemo(
    () => computeSessionComparison(currentSessionA, currentSessionB),
    [currentSessionA, currentSessionB],
  );

  const handleSelectPreset = (preset: SessionPreset) => {
    setCurrentSessionA(preset.sessionA);
    setCurrentSessionB(preset.sessionB);
    setActivePresetId(preset.id);
  };

  // Prepare recharts comparison data
  const chartData = useMemo(() => {
    return delta.algorithmDiffs.map((diff) => ({
      name: diff.cipherName,
      category: diff.category,
      sessionA_ops: diff.opsPerSecA || 0,
      sessionB_ops: diff.opsPerSecB || 0,
      sessionA_time: diff.avgTimeA || 0,
      sessionB_time: diff.avgTimeB || 0,
      sessionA_worker: diff.resultA?.workerExecutionTime || 0,
      sessionB_worker: diff.resultB?.workerExecutionTime || 0,
      sessionA_memory: (diff.resultA?.memoryUsage || 0) / 1024,
      sessionB_memory: (diff.resultB?.memoryUsage || 0) / 1024,
      speedup: diff.speedupFactor || 1,
    }));
  }, [delta]);

  return (
    <div className="space-y-6 rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-zinc-950">
      {/* Header & Presets */}
      <div className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-zinc-100 pb-4 dark:border-zinc-800">
          <div>
            <span className="text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400">
              Interactive Benchmark Module
            </span>
            <h2 className="text-2xl font-bold tracking-tight text-zinc-900 dark:text-white">
              Compare Benchmarks Across Sessions
            </h2>
            <p className="mt-1 text-sm text-zinc-500 dark:text-zinc-400">
              Analyze throughput speedups, execution latency deltas, thread IPC performance, and hardware acceleration across benchmark runs.
            </p>
          </div>

          {/* Navigation Sub-Tabs */}
          <div className="flex flex-wrap gap-1 rounded-xl bg-zinc-100 p-1 dark:bg-zinc-900">
            {[
              { id: "charts", label: "Comparison Charts", icon: BarChart3 },
              { id: "table", label: "Algorithm Diff Grid", icon: Layers },
              { id: "environment", label: "Environmental Specs", icon: Sliders },
              { id: "educational", label: "Educational Insights", icon: HelpCircle },
            ].map((tab) => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.id;
              return (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setActiveTab(tab.id as any)}
                  className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold transition-all ${
                    isActive
                      ? "bg-white text-teal-700 shadow-sm dark:bg-zinc-800 dark:text-teal-300"
                      : "text-zinc-600 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white"
                  }`}
                >
                  <Icon className="h-3.5 w-3.5" />
                  <span>{tab.label}</span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Preset Selector */}
        <SessionPresetSelector
          onSelectPreset={handleSelectPreset}
          activePresetId={activePresetId}
        />
      </div>

      {/* Top Cards: Delta Summary */}
      <SessionDeltaCard
        delta={delta}
        sessionALabel={sessionALabel}
        sessionBLabel={sessionBLabel}
      />

      {/* Export / Import Toolbar */}
      <SessionExportImport
        sessionA={currentSessionA}
        sessionB={currentSessionB}
        onImportSession={(imported) => {
          setCurrentSessionB(imported);
          setActivePresetId(undefined);
          if (onImportSession) onImportSession(imported);
        }}
      />

      {/* Main Workspace Tabs */}
      {activeTab === "charts" && (
        <div className="space-y-4">
          {/* Metric selector bar */}
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-zinc-100 bg-zinc-50/80 p-3 dark:border-zinc-800/80 dark:bg-zinc-900/60">
            <span className="text-xs font-semibold text-zinc-700 dark:text-zinc-300">
              Select Chart Metric:
            </span>
            <div className="flex flex-wrap gap-2">
              {[
                { id: "throughput", label: "Throughput (ops/sec)" },
                { id: "latency", label: "Cipher Time (ms)" },
                { id: "worker", label: "Worker RTT (ms)" },
                { id: "memory", label: "Memory Usage (KB)" },
              ].map((metric) => (
                <button
                  key={metric.id}
                  type="button"
                  onClick={() => setActiveMetric(metric.id as any)}
                  className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-all ${
                    activeMetric === metric.id
                      ? "bg-teal-600 text-white dark:bg-teal-500"
                      : "bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100 dark:bg-zinc-800 dark:border-zinc-700 dark:text-zinc-300 dark:hover:bg-zinc-700"
                  }`}
                >
                  {metric.label}
                </button>
              ))}
            </div>
          </div>

          {/* Recharts Bar Chart */}
          <div className="h-80 w-full rounded-xl border border-zinc-200 bg-white p-4 shadow-sm dark:border-zinc-800 dark:bg-zinc-900">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 10, bottom: 25 }}
              >
                <CartesianGrid strokeDasharray="3 3" opacity={0.2} />
                <XAxis
                  dataKey="name"
                  tick={{ fontSize: 11 }}
                  interval={0}
                  angle={-15}
                  textAnchor="end"
                />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: "rgba(15, 23, 42, 0.95)",
                    borderColor: "#334155",
                    borderRadius: "0.75rem",
                    color: "#fff",
                    fontSize: "12px",
                  }}
                />
                <Legend wrapperStyle={{ paddingTop: "10px", fontSize: "12px" }} />
                <Bar
                  dataKey={
                    activeMetric === "throughput"
                      ? "sessionA_ops"
                      : activeMetric === "latency"
                        ? "sessionA_time"
                        : activeMetric === "worker"
                          ? "sessionA_worker"
                          : "sessionA_memory"
                  }
                  name={sessionALabel}
                  fill="#94a3b8"
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  dataKey={
                    activeMetric === "throughput"
                      ? "sessionB_ops"
                      : activeMetric === "latency"
                        ? "sessionB_time"
                        : activeMetric === "worker"
                          ? "sessionB_worker"
                          : "sessionB_memory"
                  }
                  name={sessionBLabel}
                  fill="#0d9488"
                  radius={[4, 4, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {activeTab === "table" && (
        <AlgorithmDiffTable
          algorithmDiffs={delta.algorithmDiffs}
          sessionALabel={sessionALabel}
          sessionBLabel={sessionBLabel}
        />
      )}

      {activeTab === "environment" && (
        <SessionEnvironmentComparison
          sessionA={currentSessionA}
          sessionB={currentSessionB}
          sessionALabel={sessionALabel}
          sessionBLabel={sessionBLabel}
        />
      )}

      {activeTab === "educational" && (
        <EducationalSessionInsights delta={delta} />
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import type { BenchmarkSession } from "@/types/benchmark";
import {
  exportSessionComparisonJSON,
  exportSessionComparisonCSV,
} from "@/lib/utils/sessionComparison";
import { Download, Upload, FileCode, FileSpreadsheet, Check, AlertCircle } from "lucide-react";

interface SessionExportImportProps {
  sessionA: BenchmarkSession;
  sessionB: BenchmarkSession;
  onImportSession?: (session: BenchmarkSession) => void;
}

export default function SessionExportImport({
  sessionA,
  sessionB,
  onImportSession,
}: SessionExportImportProps) {
  const [copiedFormat, setCopiedFormat] = useState<"json" | "csv" | null>(null);
  const [importError, setImportError] = useState<string | null>(null);
  const [importSuccess, setImportSuccess] = useState<string | null>(null);

  const downloadFile = (content: string, filename: string, mime: string) => {
    const blob = new Blob([content], { type: mime });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportJSON = () => {
    const json = exportSessionComparisonJSON(sessionA, sessionB);
    downloadFile(
      json,
      `cryptoviz-benchmark-comparison-${Date.now()}.json`,
      "application/json",
    );
    setCopiedFormat("json");
    setTimeout(() => setCopiedFormat(null), 2000);
  };

  const handleExportCSV = () => {
    const csv = exportSessionComparisonCSV(sessionA, sessionB);
    downloadFile(
      csv,
      `cryptoviz-benchmark-comparison-${Date.now()}.csv`,
      "text/csv",
    );
    setCopiedFormat("csv");
    setTimeout(() => setCopiedFormat(null), 2000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setImportError(null);
    setImportSuccess(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const parsed = JSON.parse(text);

        // Check if file is a direct BenchmarkSession or exported session report
        let importedSession: BenchmarkSession | null = null;

        if (parsed.id && Array.isArray(parsed.results)) {
          importedSession = parsed as BenchmarkSession;
        } else if (parsed.sessionB && Array.isArray(parsed.sessionB.results)) {
          importedSession = parsed.sessionB as BenchmarkSession;
        }

        if (!importedSession) {
          throw new Error("Invalid session format. Missing session ID or results array.");
        }

        importedSession.timestamp = new Date(importedSession.timestamp);
        importedSession.results = importedSession.results.map((r: any) => ({
          ...r,
          timestamp: new Date(r.timestamp),
        }));

        if (onImportSession) {
          onImportSession(importedSession);
          setImportSuccess(`Successfully imported session (${importedSession.results.length} ciphers).`);
        }
      } catch (err: any) {
        setImportError(err.message || "Failed to parse benchmark session JSON file.");
      }
    };

    reader.readAsText(file);
  };

  return (
    <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-zinc-200 bg-white p-4 shadow-sm dark:border-zinc-800 dark:bg-zinc-900">
      <div className="flex items-center gap-2">
        <Download className="h-4 w-4 text-teal-600 dark:text-teal-400" />
        <span className="text-xs font-semibold text-zinc-900 dark:text-white">
          Export / Import Benchmark Comparison Report
        </span>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <button
          type="button"
          onClick={handleExportJSON}
          className="flex items-center gap-1.5 rounded-lg border border-zinc-300 px-3 py-1.5 text-xs font-medium text-zinc-700 hover:bg-zinc-50 dark:border-zinc-700 dark:text-zinc-300 dark:hover:bg-zinc-800"
        >
          {copiedFormat === "json" ? (
            <Check className="h-3.5 w-3.5 text-emerald-500" />
          ) : (
            <FileCode className="h-3.5 w-3.5 text-teal-600 dark:text-teal-400" />
          )}
          <span>Export JSON</span>
        </button>

        <button
          type="button"
          onClick={handleExportCSV}
          className="flex items-center gap-1.5 rounded-lg border border-zinc-300 px-3 py-1.5 text-xs font-medium text-zinc-700 hover:bg-zinc-50 dark:border-zinc-700 dark:text-zinc-300 dark:hover:bg-zinc-800"
        >
          {copiedFormat === "csv" ? (
            <Check className="h-3.5 w-3.5 text-emerald-500" />
          ) : (
            <FileSpreadsheet className="h-3.5 w-3.5 text-blue-600 dark:text-blue-400" />
          )}
          <span>Export CSV</span>
        </button>

        {onImportSession && (
          <label className="flex cursor-pointer items-center gap-1.5 rounded-lg bg-teal-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-teal-700 dark:bg-teal-500 dark:hover:bg-teal-600">
            <Upload className="h-3.5 w-3.5" />
            <span>Import Session JSON</span>
            <input
              type="file"
              accept=".json"
              onChange={handleFileUpload}
              className="hidden"
            />
          </label>
        )}
      </div>

      {importError && (
        <div className="w-full flex items-center gap-1.5 rounded-lg bg-rose-50 p-2 text-xs text-rose-700 dark:bg-rose-950/40 dark:text-rose-300">
          <AlertCircle className="h-3.5 w-3.5 shrink-0" />
          <span>{importError}</span>
        </div>
      )}

      {importSuccess && (
        <div className="w-full flex items-center gap-1.5 rounded-lg bg-emerald-50 p-2 text-xs text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">
          <Check className="h-3.5 w-3.5 shrink-0" />
          <span>{importSuccess}</span>
        </div>
      )}
    </div>
  );
}

'use client'

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import { useCipherWorker } from '../../lib/hooks/useCipherWorker'
import { generateChallengeData, type ChallengeData, type ChallengeDifficulty } from '../../lib/challenge/generator'
import { getWrongAnswerExplanation } from '../../lib/challenge/explain'
import { CIPHER_REGISTRY } from '../../lib/cipher/registry'

type FeedbackState = 'idle' | 'correct' | 'incorrect'

export type QuestionCountOption = 5 | 10 | 20
export type TimeLimitOption = 30 | 60 | 120 | 0

const QUESTION_COUNT_OPTIONS: readonly QuestionCountOption[] = [5, 10, 20]
const TIME_LIMIT_OPTIONS: readonly TimeLimitOption[] = [30, 60, 120, 0]

const DEFAULT_QUESTION_COUNT: QuestionCountOption = 10
const DEFAULT_TIME_LIMIT: TimeLimitOption = 60

const XP_BASE_CORRECT = 100
const XP_PENALTY_PER_HINT = 20
const XP_MIN_CORRECT = 10

const HISTORY_CAP = 20
const HISTORY_KEY = 'cryptoviz_challenge_history'
const XP_TOTAL_KEY = 'cryptoviz_xp_total'
const STREAK_COUNT_KEY = 'cryptoviz_streak_count'
const STREAK_LAST_DATE_KEY = 'cryptoviz_streak_last_play_date'
const BEST_SCORE_KEY = 'cryptoviz_best_score'
const QUESTION_COUNT_KEY = 'cryptoviz_challenge_question_count'
const TIME_LIMIT_KEY = 'cryptoviz_challenge_time_limit'

type QuestionRun = {
  cipherId: ChallengeData['cipherId']
  plaintext: string
  key: string
  difficulty: ChallengeData['difficulty']
  correct: boolean
  hintRevealedCount: number
  wrongAttempts: number
  lastExplanation: { title: string; details: string[] }
  earnedXp: number
}

type ChallengeHistoryEntry = {
  id: string
  createdAt: number
  difficulty: ChallengeDifficulty
  xpEarned: number
  accuracy: number // 0..1
  streakAfter: number
  questions: Array<{
    cipherId: QuestionRun['cipherId']
    correct: boolean
    hintRevealedCount: number
    wrongAttempts: number
    earnedXp: number
  }>
}

function formatLocalDateKey(d: Date) {
  const yyyy = d.getFullYear()
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const dd = String(d.getDate()).padStart(2, '0')
  return `${yyyy}-${mm}-${dd}`
}

function parseLocalDateKey(key: string) {
  const [y, m, d] = key.split('-').map((x) => parseInt(x, 10))
  if (!y || !m || !d) return null
  return new Date(y, m - 1, d)
}

function daysBetweenLocalDates(a: Date, b: Date) {
  const a0 = new Date(a.getFullYear(), a.getMonth(), a.getDate())
  const b0 = new Date(b.getFullYear(), b.getMonth(), b.getDate())
  const ms = b0.getTime() - a0.getTime()
  return Math.floor(ms / (24 * 60 * 60 * 1000))
}

function computeEarnedXp(params: {
  wasCorrect: boolean
  hintRevealedCount: number
}) {
  if (!params.wasCorrect) return 0
  const penalty = params.hintRevealedCount * XP_PENALTY_PER_HINT
  const earned = XP_BASE_CORRECT - penalty
  return Math.max(XP_MIN_CORRECT, earned)
}

function safeJsonParse<T>(s: string | null): T | null {
  if (!s) return null
  try {
    return JSON.parse(s) as T
  } catch {
    return null
  }
}

function uid() {
  return Math.random().toString(36).slice(2) + '-' + Date.now().toString(36)
}

export default function ChallengeMode() {
  const { runCipher, loading, error } = useCipherWorker()
  const successTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const sessionPersistedRef = useRef(false)

  const MAX_CIPHERTEXT_RETRIES = 3
  const RETRY_BACKOFF_BASE_MS = 400

  const [cipherRetryCount, setCipherRetryCount] = useState(0)
  const retryTimerRef = useRef<NodeJS.Timeout | null>(null)


  const [difficulty, setDifficulty] = useState<ChallengeDifficulty>('medium')
  const [questionCount, setQuestionCount] = useState<QuestionCountOption>(DEFAULT_QUESTION_COUNT)
  const [timeLimit, setTimeLimit] = useState<TimeLimitOption>(DEFAULT_TIME_LIMIT)
  const [started, setStarted] = useState(false)
  const [replayMode, setReplayMode] = useState(false)

  const [isHydrated, setIsHydrated] = useState(false)

  // Best score (legacy)
  const [bestScore, setBestScore] = useState(0)

  // XP + streak
  const [xpTotal, setXpTotal] = useState(0)
  const [streak, setStreak] = useState(0)

  // Session state
  const [sessionChallenges, setSessionChallenges] = useState<ChallengeData[] | null>(null)
  const [expectedCiphertext, setExpectedCiphertext] = useState('')
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0) // 0..n-1
  const [feedback, setFeedback] = useState<FeedbackState>('idle')
  const [copied, setCopied] = useState(false)

  const [answer, setAnswer] = useState('')
  const [timeLeft, setTimeLeft] = useState<number>(DEFAULT_TIME_LIMIT)

  const [showHintIndex, setShowHintIndex] = useState(0) // 0..n-1 (but reveals hint at index)

  const [questionRuns, setQuestionRuns] = useState<QuestionRun[] | null>(null)
  const [challengeExplanation, setChallengeExplanation] = useState<{ title: string; details: string[] } | null>(null)

  const handleQuestionCountChange = useCallback((count: QuestionCountOption) => {
    setQuestionCount(count)
    localStorage.setItem(QUESTION_COUNT_KEY, String(count))
  }, [])

  const handleTimeLimitChange = useCallback((limit: TimeLimitOption) => {
    setTimeLimit(limit)
    localStorage.setItem(TIME_LIMIT_KEY, String(limit))
  }, [])

  const currentChallenge = useMemo(() => {
    if (!sessionChallenges) return null
    return sessionChallenges[currentQuestionIndex] ?? null
  }, [sessionChallenges, currentQuestionIndex])

  const currentCipherName = useMemo(() => {
    if (!currentChallenge) return 'Cipher'
    return CIPHER_REGISTRY.find((c) => c.id === currentChallenge.cipherId)?.name ?? 'Cipher'
  }, [currentChallenge])

  const progressPercent = useMemo(() => {
    return Math.round((currentQuestionIndex / questionCount) * 100)
  }, [currentQuestionIndex, questionCount])

  // Hydration + persisted values
  useEffect(() => {
    const savedBest = localStorage.getItem(BEST_SCORE_KEY)
    if (savedBest) setBestScore(parseInt(savedBest, 10) || 0)

    const savedXp = localStorage.getItem(XP_TOTAL_KEY)
    if (savedXp) setXpTotal(parseInt(savedXp, 10) || 0)

    const savedStreakCount = localStorage.getItem(STREAK_COUNT_KEY)

    if (savedStreakCount) setStreak(parseInt(savedStreakCount, 10) || 0)

    const savedCount = localStorage.getItem(QUESTION_COUNT_KEY)
    if (savedCount) {
      const val = parseInt(savedCount, 10)
      if (QUESTION_COUNT_OPTIONS.includes(val as QuestionCountOption)) {
        setQuestionCount(val as QuestionCountOption)
      }
    }

    const savedTime = localStorage.getItem(TIME_LIMIT_KEY)
    if (savedTime !== null) {
      const val = parseInt(savedTime, 10)
      if (TIME_LIMIT_OPTIONS.includes(val as TimeLimitOption)) {
        setTimeLimit(val as TimeLimitOption)
      }
    }

    setIsHydrated(true)
  }, [])

  const generateSessionChallenges = useCallback(
    (d: ChallengeDifficulty, count: number) => {
      const arr: ChallengeData[] = []
      for (let i = 0; i < count; i++) {
        arr.push(generateChallengeData(d))
      }
      return arr
    },
    []
  )

  const loadExpectedCiphertextForCurrent = useCallback(async () => {
    if (!currentChallenge) return
    setExpectedCiphertext('')

    try {
      const result = await runCipher('encrypt', currentChallenge.cipherId, currentChallenge.plaintext, currentChallenge.key)
      setExpectedCiphertext(result.output)
    } catch (e) {
      console.error('Worker failed to generate expected ciphertext:', e)
      // `useCipherWorker` already sets `error`; UI will offer retry.
    }
  }, [currentChallenge, runCipher])


  // Load ciphertext when session advances
  useEffect(() => {
    if (!started) return
    if (!currentChallenge) return

    // Reset retry state for the new question
    setCipherRetryCount(0)
    retryTimerRef.current && clearTimeout(retryTimerRef.current)
    retryTimerRef.current = null

    loadExpectedCiphertextForCurrent()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentQuestionIndex, started])


  const advanceQuestion = useCallback(() => {
    setFeedback('idle')
    setChallengeExplanation(null)
    setAnswer('')
    setShowHintIndex(0)
    setTimeLeft(timeLimit)

    setCurrentQuestionIndex((i) => {
      const next = i + 1
      return next
    })
  }, [timeLimit])

  // Timer effect for challenge countdown and untimed mode
  useEffect(() => {
    if (!currentChallenge) return
    if (feedback === 'correct') return
    if (loading) return
    if (timeLimit === 0) return

    if (timeLeft === 0) {
      // mark incorrect due to timeout
      setFeedback('incorrect')
      setChallengeExplanation(null)

      setQuestionRuns((prev) => {
        const runs = prev ? [...prev] : []
        const ch = currentChallenge
        const hintCount = showHintIndex
        const existing = runs[currentQuestionIndex]
        const wrongAttempts = existing?.wrongAttempts ?? 0
        const explanation = getWrongAnswerExplanation({ cipherId: ch.cipherId, difficulty: ch.difficulty })
        const earnedXp = computeEarnedXp({ wasCorrect: false, hintRevealedCount: hintCount })

        runs[currentQuestionIndex] = {
          cipherId: ch.cipherId,
          plaintext: ch.plaintext,
          key: ch.key,
          difficulty: ch.difficulty,
          correct: false,
          hintRevealedCount: hintCount,
          wrongAttempts,
          lastExplanation: explanation,
          earnedXp,
        }
        return runs
      })

      successTimeoutRef.current && clearTimeout(successTimeoutRef.current)
      successTimeoutRef.current = setTimeout(() => {
        advanceQuestion()
      }, 1500)

      return
    }

    const t = setTimeout(() => setTimeLeft((v) => v - 1), 1000)
    return () => clearTimeout(t)
  }, [currentChallenge, feedback, loading, timeLeft, currentQuestionIndex, showHintIndex, timeLimit, advanceQuestion])

  const resetSession = useCallback(() => {
    successTimeoutRef.current && clearTimeout(successTimeoutRef.current)
    sessionPersistedRef.current = false
    setReplayMode(false)

    setStarted(true)
    setSessionChallenges(generateSessionChallenges(difficulty, questionCount))
    setQuestionRuns(new Array(questionCount))
    setCurrentQuestionIndex(0)
    setExpectedCiphertext('')
    setFeedback('idle')
    setChallengeExplanation(null)
    setAnswer('')
    setShowHintIndex(0)
    setTimeLeft(timeLimit)
    setCopied(false)
  }, [difficulty, questionCount, timeLimit, generateSessionChallenges])

  const startNewSession = useCallback(() => {
    successTimeoutRef.current && clearTimeout(successTimeoutRef.current)
    sessionPersistedRef.current = false
    setReplayMode(false)
    setSessionChallenges(generateSessionChallenges(difficulty, questionCount))
    setQuestionRuns(new Array(questionCount))
    setCurrentQuestionIndex(0)
    setExpectedCiphertext('')
    setFeedback('idle')
    setChallengeExplanation(null)
    setAnswer('')
    setShowHintIndex(0)
    setTimeLeft(timeLimit)
    setCopied(false)
    setStarted(true)
  }, [difficulty, questionCount, timeLimit, generateSessionChallenges])

  const handleCopy = () => {
    if (!expectedCiphertext) return
    navigator.clipboard.writeText(expectedCiphertext)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const handleRetryExpectedCiphertext = useCallback(() => {
    if (!currentChallenge) return
    if (!error) return
    if (loading) return
    if (cipherRetryCount >= MAX_CIPHERTEXT_RETRIES) return

    // Prevent rapid repeated clicks from scheduling multiple retries.
    setExpectedCiphertext('')

    const nextCount = cipherRetryCount + 1

    setCipherRetryCount(nextCount)

    const delayMs = RETRY_BACKOFF_BASE_MS * Math.pow(2, nextCount - 1)

    retryTimerRef.current && clearTimeout(retryTimerRef.current)
    retryTimerRef.current = setTimeout(() => {
      loadExpectedCiphertextForCurrent()
    }, delayMs)
  }, [cipherRetryCount, currentChallenge, error, loading, loadExpectedCiphertextForCurrent])



  const handleShowHint = useCallback(() => {
    if (!currentChallenge) return
    const maxHintIndex = Math.max(0, currentChallenge.hints.length - 1)
    setShowHintIndex((i) => Math.min(maxHintIndex, i + 1))
    setFeedback('idle')
  }, [currentChallenge])

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!currentChallenge) return
    if (!answer.trim()) return
    if (loading || !!error) return
    if (feedback === 'correct') return

    const isCorrect = answer.toUpperCase() === currentChallenge.plaintext.toUpperCase()

    if (isCorrect) {
      const hintCount = showHintIndex
      const earnedXp = computeEarnedXp({ wasCorrect: true, hintRevealedCount: hintCount })

      setQuestionRuns((prev) => {
        const runs = prev ? [...prev] : []
        const explanation = getWrongAnswerExplanation({ cipherId: currentChallenge.cipherId, difficulty: currentChallenge.difficulty })
        runs[currentQuestionIndex] = {
          cipherId: currentChallenge.cipherId,
          plaintext: currentChallenge.plaintext,
          key: currentChallenge.key,
          difficulty: currentChallenge.difficulty,
          correct: true,
          hintRevealedCount: hintCount,
          wrongAttempts: 0,
          lastExplanation: explanation,
          earnedXp,
        }
        return runs
      })

      setFeedback('correct')
      setChallengeExplanation(null)

      successTimeoutRef.current && clearTimeout(successTimeoutRef.current)
      successTimeoutRef.current = setTimeout(() => {
        advanceQuestion()
      }, 1500)
      return
    }

    // incorrect
    const explanation = getWrongAnswerExplanation({ cipherId: currentChallenge.cipherId, difficulty: currentChallenge.difficulty })
    setChallengeExplanation(explanation)
    setFeedback('incorrect')

    setQuestionRuns((prev) => {
      const runs = prev ? [...prev] : []
      const existing = runs[currentQuestionIndex]
      const hintCount = showHintIndex
      const wrongAttempts = (existing?.wrongAttempts ?? 0) + 1
      const earnedXp = computeEarnedXp({ wasCorrect: false, hintRevealedCount: hintCount })

      runs[currentQuestionIndex] = {
        cipherId: currentChallenge.cipherId,
        plaintext: currentChallenge.plaintext,
        key: currentChallenge.key,
        difficulty: currentChallenge.difficulty,
        correct: false,
        hintRevealedCount: hintCount,
        wrongAttempts,
        lastExplanation: explanation,
        earnedXp,
      }
      return runs
    })
  }

  const sessionSummary = useMemo(() => {
    if (!questionRuns) return null
    const completed = questionRuns.filter(Boolean) as QuestionRun[]
    const correctCount = completed.filter((r) => r.correct).length
    const totalXp = completed.reduce((a, r) => a + r.earnedXp, 0)
    const accuracy = completed.length ? correctCount / completed.length : 0

    const totalHintsUsed = completed.reduce((a, r) => a + r.hintRevealedCount, 0)

    const perCipher = new Map<string, { cipherId: string; correct: number; attempts: number; hints: number }>()
    for (const r of completed) {
      const key = String(r.cipherId)
      const cur = perCipher.get(key) ?? { cipherId: key, correct: 0, attempts: 0, hints: 0 }
      cur.attempts += 1
      if (r.correct) cur.correct += 1
      cur.hints += r.hintRevealedCount
      perCipher.set(key, cur)
    }

    return {
      completedCount: completed.length,
      correctCount,
      totalXp,
      accuracy,
      totalHintsUsed,
      perCipher: Array.from(perCipher.values()),
    }
  }, [questionRuns])

  // Completion: persist XP, streak, history, update legacy best score
  useEffect(() => {
    // Guard: prevent double-persistence from StrictMode, stale closure re-renders, etc.
    if (sessionPersistedRef.current) return
    if (!started) return
    if (!questionRuns) return
    if (currentQuestionIndex <= questionCount - 1) return

    const completed = questionRuns.filter(Boolean) as QuestionRun[]
    if (completed.length !== questionCount) return

    const sessionXp = completed.reduce((a, r) => a + r.earnedXp, 0)
    const correctCount = completed.filter((r) => r.correct).length

    // update best score legacy using old points model (approx): correctCount * 100
    const legacyScore = correctCount * XP_BASE_CORRECT

    const now = new Date()
    const todayKey = formatLocalDateKey(now)
    const lastKey = localStorage.getItem(STREAK_LAST_DATE_KEY)
    const lastDate = lastKey ? parseLocalDateKey(lastKey) : null

    let newStreak = 1
    if (lastDate) {
      const diff = daysBetweenLocalDates(lastDate, now)
      if (diff === 0) {
        newStreak = parseInt(localStorage.getItem(STREAK_COUNT_KEY) || '0', 10) || 0
      } else if (diff === 1) {
        newStreak = (parseInt(localStorage.getItem(STREAK_COUNT_KEY) || '0', 10) || 0) + 1
      } else {
        newStreak = 1
      }
    } else {
      newStreak = 1
    }

    setStreak(newStreak)
    setXpTotal((prev) => prev + sessionXp)

    localStorage.setItem(XP_TOTAL_KEY, String((parseInt(localStorage.getItem(XP_TOTAL_KEY) || '0', 10) || 0) + sessionXp))
    localStorage.setItem(STREAK_COUNT_KEY, String(newStreak))
    localStorage.setItem(STREAK_LAST_DATE_KEY, todayKey)

    // history
    const accuracy = completed.length ? correctCount / completed.length : 0

    const entry: ChallengeHistoryEntry = {
      id: uid(),
      createdAt: Date.now(),
      difficulty,
      xpEarned: sessionXp,
      accuracy,
      streakAfter: newStreak,
      questions: completed.map((r) => ({
        cipherId: r.cipherId,
        correct: r.correct,
        hintRevealedCount: r.hintRevealedCount,
        wrongAttempts: r.wrongAttempts,
        earnedXp: r.earnedXp,
      })),
    }

    const prevHistory = safeJsonParse<ChallengeHistoryEntry[]>(localStorage.getItem(HISTORY_KEY)) ?? []
    const nextHistory = [entry, ...prevHistory].slice(0, HISTORY_CAP)
    localStorage.setItem(HISTORY_KEY, JSON.stringify(nextHistory))

    // best score legacy
    setBestScore((prev) => {
      const next = Math.max(prev, legacyScore)
      localStorage.setItem(BEST_SCORE_KEY, String(next))
      return next
    })

    // Mark this session as persisted to prevent double-persistence
    sessionPersistedRef.current = true
  }, [started, questionRuns, currentQuestionIndex, difficulty, questionCount])

  const handleReplay = useCallback(() => {
    if (!sessionChallenges) return
