            <p className="text-2xl font-bold text-emerald-600 dark:text-emerald-400 mt-1">Active (Non-Blocking)</p>
          </div>
        </div>
      )}

      {/* Live Log Feed */}
      <div className="p-5 rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-zinc-900 text-zinc-100 font-mono text-xs space-y-3">
        <div className="flex justify-between items-center border-b border-zinc-800 pb-2">
          <span className="text-zinc-400 font-bold">Worker Event Log</span>
          <button
            onClick={() => setLogs([])}
            className="text-[10px] text-zinc-500 hover:text-zinc-300 uppercase tracking-wider"
          >
            Clear Console
          </button>
        </div>

        <div className="max-h-64 overflow-y-auto space-y-2">
          {logs.length === 0 ? (
            <p className="text-zinc-600 italic">No events logged yet. Click 'Ping Web Worker' above to begin.</p>
          ) : (
            logs.map((log) => (
              <div key={log.id} className="flex items-start gap-2">
                <span className="text-zinc-500 text-[10px]">{log.timestamp}</span>
                <span
                  className={`px-1.5 py-0.5 rounded text-[10px] font-bold ${
                    log.type === "sent"
                      ? "bg-blue-900/50 text-blue-300"
                      : log.type === "received"
                      ? "bg-emerald-900/50 text-emerald-300"
                      : "bg-red-900/50 text-red-300"
                  }`}
                >
                  {log.type.toUpperCase()}
                </span>
                <span className="text-zinc-300">{log.message}</span>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

import { Project, Identifier, Node } from "ts-morph";
import * as fs from "fs";

const project = new Project({
  tsConfigFilePath: "tsconfig.json",
});

const report = JSON.parse(fs.readFileSync('unused2.json', 'utf8'));

for (const item of report) {
  const sourceFile = project.getSourceFile(item.file);
  if (!sourceFile) continue;

  let fileChanged = false;

  for (const unused of item.unused) {
    const line = unused.line;
    // Extract the variable name from the message.
    // e.g. "'keystream' is assigned a value but never used."
    // e.g. "'key' is defined but never used."
    const match = unused.msg.match(/'([^']+)'/);
    if (!match) continue;
    const varName = match[1];

    // Sometimes eslint reports unused vars which we can prefix with _
    // Let's find identifiers on that line with that name
    const descendants = sourceFile.getDescendants();
    for (const node of descendants) {
      if (Node.isIdentifier(node) && node.getText() === varName) {
        if (node.getStartLineNumber() === line) {
          // If it's a declaration, rename it
          try {
            node.rename(`_${varName}`);
            fileChanged = true;
          } catch (e) {
            // rename might fail if it's not a valid rename location or read-only
          }
        }
      }
    }
  }

  if (fileChanged) {
    sourceFile.saveSync();
  }
}

import { p256 } from '@noble/curves/nist.js'
import { sha256 } from '@noble/hashes/sha2.js'
import { CipherError } from '../../utils/errors'
import { toByteArray, fromByteArray } from '../../utils/encoding'
import { modPow } from './rsa'
import type { CipherResult, CipherStep, CipherMetadata, CipherOptions, Encoding, TestVector } from '../types'

/**
 * Derive a valid P-256 private scalar deterministically from arbitrary input.
 * SHA-256 of the seed is almost always a valid secret key; on the astronomically
 * rare chance it is out of range we re-hash until getPublicKey accepts it.
 */
function derivePrivateScalar(seed: string, encoding: Encoding): Uint8Array {
  let candidate = sha256(toByteArray(seed, encoding))
  for (let i = 0; i < 16; i++) {
    try {
      p256.getPublicKey(candidate)
      return candidate
    } catch {
      candidate = sha256(candidate)
    }
  }
  throw new CipherError('INVALID_KEY', 'Could not derive a valid P-256 private key from the input.')
}

const METADATA: CipherMetadata = {
  name: 'Diffie-Hellman',
  securityStatus: 'secure', // Real mode is secure, demo mode is legacy/broken
  yearDesigned: 1976,
  standardBody: 'RFC 7919 / FIPS 196',
}

