interface DhParams {
  p: bigint
  g: bigint
  a?: bigint
  b?: bigint
}

function parseDhInput(inputStr: string): { a: bigint; b?: bigint } {
  const parts = inputStr.split(/[\s,]+/).map(p => p.trim()).filter(Boolean)
  if (parts.length === 0) {
    throw new CipherError('INPUT_REQUIRED', 'Alice secret key "a" is required.')
  }

  // Check if formatted like a=6, b=15
  let a = 0n
  let b: bigint | undefined = undefined

  const aMatch = inputStr.match(/a\s*=\s*(\d+)/i)
  const bMatch = inputStr.match(/b\s*=\s*(\d+)/i)

  if (aMatch) {
    a = BigInt(aMatch[1])
    if (bMatch) b = BigInt(bMatch[1])
  } else {
    a = BigInt(parts[0])
    if (parts.length >= 2) {
      b = BigInt(parts[1])
    }
  }

  return { a, b }
}

function parseDhParams(keyStr: string): DhParams {
  const cleanKey = keyStr.trim()
  if (!cleanKey) {
    // Defaults for demo mode
    return { p: 23n, g: 5n }
  }

  // Check if formatted like p=23, g=5
  const pMatch = cleanKey.match(/p\s*=\s*(\d+)/i)
  const gMatch = cleanKey.match(/g\s*=\s*(\d+)/i)

  if (pMatch && gMatch) {
    return {
      p: BigInt(pMatch[1]),
      g: BigInt(gMatch[1]),
    }
  }

  const parts = cleanKey.split(/[\s,]+/).map(p => p.trim()).filter(Boolean)
  if (parts.length >= 2) {
    return {
      p: BigInt(parts[0]),
      g: BigInt(parts[1]),
    }
  }

  throw new CipherError(
    'INVALID_KEY',
    'Invalid DH parameters. Use "p,g", "p=..., g=...", or leave empty for default.'
  )
}

export function encrypt(
  input: string,
  key: string = '',
  options: CipherOptions = {}
): CipherResult {
  if (input === undefined || input === null || input === '') {
    throw new CipherError('INPUT_REQUIRED', 'Private key input is required.')
  }

  const start = performance.now()
  const isRealMode = options.mode === 'real'

  // Real Mode: genuine ECDH over the NIST P-256 curve via @noble/curves.
  if (isRealMode) {
    const steps: CipherStep[] = []

    // Alice's private scalar is derived deterministically from the input seed;
    // Bob is the counterparty with an ephemeral (freshly generated) key pair.
    const alicePriv = derivePrivateScalar(input, options.encoding || 'utf8')
    const bobPriv = p256.utils.randomSecretKey()
    const alicePub = p256.getPublicKey(alicePriv)
    const bobPub = p256.getPublicKey(bobPriv)

    // ECDH: each party multiplies its own private key by the other's public key.
    // The result is the same shared point; its x-coordinate is the raw secret.
    const aliceShared = p256.getSharedSecret(alicePriv, bobPub)
    const bobShared = p256.getSharedSecret(bobPriv, alicePub)
    if (fromByteArray(aliceShared, 'hex') !== fromByteArray(bobShared, 'hex')) {
      // Should be mathematically impossible; guards against a broken curve impl.
      throw new CipherError('ALGORITHM_UNSUPPORTED', 'ECDH shared secret mismatch between parties.')
    }

    // Strip the 0x02/0x03 compressed-point prefix to expose the 32-byte x-coordinate.
    const sharedSecret = fromByteArray(aliceShared.slice(1), 'hex')

    if (options.instrument) {
      steps.push({
        index: 0,
        label: 'ECDH P-256 Key Exchange (real)',
        inputState: fromByteArray(alicePriv, 'hex'),
        outputState: sharedSecret,
        table: [
          { key: "Alice's public key", value: fromByteArray(alicePub, 'hex') },
          { key: "Bob's public key (ephemeral)", value: fromByteArray(bobPub, 'hex') },
        ],
        note: "Real mode performs genuine Elliptic Curve Diffie-Hellman over NIST P-256 using @noble/curves. Alice computes a·B and Bob computes b·A; both scalar multiplications land on the same point, so the shared secret (its x-coordinate) matches. In practice this raw secret is run through a KDF before use as a key.",
        isMilestone: true,
      })
    }

    return {
      output: sharedSecret,
      outputEncoding: 'hex',
      steps,
      metadata: {
        ...METADATA,
        name: 'ECDH P-256',
        keySize: 256,
      },
      durationMs: performance.now() - start,
    }
  }

  // Demo Mode
  const { p, g } = parseDhParams(key)
  const { a, b } = parseDhInput(input)

  if (a <= 1n || a >= p - 1n) {
    throw new CipherError('INVALID_KEY', `Alice's secret 'a' must be in range [2, p-2] (got ${a}).`)
  }
  if (b !== undefined && (b <= 1n || b >= p - 1n)) {
    throw new CipherError('INVALID_KEY', `Bob's secret 'b' must be in range [2, p-2] (got ${b}).`)
  }

  const steps: CipherStep[] = []

  if (options.instrument) {
    steps.push({
      index: 0,
      label: 'Agreement on Public Parameters',
      inputState: '',
      outputState: '',
      table: [
        { key: 'Modulus p (Prime)', value: p.toString() },
        { key: 'Generator g', value: g.toString() },
      ],
      note: `Alice and Bob agree openly on prime p = ${p} and generator g = ${g}.`,
      isMilestone: true,
    })

    steps.push({
      index: 1,
      label: 'Visual Analogy: Paint Mixing (Part 1)',
      inputState: '',
      outputState: '',
      note: `Analogy: The public parameters are like a common paint color (e.g. Yellow). Anyone can see it.`,
    })

    steps.push({
      index: 2,
      label: 'Alice Generates Private Secret',
      inputState: '',
      outputState: '',
      note: `Alice selects private value a = ${a}. This is kept secret and never transmitted. (Analogy: Alice chooses her secret paint color: Red).`,
    })

    const A = modPow(g, a, p)
    steps.push({
      index: 3,
      label: 'Alice Computes Public Key',
      inputState: '',
      outputState: A.toString(),
      note: `Alice computes A = g^a mod p = ${g}^${a} mod ${p} = ${A}. (Analogy: Alice mixes Yellow and Red to get Orange).`,
    })

    if (b !== undefined) {
      steps.push({
        index: 4,
        label: 'Bob Generates Private Secret',
        inputState: '',
        outputState: '',
        note: `Bob selects private value b = ${b}. This is kept secret and never transmitted. (Analogy: Bob chooses his secret paint color: Blue).`,
      })

      const B = modPow(g, b, p)
      steps.push({
        index: 5,
        label: 'Bob Computes Public Key',
        inputState: '',
        outputState: B.toString(),
        note: `Bob computes B = g^b mod p = ${g}^${b} mod ${p} = ${B}. (Analogy: Bob mixes Yellow and Blue to get Green).`,
      })

      steps.push({
        index: 6,
        label: 'Public Exchange',
        inputState: `A = ${A}, B = ${B}`,
        outputState: '',
        note: `Alice sends A (${A}) to Bob. Bob sends B (${B}) to Alice. Eve (the eavesdropper) intercepts these but learns nothing about a or b. (Analogy: They exchange Orange and Green paint mixtures).`,
        isMilestone: true,
      })

      const Ka = modPow(B, a, p)
      steps.push({
        index: 7,
        label: 'Alice Computes Shared Secret',
        inputState: '',
        outputState: Ka.toString(),
        note: `Alice computes K = B^a mod p = ${B}^${a} mod ${p} = ${Ka}. (Analogy: Alice adds her secret Red paint to Bob's Green mix to get a final Brown color).`,
      })

      const Kb = modPow(A, b, p)
      steps.push({
        index: 8,
        label: 'Bob Computes Shared Secret',
        inputState: '',
        outputState: Kb.toString(),
        note: `Bob computes K = A^b mod p = ${A}^${b} mod ${p} = ${Kb}. (Analogy: Bob adds his secret Blue paint to Alice's Orange mix to get the same final Brown color).`,
      })

      steps.push({
        index: 9,
        label: 'Shared Secret Established',
        inputState: '',
        outputState: Ka.toString(),
        note: `Both Alice and Bob successfully arrived at the same shared secret K = ${Ka} without transmitting their private keys.`,
        isMilestone: true,
      })

      return {
        output: Ka.toString(),
        outputEncoding: 'utf8',
        steps,
        metadata: METADATA,
        durationMs: performance.now() - start,
      }
    } else {
      // Bob's secret not provided, we only calculate Alice's public key A
      const A = modPow(g, a, p)
      return {
        output: A.toString(),
        outputEncoding: 'utf8',
        steps,
        metadata: METADATA,
        durationMs: performance.now() - start,
      }
    }
  }

  // Non-instrumented path
  const A = modPow(g, a, p)
  if (b !== undefined) {
    const K = modPow(modPow(g, b, p), a, p)
    return {
      output: K.toString(),
      outputEncoding: 'utf8',
      steps: [],
      metadata: METADATA,
      durationMs: performance.now() - start,
    }
  }

  return {
    output: A.toString(),
    outputEncoding: 'utf8',
    steps: [],
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function decrypt(
  input: string,
  key: string = '',
  options: CipherOptions = {}
): CipherResult {
  throw new CipherError(
    'ALGORITHM_UNSUPPORTED',
    'Diffie-Hellman is a key exchange protocol and does not support decryption.'
  )
}

/**
 * DSA (Digital Signature Algorithm) — NIST FIPS 186, 1994.
 * @see CIPHER_ENGINE.md section "DSA"
 *
 * The finite-field discrete-log ancestor of ECDSA: same r/s signature
 * shape and same nonce-reuse vulnerability, computed in a prime-order
 * subgroup of (Z/pZ)* instead of on an elliptic curve. Demo mode uses
 * small textbook parameters (same approach as rsa.ts/dh.ts/elgamal.ts) —
 * real DSA requires p >= 2048 bits, q >= 224 bits per current NIST
 * guidance (SP 800-57).
 *
 * Verified demo values (independently computed, not hand-derived):
 *   p=47, q=23, g=4 (order-23 subgroup generator)
 *   private x=5, public y=37
 *   sign H=15 with nonce k=7 -> r=5, s=9 (verified valid)
 */

import { CipherError } from '../../utils/errors'
import type { CipherResult, CipherStep, CipherMetadata, CipherOptions, TestVector } from '../types'

const METADATA: CipherMetadata = {
  name: 'DSA',
  securityStatus: 'secure', // secure at real key sizes (p>=2048 bits, q>=224 bits per NIST SP 800-57); demo mode uses toy parameters for teaching
  yearDesigned: 1994,
  standardBody: 'NIST FIPS 186',
}

interface DsaPublicKey {
  p: bigint
  q: bigint
  g: bigint
  y: bigint
}

interface DsaPrivateKey {
  p: bigint
  q: bigint
  g: bigint
  x: bigint
}

function modPow(base: bigint, exp: bigint, mod: bigint): bigint {
  let result = 1n
  let b = ((base % mod) + mod) % mod
  let e = exp
  while (e > 0n) {
    if (e & 1n) result = (result * b) % mod
    b = (b * b) % mod
    e >>= 1n
  }
  return result
}

function extendedGcd(a: bigint, b: bigint): [bigint, bigint, bigint] {
  if (a === 0n) return [b, 0n, 1n]
  const [g, x1, y1] = extendedGcd(b % a, a)
  return [g, y1 - (b / a) * x1, x1]
}

function modInverse(a: bigint, m: bigint): bigint {
  const [g, x] = extendedGcd(((a % m) + m) % m, m)
  if (g !== 1n) throw new CipherError('INVALID_KEY', `No modular inverse exists for ${a} mod ${m}.`)
  return ((x % m) + m) % m
}

function parsePublicKey(keyStr: string): DsaPublicKey {
  const clean = keyStr.trim()
  if (!clean) return { p: 47n, q: 23n, g: 4n, y: 37n } // demo default
  const parts = clean.split(/[\s,]+/).map((s) => s.trim()).filter(Boolean)
  if (parts.length !== 4) {
    throw new CipherError('INVALID_KEY', 'DSA public key must be "p,q,g,y".')
  }
  return { p: BigInt(parts[0]), q: BigInt(parts[1]), g: BigInt(parts[2]), y: BigInt(parts[3]) }
}

function parsePrivateKey(keyStr: string): DsaPrivateKey {
  const clean = keyStr.trim()
  if (!clean) return { p: 47n, q: 23n, g: 4n, x: 5n } // demo default
  const parts = clean.split(/[\s,]+/).map((s) => s.trim()).filter(Boolean)
  if (parts.length !== 4) {
    throw new CipherError('INVALID_KEY', 'DSA private key must be "p,q,g,x".')
  }
  return { p: BigInt(parts[0]), q: BigInt(parts[1]), g: BigInt(parts[2]), x: BigInt(parts[3]) }
}

function signCore(input: string, key: string, instrument: boolean): CipherResult {
  const start = performance.now()
  const priv = parsePrivateKey(key)
  const { p, q, g, x } = priv
  const H = BigInt(input.trim())
  if (H < 0n || H >= q) {
    throw new CipherError('INVALID_INPUT', `Message hash H must satisfy 0 <= H < q (q=${q}). Reduce your hash mod q first.`)
  }

  // Demo-mode nonce: derived from input+key for reproducibility in tests.
  // Real usage MUST use a fresh cryptographically random k per signature —
  // reusing k across two signatures leaks the private key x directly.
  let k = 1n
  let r = 0n
  let s = 0n
  const steps: CipherStep[] = []
  do {
    k = ((H + x + k) % (q - 1n)) + 1n // deterministic-for-demo search, NOT how real DSA should pick k
    r = modPow(g, k, p) % q
    if (r === 0n) continue
    const kInv = modInverse(k, q)
    s = (kInv * (H + x * r)) % q
  } while (r === 0n || s === 0n)

  if (instrument) {
    steps.push({
      index: 0,
      label: 'Sign',
      inputState: H.toString(),
      outputState: `r=${r}, s=${s}`,
      table: [
        { key: 'k (nonce)', value: k.toString() },
        { key: 'r = (g^k mod p) mod q', value: r.toString() },
        { key: 's = k⁻¹(H + x·r) mod q', value: s.toString() },
      ],
      note: 'r/s shape is the same equation ECDSA later adapted to elliptic curves. Never reuse k across signatures — doing so leaks x.',
      isMilestone: true,
    })
  }

  return {
    output: `${r},${s}`,
    outputEncoding: 'utf8',
    steps,
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

function verifyCore(input: string, key: string, instrument: boolean): CipherResult {
  const start = performance.now()
  const pub = parsePublicKey(key)
  const { p, q, g, y } = pub

  // Standard contract for signature verification in this registry:
  // input = "messageHash", signature = "r,s" (passed via key or appended)
  // To match the UI pattern in ecc.ts/ed25519.ts, we expect input to be H
  // and the key to contain "p,q,g,y|r,s"
  const [keyPart, sigPart] = key.split('|').map(s => s.trim())
  if (!sigPart) {
    throw new CipherError('INVALID_KEY', 'Verification requires "p,q,g,y | r,s".')
  }

  const H = BigInt(input.trim())
  const [rs, ss] = sigPart.split(',').map((s) => s.trim())
  const r = BigInt(rs)
  const s = BigInt(ss)

  if (r <= 0n || r >= q || s <= 0n || s >= q) {
    throw new CipherError('INVALID_INPUT', 'r and s must both be in [1, q-1].')
  }

  const w = modInverse(s, q)
  const u1 = (H * w) % q
  const u2 = (r * w) % q
  const v = ((modPow(g, u1, p) * modPow(y, u2, p)) % p) % q
  const valid = v === r

  const steps: CipherStep[] = []
  if (instrument) {
    steps.push({
      index: 0,
      label: 'Verify',
      inputState: `H=${H}, r=${r}, s=${s}`,
      outputState: valid ? 'VALID' : 'INVALID',
      note: `v = (g^u1 * y^u2 mod p) mod q = ${v}; valid iff v == r (${r}).`,
      isMilestone: true,
    })
  }

  if (!valid) {
    throw new CipherError('INVALID_INPUT', 'DSA signature verification failed.')
  }

  return {
    output: 'VALID',
    outputEncoding: 'utf8',
    steps,
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function encrypt(input: string, key: string, options: CipherOptions = {}): CipherResult {
  return signCore(input, key, !!options.instrument)
}

export function decrypt(input: string, key: string, options: CipherOptions = {}): CipherResult {
  return verifyCore(input, key, !!options.instrument)
}

