import { hmac } from '@noble/hashes/hmac.js'
import { sha256 } from '@noble/hashes/sha2.js'
import { toByteArray, fromByteArray } from '../../utils/encoding'
import { CipherError, validateInput, validateKey } from '../../utils/errors'
import type { CipherResult, CipherStep, CipherMetadata, CipherOptions, TestVector } from '../types'

const METADATA: CipherMetadata = {
  name: 'HMAC-SHA256',
  blockSize: 64, // 512 bits
  securityStatus: 'secure',
  yearDesigned: 1996,
  standardBody: 'RFC 2104 / FIPS 198',
}

export const TEST_VECTORS: TestVector[] = [
  {
    input: 'Hi There',
    key: '0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b',
    expected: 'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7',
    description: 'RFC 4231 Test Case 1',
  },
  {
    input: 'what do ya want for nothing?',
    key: 'Jefe',
    expected: '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843',
    description: 'RFC 4231 Test Case 2',
  },
]

function parseKey(key: string): Uint8Array {
  // Auto-detect hex key if it is valid hex and even length
  if (/^[0-9a-fA-F]+$/.test(key) && key.length % 2 === 0) {
    return toByteArray(key, 'hex')
  }
  return toByteArray(key, 'utf8')
}

export function encrypt(
  input: string,
  key: string,
  options: CipherOptions = {}
): CipherResult {
  validateInput(input)
  validateKey(key)

  const msgBytes = toByteArray(input, options.encoding || 'utf8')
  const keyBytes = parseKey(key)

  const start = performance.now()

  if (options.instrument) {
    const steps: CipherStep[] = []

    // Step 1: Key padding / hashing
    const KPrime = new Uint8Array(64)
    let keyPrepNote = ''
    if (keyBytes.length > 64) {
      const hashedKey = sha256(keyBytes)
      KPrime.set(hashedKey, 0)
      keyPrepNote = 'Key is longer than block size (64 bytes). Hashed key with SHA-256 and padded with zeros.'
    } else {
      KPrime.set(keyBytes, 0)
      keyPrepNote = `Key length is <= 64 bytes. Padded key with zeros to block size (64 bytes).`
    }

    steps.push({
      index: 0,
      label: 'Key Preparation',
      inputState: fromByteArray(keyBytes, 'hex'),
      outputState: fromByteArray(KPrime, 'hex'),
      note: keyPrepNote,
      isMilestone: true,
    })

    // Step 2: Inner Key XOR ipad
    const ipad = new Uint8Array(64)
    const innerKey = new Uint8Array(64)
    for (let i = 0; i < 64; i++) {
      ipad[i] = 0x36
      innerKey[i] = KPrime[i] ^ 0x36
    }

    steps.push({
      index: 1,
      label: 'Inner Key (K\' XOR ipad)',
      inputState: fromByteArray(KPrime, 'hex'),
      outputState: fromByteArray(innerKey, 'hex'),
      note: 'XORed prepared key with ipad byte value (0x36 repeated 64 times).',
    })

    // Step 3: Inner Hash H(innerKey || message)
    const innerInput = new Uint8Array(64 + msgBytes.length)
    innerInput.set(innerKey, 0)
    innerInput.set(msgBytes, 64)
    const innerHash = sha256(innerInput)

    steps.push({
      index: 2,
      label: 'Inner SHA-256 Hash',
      inputState: fromByteArray(innerInput, 'hex'),
      outputState: fromByteArray(innerHash, 'hex'),
      note: 'Computed SHA-256 hash of inner key concatenated with input message.',
      isMilestone: true,
    })

    // Step 4: Outer Key XOR opad
    const opad = new Uint8Array(64)
    const outerKey = new Uint8Array(64)
    for (let i = 0; i < 64; i++) {
      opad[i] = 0x5c
      outerKey[i] = KPrime[i] ^ 0x5c
    }

    steps.push({
      index: 3,
      label: 'Outer Key (K\' XOR opad)',
      inputState: fromByteArray(KPrime, 'hex'),
      outputState: fromByteArray(outerKey, 'hex'),
      note: 'XORed prepared key with opad byte value (0x5c repeated 64 times).',
    })

    // Step 5: Final Outer Hash H(outerKey || innerHash)
    const outerInput = new Uint8Array(64 + 32)
    outerInput.set(outerKey, 0)
    outerInput.set(innerHash, 64)
    const outputBytes = sha256(outerInput)
    const outputHex = fromByteArray(outputBytes, 'hex')

    steps.push({
      index: 4,
      label: 'Outer SHA-256 Hash (Final HMAC)',
      inputState: fromByteArray(outerInput, 'hex'),
      outputState: outputHex,
      note: 'Computed final SHA-256 hash of outer key concatenated with inner hash result.',
      isMilestone: true,
    })

    return {
      output: outputHex,
      outputEncoding: 'hex',
      steps,
      metadata: METADATA,
      durationMs: performance.now() - start,
    }
  }

  // Fast path
  const outputBytes = hmac(sha256, keyBytes, msgBytes)
  const output = fromByteArray(outputBytes, 'hex')

  return {
    output,
    outputEncoding: 'hex',
    steps: [],
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function decrypt(
  input: string,
  key: string,
  options: CipherOptions = {}
): CipherResult {
  throw new CipherError(
    'ALGORITHM_UNSUPPORTED',
    'HMAC is a one-way message authentication code and cannot be decrypted.'
  )
}

/**
 * MD4 — Ronald Rivest, 1990 (RFC 1320).
 * @see CIPHER_ENGINE.md section "MD4"
 *
 * Fully broken (collisions found by hand in seconds) — included as a
 * historical entry alongside MD5 and SHA-1, and as the direct ancestor
 * MD5 was designed to fix: MD4 has only 3 rounds (MD5 has 4) and no
 * per-step additive sine-derived constants (MD5 added those).
 *
 * Verified against all 3 of RFC 1320's own published test vectors in a
 * sandbox implementation before this file was written:
 *   MD4("")               = 31d6cfe0d16ae931b73c59d7e0c089c0
 *   MD4("abc")             = a448017aaf21d8525fc10ae87aa6729d
 *   MD4("message digest")  = d9130a8164549fe818874806e1c7014b
 */

import type { CipherResult, CipherStep, CipherMetadata, CipherOptions, TestVector } from '../types'
import { CipherError, validateInput } from '../../utils'

const METADATA: CipherMetadata = {
  name: 'MD4',
  blockSize: 64,
  securityStatus: 'broken',
  breakingComplexity: 'Full collisions found by hand in seconds; do not use for anything security-relevant',
  yearDesigned: 1990,
  standardBody: 'RFC 1320',
}

const MASK = 0xffffffff
const S1 = [3, 7, 11, 19]
const S2 = [3, 5, 9, 13]
const S3 = [3, 9, 11, 15]
const ORDER2 = [0, 4, 8, 12, 1, 5, 9, 13, 2, 6, 10, 14, 3, 7, 11, 15]
const ORDER3 = [0, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15]

function rotl(x: number, n: number): number {
  const ux = x >>> 0
  return ((ux << n) | (ux >>> (32 - n))) >>> 0
}
function F(x: number, y: number, z: number): number {
  return ((x & y) | (~x & z)) >>> 0
}
function G(x: number, y: number, z: number): number {
  return ((x & y) | (x & z) | (y & z)) >>> 0
}
function H(x: number, y: number, z: number): number {
  return (x ^ y ^ z) >>> 0
}

function toBytesUtf8(str: string): Uint8Array {
  return new TextEncoder().encode(str)
}
function bytesToHex(b: Uint8Array): string {
  return Array.from(b).map((x) => x.toString(16).padStart(2, '0')).join('')
}
function wordToHex(w: number): string {
  // MD4 outputs little-endian words -> reverse byte order for hex display
  const bytes = [w & 0xff, (w >>> 8) & 0xff, (w >>> 16) & 0xff, (w >>> 24) & 0xff]
  return bytes.map((b) => b.toString(16).padStart(2, '0')).join('')
}

function pad(message: Uint8Array): Uint8Array {
  const bitLen = BigInt(message.length) * 8n
  let paddedLen = message.length + 1
  while (paddedLen % 64 !== 56) paddedLen++
  paddedLen += 8
  const out = new Uint8Array(paddedLen)
  out.set(message)
  out[message.length] = 0x80
  let bits = bitLen
  for (let i = 0; i < 8; i++) {
    out[paddedLen - 8 + i] = Number(bits & 0xffn)
    bits >>= 8n
  }
  return out
}

function md4Core(message: Uint8Array): number[] {
  let A = 0x67452301
  let B = 0xefcdab89
  let C = 0x98badcfe
  let D = 0x10325476
  const padded = pad(message)

  for (let chunkOff = 0; chunkOff < padded.length; chunkOff += 64) {
    const X: number[] = []
    for (let i = 0; i < 16; i++) {
      const o = chunkOff + i * 4
      X.push((padded[o] | (padded[o + 1] << 8) | (padded[o + 2] << 16) | (padded[o + 3] << 24)) >>> 0)
    }
    const [AA, BB, CC, DD] = [A, B, C, D]

    // Round 1
    for (let i = 0; i < 16; i++) {
      const f = F(B, C, D)
      const newA = rotl((A + f + X[i]) >>> 0, S1[i % 4])
      ;[A, B, C, D] = [D, newA, B, C]
    }
    // Round 2
    for (let idx = 0; idx < 16; idx++) {
      const k = ORDER2[idx]
      const f = G(B, C, D)
      const newA = rotl((A + f + X[k] + 0x5a827999) >>> 0, S2[idx % 4])
      ;[A, B, C, D] = [D, newA, B, C]
    }
    // Round 3
    for (let idx = 0; idx < 16; idx++) {
      const k = ORDER3[idx]
      const f = H(B, C, D)
      const newA = rotl((A + f + X[k] + 0x6ed9eba1) >>> 0, S3[idx % 4])
      ;[A, B, C, D] = [D, newA, B, C]
    }

    A = (A + AA) >>> 0
    B = (B + BB) >>> 0
    C = (C + CC) >>> 0
    D = (D + DD) >>> 0
  }
  return [A, B, C, D]
}

function md4Digest(input: string, instrument: boolean): CipherResult {
  const start = performance.now()
  const messageBytes = toBytesUtf8(input)
  const numBlocks = Math.ceil((messageBytes.length + 9) / 64)

  const steps: CipherStep[] = []
  if (instrument) {
    steps.push({
      index: 0,
      label: 'Padding',
      inputState: `${messageBytes.length} byte(s)`,
      outputState: `${numBlocks} block(s) of 64 bytes`,
      note: 'Message padded with a 1-bit, zeros, then a 64-bit little-endian length field.',
      isMilestone: true,
    })
  }

  const [A, B, C, D] = md4Core(messageBytes)
  const digest = wordToHex(A) + wordToHex(B) + wordToHex(C) + wordToHex(D)

  if (instrument) {
    steps.push({
      index: steps.length,
      label: '3 rounds x 16 operations per block',
      inputState: bytesToHex(messageBytes),
      outputState: digest,
      note: 'Round 1 uses F (choice function), round 2 uses G (majority function) + a constant, round 3 uses H (XOR) + a different constant — MD5 later added a 4th round on top of this exact structure.',
      isMilestone: true,
    })
  }

  return {
    output: digest,
    outputEncoding: 'hex',
    steps,
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

