    description: 'NIST standard vector 56-byte transition',
  },
]

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
])

const H_INIT = [
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
  0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
]

function rotr(x: number, n: number): number {
  return ((x >>> n) | (x << (32 - n))) >>> 0
}

function sigma0(x: number): number {
  return (rotr(x, 7) ^ rotr(x, 18) ^ (x >>> 3)) >>> 0
}

function sigma1(x: number): number {
  return (rotr(x, 17) ^ rotr(x, 19) ^ (x >>> 10)) >>> 0
}

function SIGMA0(x: number): number {
  return (rotr(x, 2) ^ rotr(x, 13) ^ rotr(x, 22)) >>> 0
}

function SIGMA1(x: number): number {
  return (rotr(x, 6) ^ rotr(x, 11) ^ rotr(x, 25)) >>> 0
}

function Ch(x: number, y: number, z: number): number {
  return ((x & y) ^ (~x & z)) >>> 0
}

function Maj(x: number, y: number, z: number): number {
  return ((x & y) ^ (x & z) ^ (y & z)) >>> 0
}

export function validateHashInput(input: unknown): asserts input is string {
  if (input === null || input === undefined) {
    throw new CipherError('INPUT_REQUIRED', 'Input is required.')
  }
  if (typeof input !== 'string') {
    throw new CipherError('INPUT_REQUIRED', 'Input must be a string.')
  }
  const byteLength = new TextEncoder().encode(input).length
  if (byteLength > 2 * 1024 * 1024) {
    throw new CipherError('INPUT_TOO_LONG', `Input exceeds maximum size of 2MB (got ${byteLength}).`)
  }
}

function sha256Fast(inputBytes: Uint8Array): string {
  const hashBytes = sha256(inputBytes)
  return fromByteArray(hashBytes, 'hex')
}

function sha256Instrumented(inputBytes: Uint8Array): CipherResult {
  const start = performance.now()
  const steps: CipherStep[] = []

  // Preprocessing / padding
  const originalLenBits = inputBytes.length * 8
  const padLen = (448 - (originalLenBits + 8) % 512 + 512) % 512
  const paddedLenBytes = (originalLenBits + 8 + padLen + 64) / 8
  const padded = new Uint8Array(paddedLenBytes)
  padded.set(inputBytes, 0)
  padded[inputBytes.length] = 0x80

  // Write length as 64-bit big endian at the end
  const view = new DataView(padded.buffer)
  view.setUint32(paddedLenBytes - 4, originalLenBits & 0xffffffff)
  view.setUint32(paddedLenBytes - 8, (originalLenBits / 0x100000000) & 0xffffffff)

  steps.push({
    index: 0,
    label: 'Preprocessing - padding',
    inputState: fromByteArray(inputBytes, 'hex'),
    outputState: fromByteArray(padded, 'hex'),
    table: [
      { key: 'Original length', value: `${inputBytes.length} bytes` },
      { key: 'Padded length', value: `${paddedLenBytes} bytes` },
    ],
    note: 'Appended bit 1 (0x80), zero-padded until length = 448 mod 512 bits, and appended original length as 64-bit integer.',
    isMilestone: true,
  })

  // Initialize hash state
  const H = [...H_INIT]

  // We process the first block in detail for step visualization
  const numBlocks = padded.length / 64

  for (let b = 0; b < numBlocks; b++) {
    const block = padded.slice(b * 64, (b + 1) * 64)
    const isFirstBlock = b === 0

    const W = new Uint32Array(64)
    for (let i = 0; i < 16; i++) {
      W[i] = (block[i * 4] << 24) | (block[i * 4 + 1] << 16) | (block[i * 4 + 2] << 8) | block[i * 4 + 3]
    }
    for (let i = 16; i < 64; i++) {
      W[i] = (sigma1(W[i - 2]) + W[i - 7] + sigma0(W[i - 15]) + W[i - 16]) >>> 0
    }

    if (isFirstBlock) {
      // Step 1: W[0..15]
      const wRows4x4 = Array.from({ length: 4 }, (_, r) =>
        Array.from({ length: 4 }, (_, c) => {
          const val = W[r * 4 + c]
          return '0x' + val.toString(16).padStart(8, '0')
        })
      )
      steps.push({
        index: steps.length,
        label: 'Message schedule W[0..15]',
        inputState: fromByteArray(block, 'hex'),
        outputState: '',
        matrix: wRows4x4,
        note: 'Extracted first 16 words directly from block 1.',
      })

      // Step 2-4: W[16..31], W[32..47], W[48..63]
      for (let wGroup = 1; wGroup <= 3; wGroup++) {
        const startIdx = wGroup * 16
        const endIdx = startIdx + 15
        steps.push({
          index: steps.length,
          label: `Message schedule W[${startIdx}..${endIdx}]`,
          inputState: '',
          outputState: '',
          note: `Expanded message schedule words using sigma0 and sigma1 functions.`,
        })
      }

      // Step 5: Initialize working variables
      let [a, bVar, c, d, e, f, g, h] = H
      steps.push({
        index: steps.length,
        label: 'Initialize working variables',
        inputState: '',
        outputState: '',
        table: [
          { key: 'a', value: '0x' + a.toString(16).padStart(8, '0') },
          { key: 'b', value: '0x' + bVar.toString(16).padStart(8, '0') },
          { key: 'c', value: '0x' + c.toString(16).padStart(8, '0') },
          { key: 'd', value: '0x' + d.toString(16).padStart(8, '0') },
          { key: 'e', value: '0x' + e.toString(16).padStart(8, '0') },
          { key: 'f', value: '0x' + f.toString(16).padStart(8, '0') },
          { key: 'g', value: '0x' + g.toString(16).padStart(8, '0') },
          { key: 'h', value: '0x' + h.toString(16).padStart(8, '0') },
        ],
        note: 'Set working variables to current hash state.',
        isMilestone: true,
      })

      // Compression rounds 0..63
      for (let i = 0; i < 64; i++) {
        const T1 = (h + SIGMA1(e) + Ch(e, f, g) + K[i] + W[i]) >>> 0
        const T2 = (SIGMA0(a) + Maj(a, bVar, c)) >>> 0

        h = g
        g = f
        f = e
        e = (d + T1) >>> 0
        d = c
        c = bVar
        bVar = a
        a = (T1 + T2) >>> 0

        steps.push({
          index: steps.length,
          label: `Round ${i}`,
          inputState: '',
          outputState: '',
          table: [
            { key: `W[${i}]`, value: '0x' + W[i].toString(16).padStart(8, '0') },
            { key: `K[${i}]`, value: '0x' + K[i].toString(16).padStart(8, '0') },
            { key: 'T1', value: '0x' + T1.toString(16).padStart(8, '0') },
            { key: 'T2', value: '0x' + T2.toString(16).padStart(8, '0') },
            { key: 'new a', value: '0x' + a.toString(16).padStart(8, '0') },
            { key: 'new e', value: '0x' + e.toString(16).padStart(8, '0') },
          ],
          note: `Completed SHA-256 compression round ${i}.`,
        })
      }

      // Add to hash state
      H[0] = (H[0] + a) >>> 0
      H[1] = (H[1] + bVar) >>> 0
      H[2] = (H[2] + c) >>> 0
      H[3] = (H[3] + d) >>> 0
      H[4] = (H[4] + e) >>> 0
      H[5] = (H[5] + f) >>> 0
      H[6] = (H[6] + g) >>> 0
      H[7] = (H[7] + h) >>> 0

      steps.push({
        index: steps.length,
        label: 'Add to hash state',
        inputState: '',
        outputState: '',
        note: 'Added compressed working variables back to the hash state (modulo 2^32).',
        isMilestone: true,
      })
    } else {
      // Fast compression for subsequent blocks
      let [a, bVar, c, d, e, f, g, h] = H
      for (let i = 0; i < 64; i++) {
        const T1 = (h + SIGMA1(e) + Ch(e, f, g) + K[i] + W[i]) >>> 0
        const T2 = (SIGMA0(a) + Maj(a, bVar, c)) >>> 0
        h = g
        g = f
        f = e
        e = (d + T1) >>> 0
        d = c
        c = bVar
        bVar = a
        a = (T1 + T2) >>> 0
      }
      H[0] = (H[0] + a) >>> 0
      H[1] = (H[1] + bVar) >>> 0
      H[2] = (H[2] + c) >>> 0
      H[3] = (H[3] + d) >>> 0
      H[4] = (H[4] + e) >>> 0
      H[5] = (H[5] + f) >>> 0
      H[6] = (H[6] + g) >>> 0
      H[7] = (H[7] + h) >>> 0
    }
  }

  const outputHex = H.map(val => val.toString(16).padStart(8, '0')).join('')

  steps.push({
    index: steps.length,
    label: 'Final hash output',
    inputState: '',
    outputState: outputHex,
    note: 'Concatenated H0 through H7 to yield the final 256-bit message digest.',
    isMilestone: true,
  })

  return {
    output: outputHex,
    outputEncoding: 'hex',
    steps,
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function encrypt(
  input: string,
  key: string = '',
  options: CipherOptions = {}
): CipherResult {
  validateHashInput(input)
  const inputBytes = toByteArray(input, options.encoding || 'utf8')

  if (options.instrument) {
    return sha256Instrumented(inputBytes)
  }

  const start = performance.now()
  const output = sha256Fast(inputBytes)
  return {
    output,
    outputEncoding: 'hex',
    steps: [],
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function decrypt(
  input: string,
  key: string = '',
  options: CipherOptions = {}
): CipherResult {
  throw new CipherError(
    'ALGORITHM_UNSUPPORTED',
    'One-way cryptographic hash functions do not support decryption.'
  )
}

/**
 * SHA3-256 — NIST FIPS 202 standard hash function using the Keccak sponge construction.
 * @see CIPHER_ENGINE.md section "SHA3-256"
 *
 * Unlike SHA-256 (Merkle-Damgard + compression function), SHA-3 absorbs input
 * into a 1600-bit state (5x5 array of 64-bit lanes) rate-sized block at a time,
 * running the Keccak-f[1600] permutation (24 rounds of theta/rho/pi/chi/iota)
 * between blocks, then squeezes out the digest.
 *
 * Fast mode delegates to the audited @noble/hashes implementation (same
 * pattern as sha256.ts's use of @noble/hashes for header computation).
 * Instrumented mode re-implements the permutation by hand so each round's
 * state can be visualized; its final output is verified against the noble
 * implementation in tests to guarantee correctness.
 */

import { sha3_256 } from '@noble/hashes/sha3.js'
import { toByteArray, fromByteArray } from '../../utils/encoding'
import { CipherError } from '../../utils/errors'
import type { CipherResult, CipherStep, CipherMetadata, CipherOptions, TestVector } from '../types'

const METADATA: CipherMetadata = {
  name: 'SHA3-256',
  blockSize: 136, // rate = 1088 bits = 136 bytes
  rounds: 24,
  securityStatus: 'secure',
  yearDesigned: 2015,
  standardBody: 'NIST FIPS 202',
}

export const TEST_VECTORS: TestVector[] = [
  {
    input: '',
    key: '',
    expected: 'a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a',
    description: 'NIST FIPS 202 vector for empty input',
  },
  {
    input: 'abc',
    key: '',
    expected: '3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532',
    description: 'NIST FIPS 202 standard vector',
  },
]

const RATE_BYTES = 136 // 1088 bits
const OUTPUT_BYTES = 32 // 256 bits
const MASK64 = (1n << 64n) - 1n

function rotl64(x: bigint, n: number): bigint {
  const shift = BigInt(n % 64)
  if (shift === 0n) return x & MASK64
  return ((x << shift) | (x >> (64n - shift))) & MASK64
}

// Round constants generated via FIPS 202 Algorithm 5/6 (LFSR-based), not a
// hand-transcribed table — avoids silent transcription errors in 24 hex constants.
function generateRoundConstants(): bigint[] {
  function rc(t: number): number {
    if (t % 255 === 0) return 1
    let R = [1, 0, 0, 0, 0, 0, 0, 0]
    for (let i = 1; i <= t % 255; i++) {
      R = [0, ...R]
      R[0] ^= R[8]
      R[4] ^= R[8]
      R[5] ^= R[8]
      R[6] ^= R[8]
      R = R.slice(0, 8)
    }
    return R[0]
  }
  const RC: bigint[] = []
  for (let round = 0; round < 24; round++) {
    let val = 0n
    for (let j = 0; j <= 6; j++) {
      if (rc(j + 7 * round)) {
        val |= 1n << ((1n << BigInt(j)) - 1n)
      }
    }
    RC.push(val)
  }
  return RC
}

// Rho rotation offsets generated via the standard Keccak spec recurrence,
// not a hand-transcribed table.
function generateRhoOffsets(): number[][] {
  const off = Array.from({ length: 5 }, () => new Array(5).fill(0))
  let x = 1
  let y = 0
  for (let t = 0; t < 24; t++) {
    off[x][y] = Number((BigInt((t + 1) * (t + 2)) / 2n) % 64n)
    const newX = y
    const newY = (2 * x + 3 * y) % 5
    x = newX
    y = newY
  }
  return off
}

const ROUND_CONSTANTS = generateRoundConstants()
const RHO_OFFSETS = generateRhoOffsets()

// state[x + 5*y] holds lane (x,y). Mutates state in place.
function keccakF1600(state: BigUint64Array, steps?: CipherStep[], stepLabelPrefix?: string): void {
  for (let round = 0; round < 24; round++) {
    // Theta: XOR each column's parity into every lane in that column's neighbors
    const C = new Array<bigint>(5)
    for (let x = 0; x < 5; x++) {
      C[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20]
    }
    const D = new Array<bigint>(5)
    for (let x = 0; x < 5; x++) {
      D[x] = C[(x + 4) % 5] ^ rotl64(C[(x + 1) % 5], 1)
    }
    for (let x = 0; x < 5; x++) {
      for (let y = 0; y < 5; y++) {
        state[x + 5 * y] ^= D[x]
      }
    }

    // Rho (rotate each lane) + Pi (permute lane positions), combined
    const B = new BigUint64Array(25)
    for (let x = 0; x < 5; x++) {
      for (let y = 0; y < 5; y++) {
        const newX = y
        const newY = (2 * x + 3 * y) % 5
        B[newX + 5 * newY] = rotl64(state[x + 5 * y], RHO_OFFSETS[x][y])
      }
    }

    // Chi: nonlinear mixing within each row
    for (let x = 0; x < 5; x++) {
      for (let y = 0; y < 5; y++) {
        state[x + 5 * y] = B[x + 5 * y] ^ (~B[(x + 1) % 5 + 5 * y] & MASK64 & B[(x + 2) % 5 + 5 * y])
      }
    }

    // Iota: XOR the round constant into lane (0,0) to break symmetry
    state[0] ^= ROUND_CONSTANTS[round]

    if (steps) {
      steps.push({
        index: steps.length,
        label: `${stepLabelPrefix ?? 'Permutation'} — round ${round + 1}/24`,
        inputState: '',
        outputState: '',
        table: [{ key: 'Lane (0,0) after iota', value: '0x' + state[0].toString(16).padStart(16, '0') }],
        note: 'theta -> rho -> pi -> chi -> iota applied to the 1600-bit state.',
      })
    }
  }
}

function padTenOne(inputBytes: Uint8Array): Uint8Array {
  const numBlocks = Math.floor(inputBytes.length / RATE_BYTES) + 1
  const paddedLen = numBlocks * RATE_BYTES
  const padded = new Uint8Array(paddedLen)
  padded.set(inputBytes, 0)
  padded[inputBytes.length] ^= 0x06 // SHA-3 domain separator (01 appended, then pad10*1)
  padded[paddedLen - 1] ^= 0x80
  return padded
}

function sha3Fast(inputBytes: Uint8Array): string {
  return fromByteArray(sha3_256(inputBytes), 'hex')
}

function sha3Instrumented(inputBytes: Uint8Array): CipherResult {
  const start = performance.now()
  const steps: CipherStep[] = []

  const padded = padTenOne(inputBytes)
  const numBlocks = padded.length / RATE_BYTES

  steps.push({
    index: 0,
    label: 'Padding (pad10*1 with SHA-3 domain separator)',
    inputState: fromByteArray(inputBytes, 'hex'),
    outputState: fromByteArray(padded, 'hex'),
    table: [
      { key: 'Original length', value: `${inputBytes.length} bytes` },
      { key: 'Rate (block size)', value: `${RATE_BYTES} bytes (1088 bits)` },
      { key: 'Padded length', value: `${padded.length} bytes` },
    ],
    note: 'Appended 0x06 domain-separator byte, zero-padded, and set the top bit of the last byte (0x80) to close the padding.',
    isMilestone: true,
  })

  const state = new BigUint64Array(25)
  for (let b = 0; b < numBlocks; b++) {
    const block = padded.slice(b * RATE_BYTES, (b + 1) * RATE_BYTES)
    for (let i = 0; i < RATE_BYTES; i++) {
      const laneIdx = Math.floor(i / 8)
      const byteIdx = i % 8
      state[laneIdx] ^= BigInt(block[i]) << (8n * BigInt(byteIdx))
    }
    steps.push({
      index: steps.length,
      label: `Absorb block ${b + 1}/${numBlocks}`,
      inputState: fromByteArray(block, 'hex'),
      outputState: '',
      note: 'XORed this rate-sized block into the first 136 bytes of the 1600-bit state.',
      isMilestone: true,
    })
    // Only the first block's permutation is traced round-by-round to stay
    // within the visualizer's step budget for long inputs.
    keccakF1600(state, b === 0 ? steps : undefined, 'Keccak-f[1600]')
  }

  const outBytes = new Uint8Array(OUTPUT_BYTES)
  for (let i = 0; i < OUTPUT_BYTES; i++) {
    const laneIdx = Math.floor(i / 8)
    const byteIdx = i % 8
    outBytes[i] = Number((state[laneIdx] >> (8n * BigInt(byteIdx))) & 0xffn)
  }
  const outputHex = fromByteArray(outBytes, 'hex')

  steps.push({
    index: steps.length,
    label: 'Squeeze final digest',
    inputState: '',
    outputState: outputHex,
    note: 'Read the first 32 bytes (256 bits) of the state as the digest.',
    isMilestone: true,
  })

  return {
    output: outputHex,
    outputEncoding: 'hex',
    steps,
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function encrypt(input: string, key: string = '', options: CipherOptions = {}): CipherResult {
  if (input === null || input === undefined || typeof input !== 'string') {
    throw new CipherError('INPUT_REQUIRED', 'Input is required.')
  }
  const byteLength = new TextEncoder().encode(input).length
  if (byteLength > 2 * 1024 * 1024) {
    throw new CipherError('INPUT_TOO_LONG', `Input exceeds maximum size of 2MB (got ${byteLength}).`)
  }
  const inputBytes = toByteArray(input, options.encoding || 'utf8')

  if (options.instrument) {
    return sha3Instrumented(inputBytes)
  }

  const start = performance.now()
  const output = sha3Fast(inputBytes)
  return {
    output,
    outputEncoding: 'hex',
    steps: [],
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function decrypt(): CipherResult {
  throw new CipherError(
    'ALGORITHM_UNSUPPORTED',
    'One-way cryptographic hash functions do not support decryption.'
  )
}

