  {
    input: "a",
    key: "0",
    expected: "550d7456",
    description: "XXH32 one-byte input with seed 0",
  },
  {
    input: "abc",
    key: "0",
    expected: "32d153ff",
    description: "XXH32 short input with seed 0",
  },
  {
    input: "Hello, World!",
