function toUint32(value: number): number {
  return value >>> 0;
}

function rotl32(value: number, bits: number): number {
  return ((value << bits) | (value >>> (32 - bits))) >>> 0;
}

function mul32(a: number, b: number): number {
  return Math.imul(a, b) >>> 0;
}

function add32(...values: number[]): number {
  return values.reduce((sum, value) => (sum + value) >>> 0, 0);
}

function readUint32LE(bytes: Uint8Array, offset: number): number {
  return (
    (bytes[offset] |
      (bytes[offset + 1] << 8) |
      (bytes[offset + 2] << 16) |
      (bytes[offset + 3] << 24)) >>>
    0
  );
}

function toHex32(value: number): string {
  return (value >>> 0).toString(16).padStart(8, "0");
}

function parseSeed(key: string | undefined): number {
  const raw = key?.trim() ?? "";
  if (!raw) return 0;

  const parsed =
    raw.startsWith("0x") || raw.startsWith("0X")
      ? Number.parseInt(raw.slice(2), 16)
      : Number.parseInt(raw, 10);

  if (!Number.isFinite(parsed) || Number.isNaN(parsed)) {
    throw new CipherError(
      "INVALID_KEY",
      "XXHash seed must be a decimal integer or 0x-prefixed hexadecimal value.",
    );
  }

  if (parsed < 0 || parsed > 0xffffffff) {
    throw new CipherError(
      "INVALID_KEY",
      "XXHash seed must fit inside an unsigned 32-bit integer.",
    );
  }

  return parsed >>> 0;
}

function round(accumulator: number, lane: number): number {
  return mul32(
    rotl32(add32(accumulator, mul32(lane, PRIME32_2)), 13),
    PRIME32_1,
  );
}

function avalanche(value: number): number {
  let hash = value >>> 0;
  hash ^= hash >>> 15;
  hash = mul32(hash, PRIME32_2);
  hash ^= hash >>> 13;
  hash = mul32(hash, PRIME32_3);
  hash ^= hash >>> 16;
  return hash >>> 0;
}

export function xxh32Hex(inputBytes: Uint8Array, seed = 0): string {
  let offset = 0;
  let hash: number;

  if (inputBytes.length >= 16) {
    let v1 = add32(seed, PRIME32_1, PRIME32_2);
    let v2 = add32(seed, PRIME32_2);
    let v3 = seed >>> 0;
    let v4 = add32(seed, -PRIME32_1);

    const limit = inputBytes.length - 16;
    while (offset <= limit) {
      v1 = round(v1, readUint32LE(inputBytes, offset));
      offset += 4;
      v2 = round(v2, readUint32LE(inputBytes, offset));
      offset += 4;
      v3 = round(v3, readUint32LE(inputBytes, offset));
      offset += 4;
      v4 = round(v4, readUint32LE(inputBytes, offset));
      offset += 4;
    }

    hash = add32(rotl32(v1, 1), rotl32(v2, 7), rotl32(v3, 12), rotl32(v4, 18));
  } else {
    hash = add32(seed, PRIME32_5);
  }

  hash = add32(hash, inputBytes.length);

  while (offset + 4 <= inputBytes.length) {
    hash = mul32(
      rotl32(
        add32(hash, mul32(readUint32LE(inputBytes, offset), PRIME32_3)),
        17,
      ),
      PRIME32_4,
    );
    offset += 4;
  }

  while (offset < inputBytes.length) {
    hash = mul32(
      rotl32(add32(hash, mul32(inputBytes[offset], PRIME32_5)), 11),
      PRIME32_1,
    );
    offset += 1;
  }

  return toHex32(avalanche(hash));
}

function pushStep(steps: CipherStep[], step: Omit<CipherStep, "index">): void {
  steps.push({
    index: steps.length,
    ...step,
  });
}

function xxhashInstrumented(
  inputBytes: Uint8Array,
  seed: number,
): CipherResult {
  const start = performance.now();
  const steps: CipherStep[] = [];
  let offset = 0;
  let hash: number;

  pushStep(steps, {
    label: "Read input and seed",
    inputState: fromByteArray(inputBytes, "hex"),
    outputState: "",
    table: [
      { key: "Input length", value: `${inputBytes.length} bytes` },
      { key: "Seed", value: `0x${toHex32(seed)}` },
      { key: "Mode", value: "XXH32 non-cryptographic hash" },
    ],
    note: "XXHash32 begins by converting the message into bytes and applying a 32-bit seed. It is designed for speed and checksums, not cryptographic collision resistance.",
    isMilestone: true,
  });

  if (inputBytes.length >= 16) {
    let v1 = add32(seed, PRIME32_1, PRIME32_2);
    let v2 = add32(seed, PRIME32_2);
    let v3 = seed >>> 0;
    let v4 = add32(seed, -PRIME32_1);

    pushStep(steps, {
      label: "Initialize four accumulators",
      inputState: "",
      outputState: "",
      table: [
        { key: "v1", value: `0x${toHex32(v1)}` },
        { key: "v2", value: `0x${toHex32(v2)}` },
        { key: "v3", value: `0x${toHex32(v3)}` },
        { key: "v4", value: `0x${toHex32(v4)}` },
      ],
      note: "Inputs of at least 16 bytes are processed in four parallel 32-bit lanes. This is the main reason XXHash is very fast.",
      isMilestone: true,
    });

    const limit = inputBytes.length - 16;
    let stripe = 0;

    while (offset <= limit) {
      const lane1 = readUint32LE(inputBytes, offset);
      offset += 4;
      const lane2 = readUint32LE(inputBytes, offset);
      offset += 4;
      const lane3 = readUint32LE(inputBytes, offset);
      offset += 4;
      const lane4 = readUint32LE(inputBytes, offset);
      offset += 4;

      v1 = round(v1, lane1);
      v2 = round(v2, lane2);
      v3 = round(v3, lane3);
      v4 = round(v4, lane4);

      pushStep(steps, {
        label: `Process 16-byte stripe ${stripe}`,
        inputState: fromByteArray(inputBytes.slice(offset - 16, offset), "hex"),
        outputState: "",
        matrix: [
          [`lane 1`, `0x${toHex32(lane1)}`, `v1 = 0x${toHex32(v1)}`],
          [`lane 2`, `0x${toHex32(lane2)}`, `v2 = 0x${toHex32(v2)}`],
          [`lane 3`, `0x${toHex32(lane3)}`, `v3 = 0x${toHex32(v3)}`],
          [`lane 4`, `0x${toHex32(lane4)}`, `v4 = 0x${toHex32(v4)}`],
        ],
        note: "Each 32-bit little-endian word is mixed into its lane using multiplication by a prime, a left rotation, and another prime multiplication.",
      });

      stripe += 1;
    }

    hash = add32(rotl32(v1, 1), rotl32(v2, 7), rotl32(v3, 12), rotl32(v4, 18));

    pushStep(steps, {
      label: "Merge accumulators",
      inputState: "",
      outputState: `0x${toHex32(hash)}`,
      table: [
        { key: "rotl(v1, 1)", value: `0x${toHex32(rotl32(v1, 1))}` },
        { key: "rotl(v2, 7)", value: `0x${toHex32(rotl32(v2, 7))}` },
        { key: "rotl(v3, 12)", value: `0x${toHex32(rotl32(v3, 12))}` },
        { key: "rotl(v4, 18)", value: `0x${toHex32(rotl32(v4, 18))}` },
      ],
      note: "The four lanes are rotated by different amounts and added to form the main hash state.",
      isMilestone: true,
    });
  } else {
    hash = add32(seed, PRIME32_5);

    pushStep(steps, {
      label: "Short-input initialization",
      inputState: "",
      outputState: `0x${toHex32(hash)}`,
      table: [
        { key: "seed", value: `0x${toHex32(seed)}` },
        { key: "PRIME32_5", value: `0x${toHex32(PRIME32_5)}` },
      ],
      note: "Inputs shorter than 16 bytes skip the four-lane accumulator stage and begin with seed + PRIME32_5.",
      isMilestone: true,
    });
  }

  hash = add32(hash, inputBytes.length);
  pushStep(steps, {
    label: "Add input length",
    inputState: "",
    outputState: `0x${toHex32(hash)}`,
    table: [{ key: "length", value: `${inputBytes.length} bytes` }],
    note: "The message length is added so messages with the same tail bytes but different lengths produce different hashes.",
    isMilestone: true,
  });

  while (offset + 4 <= inputBytes.length) {
    const word = readUint32LE(inputBytes, offset);
    hash = mul32(rotl32(add32(hash, mul32(word, PRIME32_3)), 17), PRIME32_4);

    pushStep(steps, {
      label: `Mix remaining 4-byte word at offset ${offset}`,
      inputState: fromByteArray(inputBytes.slice(offset, offset + 4), "hex"),
      outputState: `0x${toHex32(hash)}`,
      table: [
        { key: "word", value: `0x${toHex32(word)}` },
        { key: "hash", value: `0x${toHex32(hash)}` },
      ],
      note: "Remaining 4-byte chunks are multiplied by PRIME32_3, rotated, then multiplied by PRIME32_4.",
    });

    offset += 4;
  }

  while (offset < inputBytes.length) {
    const byte = inputBytes[offset];
    hash = mul32(rotl32(add32(hash, mul32(byte, PRIME32_5)), 11), PRIME32_1);

    pushStep(steps, {
      label: `Mix remaining byte at offset ${offset}`,
      inputState: byte.toString(16).padStart(2, "0"),
      outputState: `0x${toHex32(hash)}`,
      table: [
        { key: "byte", value: `0x${byte.toString(16).padStart(2, "0")}` },
        { key: "hash", value: `0x${toHex32(hash)}` },
      ],
      note: "Each leftover byte still affects the final digest through prime multiplication and rotation.",
    });

    offset += 1;
  }

  const beforeAvalanche = hash;

  hash ^= hash >>> 15;
  const afterShift15 = hash >>> 0;
  hash = mul32(hash, PRIME32_2);
  const afterPrime2 = hash;
  hash ^= hash >>> 13;
  const afterShift13 = hash >>> 0;
  hash = mul32(hash, PRIME32_3);
  const afterPrime3 = hash;
  hash ^= hash >>> 16;
  hash >>>= 0;

  pushStep(steps, {
    label: "Avalanche finalization",
    inputState: `0x${toHex32(beforeAvalanche)}`,
    outputState: `0x${toHex32(hash)}`,
    table: [
      { key: "xor >> 15", value: `0x${toHex32(afterShift15)}` },
      { key: "* PRIME32_2", value: `0x${toHex32(afterPrime2)}` },
      { key: "xor >> 13", value: `0x${toHex32(afterShift13)}` },
      { key: "* PRIME32_3", value: `0x${toHex32(afterPrime3)}` },
      { key: "xor >> 16", value: `0x${toHex32(hash)}` },
    ],
    note: "The avalanche stage diffuses small input changes across the final 32-bit output.",
    isMilestone: true,
  });

  pushStep(steps, {
    label: "Final XXH32 digest",
    inputState: "",
    outputState: toHex32(hash),
    table: [
      { key: "Hex digest", value: toHex32(hash) },
      { key: "Unsigned integer", value: hash.toString(10) },
    ],
    note: "The final 32-bit digest is displayed as eight hexadecimal characters. Use it for fast checksums, not for passwords, signatures, or security decisions.",
    isMilestone: true,
  });

  return {
    output: toHex32(hash),
    outputEncoding: "hex",
    steps,
    metadata: METADATA,
    durationMs: performance.now() - start,
  };
}

export function encrypt(
  input: string,
  key: string = "0",
  options: CipherOptions = {},
): CipherResult {
  validateHashInput(input);
  const seed = parseSeed(key);
  const inputBytes = toByteArray(input, options.encoding || "utf8");

  if (options.instrument) {
    return xxhashInstrumented(inputBytes, seed);
  }

  const start = performance.now();
  const output = xxh32Hex(inputBytes, seed);

  return {
    output,
    outputEncoding: "hex",
    steps: [],
    metadata: METADATA,
    durationMs: performance.now() - start,
  };
}

export function decrypt(): CipherResult {
  throw new CipherError(
    "ALGORITHM_UNSUPPORTED",
    "XXHash is a one-way non-cryptographic hash and does not support decryption.",
  );
}

/**
 * AES-GCM — authenticated encryption (AEAD).
 * NIST SP 800-38D (Galois/Counter Mode).
 *
 * GCM = CTR-mode confidentiality + a GHASH authentication tag. The plaintext is
 * encrypted with AES in counter mode (a keystream XORed with the data), and a
 * separate GHASH pass over the associated data and ciphertext produces a 128-bit
 * tag that binds them together. Flipping a single ciphertext (or AAD) byte makes
 * the recomputed tag disagree, so decryption *rejects* the message instead of
 * returning garbage — that is the integrity guarantee CTR/CBC alone don't give.
 *
 * Real mode: the authoritative ciphertext + tag are produced by WebCrypto
 * (crypto.subtle AES-GCM), as GUIDELINES prescribe. A parallel, pure-TypeScript
 * CTR + GHASH implementation (verified against the NIST/McGrew-Viega GCM test
 * vectors — see tests/unit/symmetric/aes-gcm.test.ts) drives the instrumented
 * visualization steps, so the visual walkthrough matches the real output
 * byte-for-byte without ever being used to protect sensitive data.
 *
 * @see CIPHER_ENGINE.md line ~651 ("GCM = CTR + GHASH")
 */

import type { CipherResult, CipherStep, CipherOptions, TestVector } from '../types'
import { CipherError, validateInput, toByteArray, fromByteArray } from '../../utils'
import { expandKey, processBlock } from './aes'

const METADATA = {
  name: 'AES-GCM (Galois/Counter Mode)',
  securityStatus: 'secure' as const,
  breakingComplexity: '2^128 (confidentiality) / 2^128 forgery resistance per 128-bit tag',
  yearDesigned: 2007,
  standardBody: 'NIST SP 800-38D',
  blockSize: 16,
}

// GCM is standardised around a 96-bit (12-byte) IV; that is what WebCrypto and
// every common protocol (TLS 1.3, WireGuard) use, and what this module supports.
const GCM_IV_BYTES = 12
const TAG_BYTES = 16

// ---------------------------------------------------------------------------
// WebCrypto (real mode) plumbing
// ---------------------------------------------------------------------------

function getSubtle(): SubtleCrypto {
  const subtle = globalThis.crypto?.subtle
  if (!subtle) {
    throw new CipherError(
      'WEBCRYPTO_UNAVAILABLE',
      'WebCrypto (crypto.subtle) is unavailable in this environment; AES-GCM real mode requires it.'
    )
  }
  return subtle
}

// crypto.subtle's DOM types want a BufferSource backed by a (non-shared)
// ArrayBuffer; our Uint8Arrays always are at runtime, so this narrowing is safe.
function asBufferSource(bytes: Uint8Array): BufferSource {
  return bytes as unknown as BufferSource
}

async function subtleGcmEncrypt(
  keyBytes: Uint8Array,
  iv: Uint8Array,
  plaintext: Uint8Array,
  aad: Uint8Array
): Promise<{ ciphertext: Uint8Array; tag: Uint8Array }> {
  const subtle = getSubtle()
  const key = await subtle.importKey('raw', asBufferSource(keyBytes), { name: 'AES-GCM' }, false, ['encrypt'])
  const params: AesGcmParams = { name: 'AES-GCM', iv: asBufferSource(iv), tagLength: TAG_BYTES * 8 }
  if (aad.length) params.additionalData = asBufferSource(aad)
  const combined = new Uint8Array(await subtle.encrypt(params, key, asBufferSource(plaintext)))
  // WebCrypto returns ciphertext || tag.
  return {
    ciphertext: combined.slice(0, combined.length - TAG_BYTES),
    tag: combined.slice(combined.length - TAG_BYTES),
  }
}

async function subtleGcmDecrypt(
  keyBytes: Uint8Array,
  iv: Uint8Array,
  ciphertext: Uint8Array,
  tag: Uint8Array,
  aad: Uint8Array
): Promise<Uint8Array> {
  const subtle = getSubtle()
  const key = await subtle.importKey('raw', asBufferSource(keyBytes), { name: 'AES-GCM' }, false, ['decrypt'])
  const params: AesGcmParams = { name: 'AES-GCM', iv: asBufferSource(iv), tagLength: TAG_BYTES * 8 }
  if (aad.length) params.additionalData = asBufferSource(aad)
  const combined = new Uint8Array(ciphertext.length + tag.length)
  combined.set(ciphertext, 0)
  combined.set(tag, ciphertext.length)
  try {
    const plain = await subtle.decrypt(params, key, asBufferSource(combined))
    return new Uint8Array(plain)
  } catch {
    // WebCrypto throws an OperationError (with no useful message) when the tag
    // does not verify. Translate it into a clear, teachable integrity failure.
    throw new CipherError(
      'AUTH_TAG_MISMATCH',
      'AES-GCM authentication failed: the tag does not match. The ciphertext, AAD, IV, or key was altered — GCM refuses to return unauthenticated plaintext.'
    )
  }
}

// ---------------------------------------------------------------------------
// Pure-TypeScript GCM (instrumentation + independently testable primitives)
// ---------------------------------------------------------------------------

// GF(2^128) multiplication per NIST SP 800-38D, Algorithm 1 (bit 0 = MSB of
// byte 0). Used by GHASH; the reduction polynomial is R = 11100001 || 0^120.
function gf128Mul(X: Uint8Array, Y: Uint8Array): Uint8Array {
  const Z = new Uint8Array(16)
  const V = new Uint8Array(Y)
  for (let i = 0; i < 128; i++) {
    if ((X[i >> 3] >> (7 - (i & 7))) & 1) {
      for (let j = 0; j < 16; j++) Z[j] ^= V[j]
    }
    const lsb = V[15] & 1
    for (let j = 15; j > 0; j--) {
      V[j] = ((V[j] >> 1) | (V[j - 1] << 7)) & 0xff
    }
    V[0] = V[0] >> 1
    if (lsb) V[0] ^= 0xe1
  }
  return Z
}

// GHASH_H(data): data must already be a multiple of the 16-byte block size.
function ghash(H: Uint8Array, data: Uint8Array, onBlock?: (y: Uint8Array, i: number) => void): Uint8Array {
  let Y: Uint8Array = new Uint8Array(16)
  for (let i = 0; i < data.length; i += 16) {
    for (let j = 0; j < 16; j++) Y[j] ^= data[i + j]
    Y = gf128Mul(Y, H)
    onBlock?.(Y, i / 16)
  }
  return Y
}

// Increment the rightmost 32 bits of a counter block (mod 2^32), big-endian.
function inc32(block: Uint8Array): Uint8Array {
  const out = new Uint8Array(block)
  for (let i = 15; i >= 12; i--) {
    out[i] = (out[i] + 1) & 0xff
    if (out[i] !== 0) break
  }
  return out
}

// Pad `bytes` up to the next 16-byte boundary with zeros.
function zeroPadLen(len: number): number {
  return (16 - (len % 16)) % 16
}

function writeUint64BE(target: Uint8Array, offset: number, value: bigint): void {
  for (let i = 7; i >= 0; i--) {
    target[offset + i] = Number(value & 0xffn)
    value >>= 8n
  }
}

// Build the GHASH input: A || 0* || C || 0* || [len(A)]64 || [len(C)]64 (bits).
function buildGhashData(aad: Uint8Array, ciphertext: Uint8Array): Uint8Array {
  const aadPad = zeroPadLen(aad.length)
  const ctPad = zeroPadLen(ciphertext.length)
  const data = new Uint8Array(aad.length + aadPad + ciphertext.length + ctPad + 16)
  let o = 0
  data.set(aad, o)
  o += aad.length + aadPad
  data.set(ciphertext, o)
  o += ciphertext.length + ctPad
  writeUint64BE(data, o, BigInt(aad.length) * 8n)
  writeUint64BE(data, o + 8, BigInt(ciphertext.length) * 8n)
  return data
}

// GCTR: AES-CTR with a 32-bit incrementing counter, starting at `icb`.
function gctr(roundKeys: Uint8Array[], icb: Uint8Array, input: Uint8Array): Uint8Array {
  const out = new Uint8Array(input.length)
  let counter: Uint8Array = new Uint8Array(icb)
  const numBlocks = Math.ceil(input.length / 16)
  for (let b = 0; b < numBlocks; b++) {
    const keystream = processBlock(counter, roundKeys, false)
    const offset = b * 16
    const blockLen = Math.min(16, input.length - offset)
    for (let i = 0; i < blockLen; i++) out[offset + i] = input[offset + i] ^ keystream[i]
    counter = inc32(counter)
  }
  return out
}

function computeJ0(iv: Uint8Array): Uint8Array {
  // For a 96-bit IV, J0 = IV || 0x00000001.
  const j0 = new Uint8Array(16)
  j0.set(iv)
  j0[15] = 1
  return j0
}

interface GcmRaw {
  ciphertext: Uint8Array
  tag: Uint8Array
}

/**
 * Reference GCM encryption in pure TypeScript. Exported for the NIST test
 * vectors; the visualizer uses WebCrypto for the authoritative output.
 */
export function gcmEncryptRaw(
  keyBytes: Uint8Array,
  iv: Uint8Array,
  plaintext: Uint8Array,
  aad: Uint8Array = new Uint8Array(0)
): GcmRaw {
  const roundKeys = expandKey(keyBytes)
  const H = processBlock(new Uint8Array(16), roundKeys, false)
  const j0 = computeJ0(iv)
  const ciphertext = gctr(roundKeys, inc32(j0), plaintext)
  const S = ghash(H, buildGhashData(aad, ciphertext))
  const ej0 = processBlock(j0, roundKeys, false)
  const tag = new Uint8Array(16)
  for (let i = 0; i < 16; i++) tag[i] = S[i] ^ ej0[i]
  return { ciphertext, tag }
}

// ---------------------------------------------------------------------------
// Instrumented step builders (visualization only)
// ---------------------------------------------------------------------------

const ZERO_BLOCK_HEX = '00000000000000000000000000000000'

function buildEncryptSteps(
  keyBytes: Uint8Array,
  iv: Uint8Array,
  plaintext: Uint8Array,
  aad: Uint8Array,
  ciphertext: Uint8Array,
  tag: Uint8Array
): CipherStep[] {
  const roundKeys = expandKey(keyBytes)
  const H = processBlock(new Uint8Array(16), roundKeys, false)
  const j0 = computeJ0(iv)
  const steps: CipherStep[] = []

  steps.push({
    index: steps.length,
    label: 'GCM Setup — Hash Subkey H',
    inputState: ZERO_BLOCK_HEX,
    outputState: fromByteArray(H, 'hex'),
    note: 'H = AES_K(0¹²⁸). This block-cipher encryption of an all-zero block is the multiplication key used by every GHASH step.',
    isMilestone: true,
  })

  steps.push({
    index: steps.length,
    label: 'GCM Pre-Counter Block J0',
    inputState: fromByteArray(iv, 'hex'),
    outputState: fromByteArray(j0, 'hex'),
    note: 'With a 96-bit IV, J0 = IV ‖ 0x00000001. CTR encryption starts at inc32(J0); J0 itself is reserved to mask the final tag.',
    isMilestone: true,
  })

  // CTR-mode confidentiality: keystream XOR plaintext, block by block.
  let counter = inc32(j0)
  const ctrBlocks = Math.ceil(plaintext.length / 16)
  for (let b = 0; b < ctrBlocks; b++) {
    const keystream = processBlock(counter, roundKeys, false)
    const offset = b * 16
    const blockLen = Math.min(16, plaintext.length - offset)
    const ptBlock = plaintext.slice(offset, offset + blockLen)
    const ctBlock = ciphertext.slice(offset, offset + blockLen)
    steps.push({
      index: steps.length,
      label: `Block ${b + 1} — CTR Keystream`,
      inputState: fromByteArray(counter, 'hex'),
      outputState: fromByteArray(keystream, 'hex'),
      note: `Encrypted counter block ${b + 1} with AES to produce this block's keystream.`,
      isMilestone: b === 0,
    })
    steps.push({
      index: steps.length,
      label: `Block ${b + 1} — CTR Encrypt (XOR)`,
      inputState: fromByteArray(ptBlock, 'hex'),
      outputState: fromByteArray(ctBlock, 'hex'),
      note: 'XORed the plaintext block with the keystream to produce the ciphertext block (confidentiality only — no integrity yet).',
    })
    counter = inc32(counter)
  }

  // GHASH authentication: fold AAD + ciphertext + lengths into the tag.
  const ghashData = buildGhashData(aad, ciphertext)
  steps.push({
    index: steps.length,
    label: 'GHASH — Authentication Input',
    inputState: `AAD ${aad.length}B ‖ ciphertext ${ciphertext.length}B`,
    outputState: fromByteArray(ghashData, 'hex'),
    note: 'GHASH runs over AAD ‖ 0* ‖ ciphertext ‖ 0* ‖ len(AAD)₆₄ ‖ len(C)₆₄, so both the associated data and every ciphertext byte are authenticated.',
    isMilestone: true,
  })

  const totalGhashBlocks = ghashData.length / 16
  ghash(H, ghashData, (Y, i) => {
    // Instrument the first, second, and last accumulation to keep the trace
    // readable on large inputs while still showing the running GHASH state.
    if (i === 0 || i === 1 || i === totalGhashBlocks - 1) {
      steps.push({
        index: steps.length,
        label: `GHASH — Accumulate Block ${i + 1}/${totalGhashBlocks}`,
        inputState: fromByteArray(ghashData.slice(i * 16, i * 16 + 16), 'hex'),
        outputState: fromByteArray(Y, 'hex'),
        note: 'Yᵢ = (Yᵢ₋₁ ⊕ blockᵢ) · H in GF(2¹²⁸). Multiplying by H after each XOR chains every block into a single 128-bit accumulator.',
      })
    }
  })

  const S = ghash(H, ghashData)
  const ej0 = processBlock(j0, roundKeys, false)
  steps.push({
    index: steps.length,
    label: 'Authentication Tag = GHASH ⊕ AES_K(J0)',
    inputState: `S=${fromByteArray(S, 'hex')} ⊕ E(J0)=${fromByteArray(ej0, 'hex')}`,
    outputState: fromByteArray(tag, 'hex'),
    note: 'The final GHASH value S is masked by AES_K(J0) to form the 128-bit tag. Encrypting the mask stops an attacker who can see S from forging tags.',
    isMilestone: true,
  })

  steps.push({
    index: steps.length,
    label: 'AES-GCM Sealed Output',
    inputState: `IV ${iv.length}B ‖ ciphertext ${ciphertext.length}B ‖ tag 16B`,
    outputState: fromByteArray(iv, 'hex') + fromByteArray(ciphertext, 'hex') + fromByteArray(tag, 'hex'),
    note: 'Output is IV ‖ ciphertext ‖ tag. Confidentiality comes from CTR; integrity/authenticity from the GHASH tag.',
    isMilestone: true,
  })

  return steps
}

function buildDecryptSteps(
  keyBytes: Uint8Array,
  iv: Uint8Array,
  ciphertext: Uint8Array,
  tag: Uint8Array,
  aad: Uint8Array,
  plaintext: Uint8Array
): CipherStep[] {
  const roundKeys = expandKey(keyBytes)
  const H = processBlock(new Uint8Array(16), roundKeys, false)
  const j0 = computeJ0(iv)
  const steps: CipherStep[] = []

  steps.push({
    index: steps.length,
    label: 'GCM Setup — Hash Subkey H',
    inputState: ZERO_BLOCK_HEX,
    outputState: fromByteArray(H, 'hex'),
    note: 'H = AES_K(0¹²⁸), recomputed by the receiver to re-derive the authentication tag.',
    isMilestone: true,
  })

  // Recompute the expected tag over the received ciphertext first — GCM verifies
  // BEFORE releasing any plaintext.
  const S = ghash(H, buildGhashData(aad, ciphertext))
  const ej0 = processBlock(j0, roundKeys, false)
  const expectedTag = new Uint8Array(16)
  for (let i = 0; i < 16; i++) expectedTag[i] = S[i] ^ ej0[i]

  steps.push({
    index: steps.length,
    label: 'GHASH — Recompute Tag over Received Ciphertext',
    inputState: fromByteArray(ciphertext, 'hex'),
    outputState: fromByteArray(expectedTag, 'hex'),
    note: 'The receiver runs the same GHASH + AES_K(J0) mask over the ciphertext it actually received.',
    isMilestone: true,
  })

  steps.push({
    index: steps.length,
    label: 'Tag Verification',
    inputState: `received ${fromByteArray(tag, 'hex')}`,
    outputState: `expected ${fromByteArray(expectedTag, 'hex')}`,
    note: 'The tags match, so the message is authentic and CTR decryption may proceed. A single flipped byte would make these disagree and abort decryption.',
    isMilestone: true,
  })

  let counter = inc32(j0)
  const ctrBlocks = Math.ceil(ciphertext.length / 16)
  for (let b = 0; b < ctrBlocks; b++) {
    const keystream = processBlock(counter, roundKeys, false)
    const offset = b * 16
    const blockLen = Math.min(16, ciphertext.length - offset)
    steps.push({
      index: steps.length,
      label: `Block ${b + 1} — CTR Decrypt (XOR)`,
      inputState: fromByteArray(ciphertext.slice(offset, offset + blockLen), 'hex'),
      outputState: fromByteArray(plaintext.slice(offset, offset + blockLen), 'hex'),
      note: 'CTR decryption is identical to encryption: XOR the ciphertext block with AES_K(counter) to recover plaintext.',
      isMilestone: b === 0,
    })
    counter = inc32(counter)
  }

  steps.push({
    index: steps.length,
    label: 'AES-GCM Verified Plaintext',
    inputState: `ciphertext ${ciphertext.length}B`,
    outputState: fromByteArray(plaintext, 'hex'),
    note: 'Plaintext is released only because the tag verified first.',
    isMilestone: true,
  })

  return steps
}

// ---------------------------------------------------------------------------
// Key / IV / AAD parsing
// ---------------------------------------------------------------------------

function getKeyBytes(key: string): Uint8Array {
  const keyBytes = /^[0-9a-fA-F]+$/.test(key) && [32, 48, 64].includes(key.length)
    ? toByteArray(key, 'hex')
    : toByteArray(key, 'utf8')

  if (![16, 24, 32].includes(keyBytes.length)) {
    throw new CipherError(
      'INVALID_KEY_LENGTH',
      `AES-GCM key must be 16, 24, or 32 bytes (a 32/48/64-char hex string, or a 16/24/32-char passphrase); got ${keyBytes.length} bytes.`
    )
  }
  return keyBytes
}

function resolveIv(options: CipherOptions): { iv: Uint8Array; provided: boolean } {
  if (options.iv) {
    if (!/^[0-9a-fA-F]{24}$/.test(options.iv)) {
      throw new CipherError('INVALID_IV', 'AES-GCM IV must be exactly 24 hex characters (12 bytes / 96 bits).')
    }
    return { iv: toByteArray(options.iv, 'hex'), provided: true }
  }
  const iv = new Uint8Array(GCM_IV_BYTES)
  globalThis.crypto?.getRandomValues(iv)
  return { iv, provided: false }
}

function resolveAad(options: CipherOptions): Uint8Array {
  const aad = (options as { aad?: string }).aad
  if (!aad) return new Uint8Array(0)
  if (!/^[0-9a-fA-F]*$/.test(aad) || aad.length % 2 !== 0) {
    throw new CipherError('INVALID_AAD', 'AES-GCM associated data (AAD) must be an even-length hex string.')
  }
  return toByteArray(aad, 'hex')
}

// ---------------------------------------------------------------------------
// Public cipher contract
// ---------------------------------------------------------------------------

export async function encrypt(
  input: string,
  key: string,
  options: CipherOptions = {}
): Promise<CipherResult> {
  validateInput(input)
  const start = performance.now()

  const keyBytes = getKeyBytes(key)
  const { iv } = resolveIv(options)
  const aad = resolveAad(options)
  const plaintext = toByteArray(input, options.encoding || 'utf8')

  // Authoritative output comes from WebCrypto (real mode).
  const { ciphertext, tag } = await subtleGcmEncrypt(keyBytes, iv, plaintext, aad)

  const output = fromByteArray(iv, 'hex') + fromByteArray(ciphertext, 'hex') + fromByteArray(tag, 'hex')

  const steps = options.instrument
    ? buildEncryptSteps(keyBytes, iv, plaintext, aad, ciphertext, tag)
    : []

  return {
    output,
    outputEncoding: 'hex',
    steps,
    metadata: { ...METADATA, keySize: keyBytes.length * 8, modeOfOperation: 'GCM' },
    durationMs: performance.now() - start,
  }
}

export async function decrypt(
  input: string,
  key: string,
  options: CipherOptions = {}
): Promise<CipherResult> {
  validateInput(input)
  const start = performance.now()

  const keyBytes = getKeyBytes(key)
  const aad = resolveAad(options)

  const clean = input.trim()
  if (!/^[0-9a-fA-F]*$/.test(clean) || clean.length % 2 !== 0) {
    throw new CipherError('INVALID_INPUT', 'AES-GCM ciphertext must be a hex string (IV ‖ ciphertext ‖ tag).')
  }
  const minHex = (GCM_IV_BYTES + TAG_BYTES) * 2
  if (clean.length < minHex) {
    throw new CipherError(
      'INVALID_INPUT',
      `AES-GCM ciphertext is too short: expected at least a ${GCM_IV_BYTES}-byte IV and a ${TAG_BYTES}-byte tag.`
    )
  }

  const iv = toByteArray(clean.slice(0, GCM_IV_BYTES * 2), 'hex')
  const tag = toByteArray(clean.slice(clean.length - TAG_BYTES * 2), 'hex')
  const ciphertext = toByteArray(clean.slice(GCM_IV_BYTES * 2, clean.length - TAG_BYTES * 2), 'hex')

  // Real mode: WebCrypto verifies the tag and throws on any tampering.
  const plaintext = await subtleGcmDecrypt(keyBytes, iv, ciphertext, tag, aad)

  const steps = options.instrument
    ? buildDecryptSteps(keyBytes, iv, ciphertext, tag, aad, plaintext)
    : []

  const outEnc = options.encoding || 'utf8'
  return {
    output: fromByteArray(plaintext, outEnc),
    outputEncoding: outEnc,
    steps,
    metadata: { ...METADATA, keySize: keyBytes.length * 8, modeOfOperation: 'GCM' },
    durationMs: performance.now() - start,
  }
}

// NIST / McGrew-Viega GCM test vectors are asserted directly in
// tests/unit/symmetric/aes-gcm.test.ts against gcmEncryptRaw(); this array
// satisfies the shared cipher-module contract.
export const TEST_VECTORS: TestVector[] = []

/**
 * Camellia Block Cipher.
 * RFC 3713 compliant implementation.
 * Supports Camellia-128, Camellia-192, and Camellia-256.
 */

import type { CipherResult, CipherStep } from '../types'
import { fromByteArray, toByteArray, CipherError, validateInput, validateKey } from '../../utils'

const METADATA = {
  name: 'Camellia',
  securityStatus: 'secure' as const,
  breakingComplexity: '2^128, 2^192, 2^256',
  yearDesigned: 2000,
  standardBody: 'ISO/IEC 18033-3, RFC 3713',
  blockSize: 16,
}

export type CamelliaMode = 'ECB' | 'CBC'

const SBOX1 = new Uint8Array([
  112, 130,  44, 236, 179,  39, 192, 229, 228, 133,  87,  53, 234,  12, 174,  65,
   35, 239, 107, 147,  69,  25, 165,  33, 237,  14,  79,  78,  29, 101, 146, 189,
  134, 184, 175, 143, 124, 235,  31, 206,  62,  48, 220,  95,  94, 197,  11,  26,
  166, 225,  57, 202, 213,  71,  93,  61, 217,   1,  90, 214,  81,  86, 108,  77,
  139,  13, 154, 102, 251, 204, 176,  45, 116,  18,  43,  32, 240, 177, 132, 153,
  223,  76, 203, 194,  52, 126, 118,   5, 109, 183, 169,  49, 209,  23,   4, 215,
   20,  88,  58,  97, 222,  27,  17,  28,  50,  15, 156,  22,  83,  24, 242,  34,
  254,  68, 207, 178, 195, 181, 122, 145,  36,   8, 232, 168,  96, 252, 105,  80,
  170, 208, 160, 125, 161, 137,  98, 151,  84,  91,  30, 149, 224, 255, 100, 210,
   16, 196,   0,  72, 163, 247, 117, 219, 138,   3, 230, 218,   9,  63, 221, 148,
  135,  92, 131,   2, 205,  74, 144,  51, 115, 103, 246, 243, 157, 127, 191, 226,
   82, 155, 216,  38, 200,  55, 198,  59, 129, 150, 111,  75,  19, 190,  99,  46,
  233, 121, 167, 140, 159, 110, 188, 142,  41, 245, 249, 182,  47, 253, 180,  89,
  120, 152,   6, 106, 231,  70, 113, 186, 212,  37, 171,  66, 136, 162, 141, 250,
  114,   7, 185,  85, 248, 238, 172,  10,  54,  73,  42, 104,  60,  56, 241, 164,
   64,  40, 211, 123, 187, 201,  67, 193,  21, 227, 173, 244, 119, 199, 128, 158
])

const SBOX2 = new Uint8Array(256)
const SBOX3 = new Uint8Array(256)
const SBOX4 = new Uint8Array(256)

for (let i = 0; i < 256; i++) {
  const v = SBOX1[i]
  SBOX2[i] = ((v << 1) | (v >> 7)) & 0xff
  SBOX3[i] = ((v << 7) | (v >> 1)) & 0xff
  SBOX4[i] = SBOX1[((i << 1) | (i >> 7)) & 0xff]
}

const MASK32 = 0xffffffffn
const MASK64 = 0xffffffffffffffffn
const MASK128 = 0xffffffffffffffffffffffffffffffffn

function rotl32(val: bigint, shift: bigint): bigint {
  const s = shift % 32n
  if (s === 0n) return val & MASK32
  return ((val << s) & MASK32) | (val >> (32n - s))
}

function rotl128(val: bigint, shift: bigint): bigint {
  const s = shift % 128n
  if (s === 0n) return val & MASK128
  return ((val << s) & MASK128) | (val >> (128n - s))
}

function F(F_IN: bigint, KE: bigint): bigint {
  const x = F_IN ^ KE
  let t1 = Number((x >> 56n) & 0xffn)
  let t2 = Number((x >> 48n) & 0xffn)
  let t3 = Number((x >> 40n) & 0xffn)
  let t4 = Number((x >> 32n) & 0xffn)
  let t5 = Number((x >> 24n) & 0xffn)
  let t6 = Number((x >> 16n) & 0xffn)
  let t7 = Number((x >> 8n) & 0xffn)
  let t8 = Number(x & 0xffn)

  t1 = SBOX1[t1]
  t2 = SBOX2[t2]
  t3 = SBOX3[t3]
  t4 = SBOX4[t4]
  t5 = SBOX2[t5]
  t6 = SBOX3[t6]
  t7 = SBOX4[t7]
  t8 = SBOX1[t8]

  const y1 = t1 ^ t3 ^ t4 ^ t6 ^ t7 ^ t8
  const y2 = t1 ^ t2 ^ t4 ^ t5 ^ t7 ^ t8
  const y3 = t1 ^ t2 ^ t3 ^ t5 ^ t6 ^ t8
  const y4 = t2 ^ t3 ^ t4 ^ t5 ^ t6 ^ t7
  const y5 = t1 ^ t2 ^ t6 ^ t7 ^ t8
  const y6 = t2 ^ t3 ^ t5 ^ t7 ^ t8
  const y7 = t3 ^ t4 ^ t5 ^ t6 ^ t8
  const y8 = t1 ^ t4 ^ t5 ^ t6 ^ t7

  return (BigInt(y1) << 56n) | (BigInt(y2) << 48n) | (BigInt(y3) << 40n) | (BigInt(y4) << 32n) |
         (BigInt(y5) << 24n) | (BigInt(y6) << 16n) | (BigInt(y7) << 8n) | BigInt(y8)
}

function FL(FL_IN: bigint, KE: bigint): bigint {
  let x1 = FL_IN >> 32n
  let x2 = FL_IN & MASK32
  const k1 = KE >> 32n
  const k2 = KE & MASK32
  x2 = x2 ^ rotl32(x1 & k1, 1n)
  x1 = x1 ^ (x2 | k2)
  return ((x1 << 32n) | x2) & MASK64
}

function FLINV(FLINV_IN: bigint, KE: bigint): bigint {
  let y1 = FLINV_IN >> 32n
  let y2 = FLINV_IN & MASK32
  const k1 = KE >> 32n
  const k2 = KE & MASK32
  y1 = y1 ^ (y2 | k2)
  y2 = y2 ^ rotl32(y1 & k1, 1n)
  return ((y1 << 32n) | y2) & MASK64
}

const Sigma1 = 0xA09E667F3BCC908Bn
const Sigma2 = 0xB67AE8584CAA73B2n
const Sigma3 = 0xC6EF372FE94F82BEn
const Sigma4 = 0x54FF53A5F1D36F1Cn
const Sigma5 = 0x10E527FADE682D1Dn
const Sigma6 = 0xB05688C2B3E6C1FDn

interface CamelliaKeys {
  kw1: bigint, kw2: bigint, kw3: bigint, kw4: bigint
  k: bigint[]
  ke: bigint[]
}

function generateKeys(keyBytes: Uint8Array): CamelliaKeys {
  if (
    keyBytes.length !== 16 &&
    keyBytes.length !== 24 &&
    keyBytes.length !== 32
  ) {
    throw new CipherError(
      'INVALID_KEY_LENGTH',
      `Camellia key must be exactly 16, 24, or 32 bytes (got ${keyBytes.length} bytes).`
    )
  }
  const K = new Uint8Array(32)
  K.set(keyBytes)

  let KL = 0n
  let KR = 0n

  if (keyBytes.length === 16) {
    KL = parseBigInt(K.subarray(0, 16))
    KR = 0n
  } else if (keyBytes.length === 24) {
    KL = parseBigInt(K.subarray(0, 16))
    const right64 = parseBigInt(K.subarray(16, 24))
    KR = (right64 << 64n) | (~right64 & MASK64)
  } else {
    KL = parseBigInt(K.subarray(0, 16))
    KR = parseBigInt(K.subarray(16, 32))
  }

  let D1 = (KL ^ KR) >> 64n
  let D2 = (KL ^ KR) & MASK64
  D2 = D2 ^ F(D1, Sigma1)
  D1 = D1 ^ F(D2, Sigma2)
  D1 = D1 ^ (KL >> 64n)
  D2 = D2 ^ (KL & MASK64)
  D2 = D2 ^ F(D1, Sigma3)
  D1 = D1 ^ F(D2, Sigma4)
  const KA = (D1 << 64n) | D2

  let KB = 0n
  if (keyBytes.length > 16) {
    let D1_B = (KA ^ KR) >> 64n
    let D2_B = (KA ^ KR) & MASK64
    D2_B = D2_B ^ F(D1_B, Sigma5)
    D1_B = D1_B ^ F(D2_B, Sigma6)
    KB = (D1_B << 64n) | D2_B
  }

  const k: bigint[] = new Array(25).fill(0n)
  const ke: bigint[] = new Array(7).fill(0n)

  const kw1 = rotl128(KL, 0n) >> 64n
  const kw2 = rotl128(KL, 0n) & MASK64

  if (keyBytes.length === 16) {
    k[1]  = rotl128(KA, 0n) >> 64n
    k[2]  = rotl128(KA, 0n) & MASK64
    k[3]  = rotl128(KL, 15n) >> 64n
    k[4]  = rotl128(KL, 15n) & MASK64
    k[5]  = rotl128(KA, 15n) >> 64n
    k[6]  = rotl128(KA, 15n) & MASK64
    ke[1] = rotl128(KA, 30n) >> 64n
    ke[2] = rotl128(KA, 30n) & MASK64
    k[7]  = rotl128(KL, 45n) >> 64n
    k[8]  = rotl128(KL, 45n) & MASK64
    k[9]  = rotl128(KA, 45n) >> 64n
    k[10] = rotl128(KL, 60n) & MASK64
    k[11] = rotl128(KA, 60n) >> 64n
    k[12] = rotl128(KA, 60n) & MASK64
    ke[3] = rotl128(KL, 77n) >> 64n
    ke[4] = rotl128(KL, 77n) & MASK64
    k[13] = rotl128(KL, 94n) >> 64n
    k[14] = rotl128(KL, 94n) & MASK64
    k[15] = rotl128(KA, 94n) >> 64n
    k[16] = rotl128(KA, 94n) & MASK64
    k[17] = rotl128(KL, 111n) >> 64n
    k[18] = rotl128(KL, 111n) & MASK64
    const kw3 = rotl128(KA, 111n) >> 64n
    const kw4 = rotl128(KA, 111n) & MASK64
    return { kw1, kw2, kw3, kw4, k, ke }
  } else {
    k[1]  = rotl128(KB, 0n) >> 64n
    k[2]  = rotl128(KB, 0n) & MASK64
    k[3]  = rotl128(KR, 15n) >> 64n
    k[4]  = rotl128(KR, 15n) & MASK64
    k[5]  = rotl128(KA, 15n) >> 64n
    k[6]  = rotl128(KA, 15n) & MASK64
    ke[1] = rotl128(KR, 30n) >> 64n
    ke[2] = rotl128(KR, 30n) & MASK64
    k[7]  = rotl128(KB, 30n) >> 64n
    k[8]  = rotl128(KB, 30n) & MASK64
    k[9]  = rotl128(KL, 45n) >> 64n
    k[10] = rotl128(KL, 45n) & MASK64
    k[11] = rotl128(KA, 45n) >> 64n
    k[12] = rotl128(KA, 45n) & MASK64
    ke[3] = rotl128(KL, 60n) >> 64n
    ke[4] = rotl128(KL, 60n) & MASK64
    k[13] = rotl128(KR, 60n) >> 64n
    k[14] = rotl128(KR, 60n) & MASK64
    k[15] = rotl128(KB, 60n) >> 64n
    k[16] = rotl128(KB, 60n) & MASK64
    k[17] = rotl128(KL, 77n) >> 64n
    k[18] = rotl128(KL, 77n) & MASK64
    ke[5] = rotl128(KA, 77n) >> 64n
    ke[6] = rotl128(KA, 77n) & MASK64
    k[19] = rotl128(KR, 94n) >> 64n
    k[20] = rotl128(KR, 94n) & MASK64
    k[21] = rotl128(KA, 94n) >> 64n
    k[22] = rotl128(KA, 94n) & MASK64
    k[23] = rotl128(KL, 111n) >> 64n
    k[24] = rotl128(KL, 111n) & MASK64
    const kw3 = rotl128(KB, 111n) >> 64n
    const kw4 = rotl128(KB, 111n) & MASK64
    return { kw1, kw2, kw3, kw4, k, ke }
  }
}

function parseBigInt(arr: Uint8Array): bigint {
  let res = 0n
  for (let i = 0; i < arr.length; i++) {
    res = (res << 8n) | BigInt(arr[i])
  }
  return res
}

function toUint8Array(val: bigint, length: number): Uint8Array {
  const res = new Uint8Array(length)
  for (let i = length - 1; i >= 0; i--) {
    res[i] = Number(val & 0xffn)
    val >>= 8n
  }
  return res
}

function processBlock(blockBytes: Uint8Array, keys: CamelliaKeys, isExtendedRounds: boolean, decrypt: boolean): Uint8Array {
  let D1 = parseBigInt(blockBytes.subarray(0, 8))
  let D2 = parseBigInt(blockBytes.subarray(8, 16))

  const { kw1, kw2, kw3, kw4, k, ke } = keys

  if (!decrypt) {
    D1 = D1 ^ kw1
    D2 = D2 ^ kw2
    D2 = D2 ^ F(D1, k[1]); D1 = D1 ^ F(D2, k[2])
    D2 = D2 ^ F(D1, k[3]); D1 = D1 ^ F(D2, k[4])
    D2 = D2 ^ F(D1, k[5]); D1 = D1 ^ F(D2, k[6])
    D1 = FL(D1, ke[1]); D2 = FLINV(D2, ke[2])
    D2 = D2 ^ F(D1, k[7]); D1 = D1 ^ F(D2, k[8])
    D2 = D2 ^ F(D1, k[9]); D1 = D1 ^ F(D2, k[10])
    D2 = D2 ^ F(D1, k[11]); D1 = D1 ^ F(D2, k[12])
    D1 = FL(D1, ke[3]); D2 = FLINV(D2, ke[4])
    D2 = D2 ^ F(D1, k[13]); D1 = D1 ^ F(D2, k[14])
    D2 = D2 ^ F(D1, k[15]); D1 = D1 ^ F(D2, k[16])
    D2 = D2 ^ F(D1, k[17]); D1 = D1 ^ F(D2, k[18])

    if (isExtendedRounds) {
      D1 = FL(D1, ke[5]); D2 = FLINV(D2, ke[6])
      D2 = D2 ^ F(D1, k[19]); D1 = D1 ^ F(D2, k[20])
      D2 = D2 ^ F(D1, k[21]); D1 = D1 ^ F(D2, k[22])
      D2 = D2 ^ F(D1, k[23]); D1 = D1 ^ F(D2, k[24])
    }

    D2 = D2 ^ kw3
    D1 = D1 ^ kw4
  } else {
    D1 = D1 ^ kw3
    D2 = D2 ^ kw4

    if (isExtendedRounds) {
      D2 = D2 ^ F(D1, k[24]); D1 = D1 ^ F(D2, k[23])
      D2 = D2 ^ F(D1, k[22]); D1 = D1 ^ F(D2, k[21])
      D2 = D2 ^ F(D1, k[20]); D1 = D1 ^ F(D2, k[19])
      D1 = FL(D1, ke[6]); D2 = FLINV(D2, ke[5])
    }

    D2 = D2 ^ F(D1, k[18]); D1 = D1 ^ F(D2, k[17])
    D2 = D2 ^ F(D1, k[16]); D1 = D1 ^ F(D2, k[15])
    D2 = D2 ^ F(D1, k[14]); D1 = D1 ^ F(D2, k[13])
    D1 = FL(D1, ke[4]); D2 = FLINV(D2, ke[3])
    D2 = D2 ^ F(D1, k[12]); D1 = D1 ^ F(D2, k[11])
    D2 = D2 ^ F(D1, k[10]); D1 = D1 ^ F(D2, k[9])
    D2 = D2 ^ F(D1, k[8]);  D1 = D1 ^ F(D2, k[7])
    D1 = FL(D1, ke[2]); D2 = FLINV(D2, ke[1])
    D2 = D2 ^ F(D1, k[6]);  D1 = D1 ^ F(D2, k[5])
    D2 = D2 ^ F(D1, k[4]);  D1 = D1 ^ F(D2, k[3])
    D2 = D2 ^ F(D1, k[2]);  D1 = D1 ^ F(D2, k[1])

    D2 = D2 ^ kw1
    D1 = D1 ^ kw2
  }

  const out = new Uint8Array(16)
  out.set(toUint8Array(D2, 8), 0)
  out.set(toUint8Array(D1, 8), 8)
  return out
}

function xorBlocks(a: Uint8Array, b: Uint8Array): Uint8Array {
  const result = new Uint8Array(16)
  for (let i = 0; i < 16; i++) result[i] = a[i] ^ b[i]
  return result
}

function padPKCS7(bytes: Uint8Array, blockSize: number): Uint8Array {
  const paddingVal = blockSize - (bytes.length % blockSize)
  const padded = new Uint8Array(bytes.length + paddingVal)
  padded.set(bytes)
  for (let i = bytes.length; i < padded.length; i++) {
    padded[i] = paddingVal
  }
  return padded
}

function unpadPKCS7(bytes: Uint8Array): Uint8Array {
  if (bytes.length === 0) {
    throw new CipherError('INVALID_PADDING', 'Empty ciphertext or block size mismatch.')
  }
  const paddingVal = bytes[bytes.length - 1]
  if (paddingVal < 1 || paddingVal > 16 || paddingVal > bytes.length) {
    throw new CipherError('INVALID_PADDING', 'Invalid PKCS7 padding value.')
  }
  for (let i = bytes.length - paddingVal; i < bytes.length; i++) {
    if (bytes[i] !== paddingVal) {
      throw new CipherError('INVALID_PADDING', 'Invalid PKCS7 padding bytes.')
    }
  }
  return new Uint8Array(bytes.subarray(0, bytes.length - paddingVal))
}

function getKeyBytes(key: string, options?: Record<string, any>): Uint8Array {
  const encoding = options?.hexInput ? 'hex' : 'utf8'
  const keyBytes = toByteArray(key, encoding)

  if (
    keyBytes.length !== 16 &&
    keyBytes.length !== 24 &&
    keyBytes.length !== 32
  ) {
    throw new CipherError(
      'INVALID_KEY_LENGTH',
      `Camellia key must be exactly 16, 24, or 32 bytes (got ${keyBytes.length} bytes).`
    )
  }
  return keyBytes
}

export function encrypt(
  input: string | Uint8Array,
  key: string | Uint8Array,
  options?: Record<string, any>
): CipherResult {
  if (typeof input === 'string') validateInput(input)
  if (typeof key === 'string') validateKey(key)

  const mode = (options?.mode || 'ECB') as CamelliaMode
  const useCbc = mode === 'CBC'

  const inputBytes = typeof input === 'string' ? toByteArray(input, options?.hexInput ? 'hex' : 'utf8') : input
  const keyBytes = typeof key === 'string' ? getKeyBytes(key, options) : key

  if (
    keyBytes.length !== 16 &&
    keyBytes.length !== 24 &&
    keyBytes.length !== 32
  ) {
    throw new CipherError(
      'INVALID_KEY_LENGTH',
      `Camellia key must be exactly 16, 24, or 32 bytes (got ${keyBytes.length} bytes).`
    )
  }

  let iv: Uint8Array = new Uint8Array(16)
  if (useCbc) {
    if (options?.iv) {
      if (typeof options.iv === 'string') {
        if (!/^[0-9a-fA-F]{32}$/.test(options.iv)) {
          throw new CipherError('INVALID_IV', 'Camellia IV must be exactly 32 hex characters (16 bytes).')
        }
        iv = toByteArray(options.iv, 'hex')
      } else if (options.iv instanceof Uint8Array) {
        if (options.iv.length !== 16) {
          throw new CipherError('INVALID_IV', 'Camellia IV must be exactly 16 bytes.')
        }
        iv = options.iv
      } else {
        throw new CipherError('INVALID_IV', 'Invalid IV format.')
      }
    } else {
      if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
        crypto.getRandomValues(iv)
      } else {
        for (let i = 0; i < 16; i++) {
          iv[i] = Math.floor(Math.random() * 256)
        }
      }
    }
  }

  const res = executeCamellia(inputBytes, keyBytes, false, options, iv)

  if (useCbc) {
    const ivHex = fromByteArray(iv, 'hex')
    return {
      ...res,
      output: ivHex + res.output,
    }
  }

  return res
}

export function decrypt(
  input: string | Uint8Array,
  key: string | Uint8Array,
  options?: Record<string, any>
): CipherResult {
  if (typeof input === 'string') validateInput(input)
  if (typeof key === 'string') validateKey(key)

  const mode = (options?.mode || 'ECB') as CamelliaMode
  const useCbc = mode === 'CBC'

  const keyBytes = typeof key === 'string' ? getKeyBytes(key, options) : key

  if (
    keyBytes.length !== 16 &&
    keyBytes.length !== 24 &&
    keyBytes.length !== 32
  ) {
    throw new CipherError(
      'INVALID_KEY_LENGTH',
      `Camellia key must be exactly 16, 24, or 32 bytes (got ${keyBytes.length} bytes).`
    )
  }

  let iv: Uint8Array = new Uint8Array(16)
  let inputBytes: Uint8Array

  if (useCbc) {
    if (options?.iv) {
      if (typeof options.iv === 'string') {
        if (!/^[0-9a-fA-F]{32}$/.test(options.iv)) {
          throw new CipherError('INVALID_IV', 'Camellia IV must be exactly 32 hex characters (16 bytes).')
        }
        iv = toByteArray(options.iv, 'hex')
      } else if (options.iv instanceof Uint8Array) {
        if (options.iv.length !== 16) {
          throw new CipherError('INVALID_IV', 'Camellia IV must be exactly 16 bytes.')
        }
        iv = options.iv
      } else {
        throw new CipherError('INVALID_IV', 'Invalid IV format.')
      }
      inputBytes = typeof input === 'string' ? toByteArray(input, 'hex') : input
    } else {
      if (typeof input === 'string') {
        if (input.length < 32) {
          throw new CipherError('INVALID_INPUT', 'CBC ciphertext must include a 32-character hex IV prefix.')
        }
        iv = toByteArray(input.slice(0, 32), 'hex')
        inputBytes = toByteArray(input.slice(32), 'hex')
      } else {
        if (input.length < 16) {
          throw new CipherError('INVALID_INPUT', 'CBC ciphertext must include a 16-byte IV prefix.')
        }
        iv = input.subarray(0, 16)
        inputBytes = input.subarray(16)
      }
    }
  } else {
    inputBytes = typeof input === 'string' ? toByteArray(input, 'hex') : input
  }

  const defaultEncoding = typeof input === 'string' ? 'utf8' : 'hex'
  const outEnc = options?.encoding || defaultEncoding

  const res = executeCamellia(inputBytes, keyBytes, true, options, iv)
  const rawBytes = toByteArray(res.output, 'hex')

  return {
    ...res,
    output: fromByteArray(rawBytes, outEnc),
    outputEncoding: outEnc,
  }
}

function executeCamellia(
  inputBytes: Uint8Array,
  keyBytes: Uint8Array,
  isDecrypt: boolean,
  options?: Record<string, any>,
  iv: Uint8Array = new Uint8Array(16)
): CipherResult {
  const start = performance.now()
  const mode = (options?.mode || 'ECB') as CamelliaMode
  const useCbc = mode === 'CBC'
  const isExtendedRounds = keyBytes.length > 16

  const keys = generateKeys(keyBytes)
  const steps: CipherStep[] = []

  steps.push({
    index: 0,
    label: 'Key Schedule Expansion',
    inputState: fromByteArray(keyBytes, 'hex'),
    outputState: `Generated subkeys for ${isExtendedRounds ? '24' : '18'}-round Camellia.`,
    note: 'Expanded the original key into multiple 64-bit subkeys using the Feistel-based key schedule.',
    isMilestone: true,
  })

  const usePadding = options?.padding !== false
  let processedInput = inputBytes
  if (usePadding) {
    if (!isDecrypt) {
      processedInput = padPKCS7(inputBytes, 16)
    } else {
      if (inputBytes.length % 16 !== 0) {
        throw new CipherError('INVALID_INPUT', 'Ciphertext length must be a multiple of 16 bytes.')
      }
    }
  } else {
    if (inputBytes.length % 16 !== 0) {
      const errMsg = isDecrypt
        ? 'Ciphertext length must be a multiple of 16 bytes when padding is disabled.'
        : 'Plaintext length must be a multiple of 16 bytes when padding is disabled.'
      throw new CipherError('INVALID_INPUT', errMsg)
    }
  }

  const numBlocks = Math.ceil(processedInput.length / 16)
  const outputBytes = new Uint8Array(numBlocks * 16)
  let prevBlock: Uint8Array = useCbc ? iv : new Uint8Array(16)

  for (let b = 0; b < numBlocks; b++) {
    const offset = b * 16
    const blockLen = Math.min(16, processedInput.length - offset)

    const block = new Uint8Array(16)
    block.set(processedInput.subarray(offset, offset + blockLen))

    let resultBlock: Uint8Array

    if (useCbc && !isDecrypt) {
      const xoredBlock = xorBlocks(block, prevBlock)
      resultBlock = processBlock(xoredBlock, keys, isExtendedRounds, false)
      prevBlock = new Uint8Array(resultBlock)
    } else if (useCbc && isDecrypt) {
      const decrypted = processBlock(block, keys, isExtendedRounds, true)
      resultBlock = xorBlocks(decrypted, prevBlock)
      prevBlock = new Uint8Array(block)
    } else {
      resultBlock = processBlock(block, keys, isExtendedRounds, isDecrypt)
    }

    outputBytes.set(resultBlock, offset)

    steps.push({
      index: steps.length,
      label: `Block ${b + 1} Computation`,
      inputState: fromByteArray(block, 'hex'),
      outputState: fromByteArray(resultBlock, 'hex'),
      note: `Camellia block processing complete for block ${b + 1}.`,
      isMilestone: true,
    })
  }

  let finalOutputBytes: Uint8Array = outputBytes
  if (usePadding && isDecrypt) {
    finalOutputBytes = unpadPKCS7(outputBytes)
  }

  return {
    output: fromByteArray(finalOutputBytes, 'hex'),
    outputEncoding: 'hex',
    steps,
    metadata: { ...METADATA, modeOfOperation: mode },
    durationMs: performance.now() - start,
  }
}

/**
 * GOST 28147-89 — Soviet/Russian government standard block cipher
 * (declassified 1994; later the basis for GOST R 34.12-2015 "Magma").
 * 64-bit block (two 32-bit words), 256-bit key, 32-round Feistel network.
 * @see CIPHER_ENGINE.md Part 2 (Symmetric Ciphers) pattern
 *
 * IMPORTANT: unlike DES/AES, GOST's standard does NOT fix the S-boxes —
 * they are a separate negotiated parameter between communicating parties.
 * The S-boxes below are one widely-circulated reference/"test" parameter
 * set, NOT verified against a single canonical source — cite the actual
 * named parameter set you're using (e.g. a specific CryptoPro set) in
 * this file and in the registry description before merging, rather than
 * presenting these as definitive.
 *
 * Round-trip verified in a sandbox (decrypt(encrypt(x)) === x) with this
 * exact key-schedule ordering (K0..K7 x3 forward, K7..K0 once reverse,
 * final round skips the a/b swap).
 */

import type { CipherResult, CipherStep, CipherOptions, TestVector, CipherMetadata } from '../types'
import { CipherError, validateInput, validateKey } from '../../utils'

const METADATA: CipherMetadata = {
  name: 'GOST 28147-89',
  keySize: 256,
  blockSize: 64,
  rounds: 32,
  securityStatus: 'secure',
  breakingComplexity: 'No practical attack when using a well-chosen (non-degenerate) S-box set',
  yearDesigned: 1989,
  standardBody: 'GOST 28147-89 (declassified 1994)',
}

const MASK = 0xffffffff

// Reference S-box set — see file header. 8 boxes, each a 16-entry
// (4-bit -> 4-bit) lookup table, applied one per nibble of the 32-bit
// round-function output.
const SBOX: number[][] = [
  [4, 10, 9, 2, 13, 8, 0, 14, 6, 11, 1, 12, 7, 15, 5, 3],
  [14, 11, 4, 12, 6, 13, 15, 10, 2, 3, 8, 1, 0, 7, 5, 9],
  [5, 8, 1, 13, 10, 3, 4, 2, 14, 15, 12, 7, 6, 0, 9, 11],
  [7, 13, 10, 1, 0, 8, 9, 15, 14, 4, 6, 12, 11, 2, 5, 3],
  [6, 12, 7, 1, 5, 15, 13, 8, 4, 10, 9, 14, 0, 3, 11, 2],
  [4, 11, 10, 0, 7, 2, 1, 13, 3, 6, 8, 5, 9, 12, 15, 14],
  [13, 11, 4, 1, 3, 15, 5, 9, 0, 10, 14, 7, 6, 8, 2, 12],
  [1, 15, 13, 0, 5, 7, 10, 4, 9, 2, 3, 14, 6, 11, 8, 12],
]

function rotl(x: number, n: number): number {
  const ux = x >>> 0
  return (((ux << n) | (ux >>> (32 - n))) >>> 0)
}

function parseHexBytes(str: string, label: string): Uint8Array {
  const clean = str.replace(/\s+/g, '').toLowerCase()
  if (!/^[0-9a-f]*$/.test(clean) || clean.length % 2 !== 0) {
    throw new CipherError('INVALID_INPUT', `${label} must be a hex string with an even number of digits.`)
  }
  const bytes = new Uint8Array(clean.length / 2)
  for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16)
  return bytes
}
function bytesToHex(b: Uint8Array): string {
  return Array.from(b).map((x) => x.toString(16).padStart(2, '0')).join('')
}
function bytesToWordLE(b: Uint8Array, off: number): number {
  return (b[off] | (b[off + 1] << 8) | (b[off + 2] << 16) | (b[off + 3] << 24)) >>> 0
}
function wordToBytesLE(w: number, out: Uint8Array, off: number): void {
  out[off] = w & 0xff
  out[off + 1] = (w >>> 8) & 0xff
  out[off + 2] = (w >>> 16) & 0xff
  out[off + 3] = (w >>> 24) & 0xff
}
function wordToHex(w: number): string {
  return (w >>> 0).toString(16).padStart(8, '0')
}

function gostF(word: number, subkey: number): number {
  const x = (word + subkey) >>> 0
  let out = 0
  for (let i = 0; i < 8; i++) {
    const nibble = (x >>> (i * 4)) & 0xf
    out |= SBOX[i][nibble] << (i * 4)
  }
  return rotl(out >>> 0, 11)
}

function parseKey(key: string): number[] {
  validateKey(key)
  const bytes = parseHexBytes(key, 'GOST key')
  if (bytes.length !== 32) {
    throw new CipherError('INVALID_KEY_LENGTH', `GOST 28147-89 requires a 256-bit key as 64 hex characters (got ${bytes.length} bytes).`)
  }
  const K: number[] = []
  for (let i = 0; i < 8; i++) K.push(bytesToWordLE(bytes, i * 4))
  return K
}

function roundOrder(decrypt: boolean): number[] {
  const forward = [0, 1, 2, 3, 4, 5, 6, 7]
  const reverse = [7, 6, 5, 4, 3, 2, 1, 0]
  const encOrder = [...forward, ...forward, ...forward, ...reverse]
  return decrypt ? [...encOrder].reverse() : encOrder
}

function gostCore(input: string, key: string, decrypt: boolean, instrument: boolean): CipherResult {
  const start = performance.now()
  const K = parseKey(key)
  const bytes = parseHexBytes(input, 'GOST input')
  if (bytes.length === 0 || bytes.length % 8 !== 0) {
    throw new CipherError('INVALID_INPUT', `GOST input must be a non-empty multiple of 8 bytes (64-bit blocks). Got ${bytes.length} bytes.`)
  }

  const order = roundOrder(decrypt)
  const steps: CipherStep[] = []
  if (instrument) {
    steps.push({
      index: 0,
      label: 'Round key order',
      inputState: key,
      outputState: order.join(','),
      note: `${decrypt ? 'Decrypt' : 'Encrypt'} order: ${decrypt ? 'K0..K7 once forward, then K7..K0 three times' : 'K0..K7 three times forward, then K7..K0 once reverse'} — 32 rounds total.`,
      isMilestone: true,
    })
  }

  const numBlocks = bytes.length / 8
  const outBytes = new Uint8Array(bytes.length)
  for (let blk = 0; blk < numBlocks; blk++) {
    const off = blk * 8
    let a = bytesToWordLE(bytes, off)
    let b = bytesToWordLE(bytes, off + 4)
    const inHex = wordToHex(a) + wordToHex(b)

    order.forEach((ki, idx) => {
      const newB = a
      const newA = (b ^ gostF(a, K[ki])) >>> 0
      a = newA
      b = newB
      if (idx === order.length - 1) {
        // GOST's final round skips the usual swap
        ;[a, b] = [b, a]
      }
    })

    wordToBytesLE(a, outBytes, off)
    wordToBytesLE(b, outBytes, off + 4)
    const outHex = wordToHex(a) + wordToHex(b)

    if (instrument) {
      steps.push({
        index: steps.length,
        label: `Block ${blk + 1}/${numBlocks} — 32 rounds`,
        inputState: inHex,
        outputState: outHex,
        note: `'${inHex}' -> '${outHex}'`,
        isMilestone: true,
      })
    }
  }

  return {
    output: bytesToHex(outBytes),
    outputEncoding: 'hex',
    steps,
    metadata: METADATA,
    durationMs: performance.now() - start,
  }
}

export function encrypt(input: string, key: string, options: CipherOptions = {}): CipherResult {
  validateInput(input)
  return gostCore(input, key, false, !!options.instrument)
}
export function decrypt(input: string, key: string, options: CipherOptions = {}): CipherResult {
  validateInput(input)
  return gostCore(input, key, true, !!options.instrument)
}

export const TEST_VECTORS: TestVector[] = [
  {
    input: '0000000000000000',
    key: '000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f',
    expected: '66aa28cf3b24ddb9'.slice(0, 16),
    description: 'Self-computed reference (round-trip verified in sandbox; S-box set is a reference/"test" parameter set — see file header)',
  },
