import { EncodingType, EncodingErrorDetail, FaultType, MojibakeResult, ByteInspectorItem } from './types';

/**
 * Detects structural and specification errors in an encoded string.
 */
export function detectEncodingErrors(input: string, encoding: EncodingType): EncodingErrorDetail[] {
  const errors: EncodingErrorDetail[] = [];
  if (!input) return errors;

  if (encoding === 'Hex') {
    const cleanHex = input.replace(/\s+/g, '');
    if (cleanHex.length % 2 !== 0) {
      errors.push({
        index: cleanHex.length - 1,
        invalidValue: cleanHex[cleanHex.length - 1],
        reason: 'Hex strings must contain an even number of characters (2 hex digits per byte).',
        severity: 'error'
      });
    }
    for (let i = 0; i < cleanHex.length; i++) {
      if (!/^[0-9a-fA-F]$/.test(cleanHex[i])) {
        errors.push({
          index: i,
          invalidValue: cleanHex[i],
          reason: `Illegal character '${cleanHex[i]}' is not a valid hex digit (0-9, A-F).`,
          severity: 'error'
        });
      }
    }
  } else if (encoding === 'Base64') {
    const cleanB64 = input.trim();
    const b64Regex = /^[A-Za-z0-9+/]*={0,2}$/;
    if (!b64Regex.test(cleanB64)) {
      for (let i = 0; i < cleanB64.length; i++) {
        const char = cleanB64[i];
        if (!/^[A-Za-z0-9+/=]$/.test(char)) {
          errors.push({
            index: i,
            invalidValue: char,
            reason: `Illegal Base64 character '${char}'. Base64 only allows A-Z, a-z, 0-9, +, /, and padding =.`,
            severity: 'error'
          });
        } else if (char === '=' && i < cleanB64.length - 2) {
          errors.push({
            index: i,
            invalidValue: char,
            reason: 'Padding symbol "=" appears in the middle of data instead of the trailing end.',
            severity: 'error'
          });
        }
      }
    }
    if (cleanB64.length % 4 !== 0 && !errors.some(e => e.reason.includes('Illegal Base64'))) {
      errors.push({
        index: cleanB64.length - 1,
        invalidValue: cleanB64.slice(-1),
        reason: `Base64 string length (${cleanB64.length}) is not a multiple of 4. Missing padding '=' characters.`,
        severity: 'error'
      });
    }
  } else if (encoding === 'ASCII') {
    for (let i = 0; i < input.length; i++) {
      const code = input.charCodeAt(i);
      if (code > 127) {
        errors.push({
          index: i,
          invalidValue: input[i],
          reason: `Character '${input[i]}' (code 0x${code.toString(16).toUpperCase()}) exceeds 7-bit ASCII range (0-127).`,
          severity: 'error'
        });
      }
    }
  } else if (encoding === 'URL-Encoding') {
    for (let i = 0; i < input.length; i++) {
      if (input[i] === '%') {
        const hexSub = input.slice(i + 1, i + 3);
        if (hexSub.length < 2 || !/^[0-9a-fA-F]{2}$/.test(hexSub)) {
          errors.push({
            index: i,
            invalidValue: input.slice(i, i + 3),
            reason: `Malformed percent-encoded sequence '%${hexSub}'. Must be followed by two hexadecimal digits.`,
            severity: 'error'
          });
        }
      }
    }
  }

  return errors;
}

/**
 * Injects deliberate encoding faults into a valid string.
 */
export function injectEncodingFault(input: string, encoding: EncodingType, fault: FaultType): { corrupted: string; explanation: string } {
  if (fault === 'INVALID_CHAR') {
    if (encoding === 'Hex') {
      const pos = Math.floor(input.length / 2);
      const corrupted = input.slice(0, pos) + 'Z' + input.slice(pos + 1);
      return { corrupted, explanation: 'Injected non-hex character "Z" into the hex sequence.' };
    }
    if (encoding === 'Base64') {
      const pos = Math.floor(input.length / 2);
      const corrupted = input.slice(0, pos) + '!' + input.slice(pos + 1);
      return { corrupted, explanation: 'Injected non-Base64 symbol "!" into the encoded string.' };
    }
    const corrupted = input + 'ñ';
    return { corrupted, explanation: 'Injected high-range character "ñ" (byte 0xF1) into strict ASCII.' };
  }

  if (fault === 'TRUNCATED_SEQUENCE') {
    if (encoding === 'UTF-8') {
      // Create a string with a 3-byte character like Euro '€' (0xE2 0x82 0xAC) truncated
      const corrupted = 'Crypto€'.slice(0, -1); // Euro sign partially truncated
      return { corrupted: 'Crypto\xE2\x82', explanation: 'Truncated 3-byte UTF-8 sequence for "€" mid-way (0xE2 0x82 missing lead byte).' };
    }
    const corrupted = input.slice(0, Math.max(1, input.length - 1));
    return { corrupted, explanation: 'Truncated string, dropping the final byte or character.' };
  }

  if (fault === 'PADDING_CORRUPTION') {
    if (encoding === 'Base64') {
      // Remove or change padding '=' to 'X'
      const corrupted = input.endsWith('=') ? input.replace(/=/g, 'A') : input + '=X';
      return { corrupted, explanation: 'Corrupted Base64 padding characters at end of string.' };
    }
  }

  if (fault === 'ODD_LENGTH_HEX') {
    const corrupted = input.length % 2 !== 0 ? input : input.slice(0, -1);
    return { corrupted, explanation: 'Produced an odd-length Hex string (nibbles without paired byte).' };
  }

  if (fault === 'MALFORMED_URL_PERCENT') {
    const corrupted = input + '%2';
    return { corrupted, explanation: 'Appended incomplete percent sequence "%2" missing second hex nibble.' };
  }

  return { corrupted: input, explanation: 'No fault injected.' };
}

/**
 * Simulates Mojibake character set mismatches (e.g. UTF-8 read as ISO-8859-1 / Windows-1252).
 */
export function simulateMojibake(text: string, sourceEncoding: string = 'UTF-8', targetEncoding: string = 'ISO-8859-1'): MojibakeResult {
  const encoder = new TextEncoder();
  const utf8Bytes = encoder.encode(text);
  const hexBytes = Array.from(utf8Bytes).map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');

  // Convert raw UTF-8 bytes to ISO-8859-1 characters (1-to-1 byte to char code)
  const mojibakeChars = Array.from(utf8Bytes).map(b => String.fromCharCode(b)).join('');

  return {
    originalText: text,
    encodedBytesHex: hexBytes,
    interpretedText: mojibakeChars,
    explanation: `Original UTF-8 text "${text}" was encoded into bytes [${hexBytes}]. When decoded as ${targetEncoding}, each byte was interpreted directly as a latin-1 code point, resulting in Mojibake: "${mojibakeChars}".`
  };
}

/**
 * Attempts to automatically repair common encoding errors.
 */
export function autoFixEncodingError(input: string, encoding: EncodingType): string {
  if (encoding === 'Hex') {
    let clean = input.replace(/[^0-9a-fA-F]/g, '');
    if (clean.length % 2 !== 0) {
      clean = clean.slice(0, -1); // drop trailing un-paired nibble
    }
    return clean;
  }
  if (encoding === 'Base64') {
    let clean = input.replace(/[^A-Za-z0-9+/=]/g, '');
    clean = clean.replace(/=/g, ''); // remove internal equals
    const rem = clean.length % 4;
    if (rem === 2) clean += '==';
    else if (rem === 3) clean += '=';
    else if (rem === 1) clean = clean.slice(0, -1);
    return clean;
  }
  if (encoding === 'ASCII') {
    return input.replace(/[^\x00-\x7F]/g, '?');
  }
  if (encoding === 'URL-Encoding') {
    return encodeURIComponent(input);
  }
  return input;
}

/**
 * Builds a byte-by-byte visualizer inspect dataset.
 */
export function buildByteInspector(input: string, encoding: EncodingType): ByteInspectorItem[] {
  const items: ByteInspectorItem[] = [];
  const errors = detectEncodingErrors(input, encoding);

  for (let i = 0; i < input.length; i++) {
    const char = input[i];
    const code = char.charCodeAt(0);
    const err = errors.find(e => e.index === i);

    items.push({
      index: i,
      hex: code.toString(16).padStart(2, '0').toUpperCase(),
      binary: code.toString(2).padStart(8, '0'),
      char: char === ' ' ? '␣' : char,
      isError: Boolean(err),
      errorMessage: err?.reason
    });
  }

  return items;
}

'use client'

import { useEffect, useRef, useState, useCallback } from 'react'
import { WorkerPool } from '../workers/pool'
import type { AttackStep, OracleMode } from '../attacks/paddingOracle'

export function useAttackWorker() {
  const poolRef = useRef<WorkerPool | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (typeof window !== 'undefined') {
      poolRef.current = new WorkerPool(() => {
        return new Worker(new URL('../workers/attack.worker.ts', import.meta.url))
      })
    }

    return () => {
      if (poolRef.current) {
        poolRef.current.terminate()
        poolRef.current = null
      }
    }
  }, [])

  const recoverPlaintextConcurrently = useCallback(async (
    key: string,
    iv: Uint8Array,
    ciphertext: Uint8Array,
    mode: OracleMode,
    onStep?: (step: AttackStep) => void
  ): Promise<{ plaintext: Uint8Array, queryCount: number }> => {
    if (!poolRef.current) throw new Error('Worker pool not initialized')

    setLoading(true)
    setError(null)

    const BLOCK_SIZE = 16
    const numBlocks = ciphertext.length / BLOCK_SIZE

    if (!Number.isInteger(numBlocks) || numBlocks < 1) {
      setLoading(false)
      throw new Error('Ciphertext length must be a positive multiple of the block size.')
    }

    // Determine if SharedArrayBuffer is available
    const useSharedMemory = typeof SharedArrayBuffer !== 'undefined'

    let sharedCiphertextBuffer: ArrayBuffer | SharedArrayBuffer | null = null
    if (useSharedMemory) {
      sharedCiphertextBuffer = new SharedArrayBuffer(ciphertext.length)
      new Uint8Array(sharedCiphertextBuffer).set(ciphertext)
    }

    const blocks = [iv]
    for (let i = 0; i < ciphertext.length; i += BLOCK_SIZE) {
      blocks.push(ciphertext.subarray(i, i + BLOCK_SIZE))
    }

    let totalQueries = 0
    const plaintextBlocks: Uint8Array[] = new Array(numBlocks)

    const promises: Promise<void>[] = []

    for (let i = 1; i < blocks.length; i++) {
      const prevBlock = blocks[i - 1]
      const targetBlock = blocks[i]
      const blockIndex = i - 1

      // We transfer a copy if SharedArrayBuffer is not available, avoiding serialization
      const prevBlockBuffer = useSharedMemory ? new Uint8Array(prevBlock).buffer : prevBlock.buffer.slice(prevBlock.byteOffset, prevBlock.byteOffset + prevBlock.byteLength)
      const targetBlockBuffer = useSharedMemory && sharedCiphertextBuffer 
        ? sharedCiphertextBuffer
        : targetBlock.buffer.slice(targetBlock.byteOffset, targetBlock.byteOffset + targetBlock.byteLength)

      const transferList = useSharedMemory ? [] : [prevBlockBuffer, targetBlockBuffer]

      const promise = poolRef.current.execute(
        {
          type: 'recoverBlock',
          payload: {
            key,
            mode,
            prevBlockBuffer,
            targetBlockBuffer,
            blockOffset: useSharedMemory ? blockIndex * BLOCK_SIZE : 0,
            blockIndex,
          }
        },
        transferList,
        (step) => {
          if (onStep) onStep(step)
        }
      ).then(result => {
        const { plaintext, queryCount } = result
        plaintextBlocks[blockIndex] = new Uint8Array(plaintext)
        totalQueries += queryCount
      })

      promises.push(promise)
    }

    try {
      await Promise.all(promises)

      const totalLen = plaintextBlocks.reduce((sum, block) => sum + block.length, 0)
      const fullPlaintext = new Uint8Array(totalLen)
      let offset = 0
      for (const block of plaintextBlocks) {
        fullPlaintext.set(block, offset)
        offset += block.length
      }

      setLoading(false)
      return { plaintext: fullPlaintext, queryCount: totalQueries }
    } catch (err: any) {
      setLoading(false)
      const msg = err.message || 'Worker execution failed'
      setError(msg)
      throw new Error(msg)
    }
  }, [])

  const cancel = useCallback(() => {
    if (poolRef.current) {
      poolRef.current.terminate()
      poolRef.current = new WorkerPool(() => {
        return new Worker(new URL('../workers/attack.worker.ts', import.meta.url))
      })
      setLoading(false)
    }
  }, [])

  return { recoverPlaintextConcurrently, cancel, loading, error }
}

/**
 * Custom Hook for executing ciphers in a Web Worker.
 * SSR-safe and handles parallel requests using unique message IDs.
 * @see CLAUDE.md
 */

'use client'

import { useEffect, useRef, useState, useCallback } from 'react'
import type { CipherResult } from '../cipher/types'
import type { WorkerRequest, WorkerResponse } from '../../types/worker'
import type { CipherErrorCode } from '../utils/errors'


const MAX_CACHE_SIZE = 200
const resultCache = new Map<string, CipherResult>()

export function clearCipherWorkerCache() {
  resultCache.clear()
}

function sortObjectKeys(obj: any): any {
  if (obj === null || typeof obj !== 'object') {
    return obj
  }
  if (Array.isArray(obj)) {
    return obj.map(sortObjectKeys)
  }
  const sortedKeys = Object.keys(obj).sort()
  const result: any = {}
  for (const k of sortedKeys) {
    result[k] = sortObjectKeys(obj[k])
  }
  return result
}

// Fast deterministic 64-bit hash (sync). Not cryptographic; used only for cache keys.
// Based on splitmix64-style mixing; returned as unsigned hex string.
function hash64(input: string): string {
  // FNV-1a seed + splitmix-like finalizer
  let h1 = 0xcbf29ce484222325n
  const prime = 0x100000001b3n

  for (let i = 0; i < input.length; i++) {
    h1 ^= BigInt(input.charCodeAt(i))
    h1 = (h1 * prime) & 0xffffffffffffffffn
  }

  // Finalize (mix)
  h1 ^= h1 >> 30n
  h1 = (h1 * 0xbf58476d1ce4e5b9n) & 0xffffffffffffffffn
  h1 ^= h1 >> 27n
  h1 = (h1 * 0x94d049bb133111ebn) & 0xffffffffffffffffn
  h1 ^= h1 >> 31n

  // 16 hex chars for 64-bit
  const hex = h1.toString(16).padStart(16, '0')
  return hex
}

function getCacheKey(
  action: 'encrypt' | 'decrypt',
  cipherId: string,
  input: string,
  key: string,
  options?: any
): string {
  const { signal: _, bypassCache: __, ...cacheableOptions } = options || {}
  // Stable serialization for options to avoid key-order issues.
  const stableOptions = JSON.stringify(sortObjectKeys(cacheableOptions))

  // Hash the full tuple, but do not store the huge JSON/plaintext as the map key.
  // This dramatically reduces memory usage from large JSON.stringify results.
  return hash64(`${action}|${cipherId}|${input}|${key}|${stableOptions}`)
}


function cacheResult(key: string, result: CipherResult) {
  if (resultCache.has(key)) {
    resultCache.delete(key)
  } else if (resultCache.size >= MAX_CACHE_SIZE) {
    const oldestKey = resultCache.keys().next().value
    if (oldestKey !== undefined) {
      resultCache.delete(oldestKey)
    }
  }
  resultCache.set(key, result)
}

export function useCipherWorker() {
  const workerRef = useRef<Worker | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<{ code: CipherErrorCode; message?: string } | null>(null)

  const [fatalError, setFatalError] = useState<Error | null>(null)

  if (fatalError) {
    throw fatalError
  }

  // Map to track active requests, resolve/reject callbacks, abort signals, and timeouts
  const activeRequestsRef = useRef<
    Map<
      string,
      {
        resolve: (value: CipherResult) => void
        reject: (reason: any) => void
        signal?: AbortSignal
        onAbort?: () => void
        timeoutId?: ReturnType<typeof setTimeout>
        cacheKey?: string
      }
    >
  >(new Map())

  // Helper to terminate the worker and reject all pending requests (fatal errors only)
  const terminateWorkerAndRejectAll = useCallback((reason: Error) => {
    if (workerRef.current) {
      workerRef.current.terminate()
      workerRef.current = null
    }
    for (const [, req] of activeRequestsRef.current.entries()) {
      try {
        if (req.timeoutId) clearTimeout(req.timeoutId)
        if (req.signal && req.onAbort) {
          req.signal.removeEventListener('abort', req.onAbort)
        }
        req.reject(reason)
      } catch {
        // Ignore secondary errors during teardown
      }
    }
    activeRequestsRef.current.clear()
    setLoading(false)
  }, [])

  // Tracks the most recent (latest) request started by this hook instance.
  // Any worker response that doesn't match will be ignored to prevent stale UI updates.
  const latestRequestIdRef = useRef<string | null>(null)

  // Helper to create and initialize the web worker
  const createWorker = useCallback(() => {
    if (typeof window === 'undefined') return null


    const worker = new Worker(
      new URL('../workers/cipher.worker.ts', import.meta.url)
    )


    worker.onmessage = (event: MessageEvent<WorkerResponse>) => {
      const { requestId, success, payload } = event.data

      // Latest-request semantics: ignore any response that doesn't match the most recent request.
      if (latestRequestIdRef.current && requestId !== latestRequestIdRef.current) {
        // Still cleanup (if the request was not already removed from the map)
        activeRequestsRef.current.delete(requestId)
        if (activeRequestsRef.current.size === 0) {
          setLoading(false)
        }
        return
      }

      const request = activeRequestsRef.current.get(requestId)


      if (request) {
        if (request.timeoutId) {
          clearTimeout(request.timeoutId)
        }
        if (request.signal && request.onAbort) {
          request.signal.removeEventListener('abort', request.onAbort)
        }

        if (success && payload.result) {
          if (request.cacheKey) {
            cacheResult(request.cacheKey, payload.result)
          }
          request.resolve(payload.result)
        } else {
          const code = payload.errorCode
          if (code) {
            request.reject(Object.assign(new Error(payload.errorMessage || payload.error || 'Worker error'), { code }))
          } else {
            request.reject(new Error(payload.error || 'Worker error'))
          }
