'use client';

import { useState, useEffect, useCallback } from 'react';
import { OfflineCacheStatus } from './types';

const CACHE_NAME = 'cryptoviz-offline-v1';

export function useOfflinePackManager() {
  const [status, setStatus] = useState<OfflineCacheStatus>({
    isSupported: false,
    isOnline: true,
    isServiceWorkerActive: false,
    cachedPackIds: [],
    storageUsedBytes: 1250000,
    storageQuotaBytes: 50000000,
    isCachingInProgress: false,
    cachingProgressPct: 0,
  });

  // Check online status and storage estimate
  const updateStatus = useCallback(async () => {
    const isOnline = typeof navigator !== 'undefined' ? navigator.onLine : true;
    const isSupported = typeof window !== 'undefined' && 'serviceWorker' in navigator;
    let isSwActive = false;
    let cachedIds: string[] = [];

    if (isSupported && navigator.serviceWorker.controller) {
      isSwActive = true;
    }

    if (typeof window !== 'undefined' && 'caches' in window) {
      try {
        const cache = await caches.open(CACHE_NAME);
        const keys = await cache.keys();
        if (keys.length > 0) {
          // Look for cached pack indicators
          const cachedJsonStr = localStorage.getItem('cryptoviz_cached_packs');
          if (cachedJsonStr) {
            cachedIds = JSON.parse(cachedJsonStr);
          } else {
            cachedIds = ['symmetric-classical'];
          }
        }
      } catch (e) {
        console.warn('Error reading offline caches:', e);
      }
    }

    let used = 1450000;
    let quota = 50000000;
    if (typeof navigator !== 'undefined' && navigator.storage && navigator.storage.estimate) {
      try {
        const estimate = await navigator.storage.estimate();
        if (estimate.usage) used = estimate.usage;
        if (estimate.quota) quota = estimate.quota;
      } catch (e) {
        // Fallback defaults
      }
    }

    setStatus(prev => ({
      ...prev,
      isSupported,
      isOnline,
      isServiceWorkerActive: isSwActive,
      cachedPackIds: cachedIds,
      storageUsedBytes: used,
      storageQuotaBytes: quota,
    }));
  }, []);

  useEffect(() => {
    updateStatus();

    const handleOnline = () => updateStatus();
    const handleOffline = () => updateStatus();

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Register Service Worker if supported
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker
        .register('/sw.js')
        .then(() => updateStatus())
        .catch(err => console.warn('SW Registration note:', err));
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [updateStatus]);

  // Pre-cache a specific offline pack
  const cachePack = async (packId: string) => {
    setStatus(prev => ({ ...prev, isCachingInProgress: true, cachingProgressPct: 10 }));

    try {
      if ('caches' in window) {
        const cache = await caches.open(CACHE_NAME);
        await cache.addAll([
          '/',
          '/offline',
          '/docs',
          '/resources',
          '/visualizer/caesar/',
          '/icon.svg',
          '/globals.css',
        ]);
      }

      // Simulate step progress for user feedback
      for (let p = 20; p <= 100; p += 20) {
        await new Promise(r => setTimeout(r, 100));
        setStatus(prev => ({ ...prev, cachingProgressPct: p }));
      }

      const current = status.cachedPackIds;
      const updated = Array.from(new Set([...current, packId]));
      localStorage.setItem('cryptoviz_cached_packs', JSON.stringify(updated));

      setStatus(prev => ({
        ...prev,
        cachedPackIds: updated,
        isCachingInProgress: false,
        cachingProgressPct: 100,
      }));
    } catch (err) {
      console.error('Failed to cache pack:', err);
      setStatus(prev => ({ ...prev, isCachingInProgress: false, cachingProgressPct: 0 }));
    }
  };

  // Clear all offline cached packs
  const clearCache = async () => {
    if ('caches' in window) {
      try {
        await caches.delete(CACHE_NAME);
      } catch (e) {
        console.error('Failed to delete cache:', e);
      }
    }
    localStorage.removeItem('cryptoviz_cached_packs');
    setStatus(prev => ({
      ...prev,
      cachedPackIds: [],
      storageUsedBytes: 0,
    }));
  };

  return {
    status,
    cachePack,
    clearCache,
    refreshStatus: updateStatus,
  };
}

export interface ConversionHistoryEntry {
  id: string
  cipherId: string
  input: string
  key: string
  action: 'encrypt' | 'decrypt'
  output: string
  timestamp: string
}

export const MAX_CONVERSION_HISTORY_ENTRIES = 50

export const getConversionHistoryStorageKey = (cipherId: string) =>
  `cryptoviz-history-${cipherId}`

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

export function normalizeConversionHistory(
  value: unknown,
  cipherId: string,
): ConversionHistoryEntry[] {
  if (!Array.isArray(value)) return []

  const seen = new Set<string>()
  const normalized: ConversionHistoryEntry[] = []

  for (const item of value) {
    if (!isRecord(item)) continue

    const id = typeof item.id === 'string' ? item.id : ''
    const action =
      item.action === 'encrypt' || item.action === 'decrypt'
        ? item.action
        : null

    if (
      !id ||
      seen.has(id) ||
      !action ||
      typeof item.input !== 'string' ||
      typeof item.key !== 'string' ||
      typeof item.output !== 'string' ||
      typeof item.timestamp !== 'string'
    ) {
      continue
    }

    seen.add(id)
    normalized.push({
      id,
      cipherId,
      input: item.input,
      key: item.key,
      action,
      output: item.output,
      timestamp: item.timestamp,
    })

    if (normalized.length === MAX_CONVERSION_HISTORY_ENTRIES) break
  }

  return normalized
}

export function loadConversionHistory(
  cipherId: string,
): ConversionHistoryEntry[] {
  if (typeof window === 'undefined') return []

  try {
    const raw = window.localStorage.getItem(
      getConversionHistoryStorageKey(cipherId),
    )
    return raw ? normalizeConversionHistory(JSON.parse(raw), cipherId) : []
  } catch {
    return []
  }
}

export function saveConversionHistory(
  cipherId: string,
  history: ConversionHistoryEntry[],
): ConversionHistoryEntry[] {
  const normalized = normalizeConversionHistory(history, cipherId)

  if (typeof window !== 'undefined') {
    try {
      const stored = normalized.map(({ cipherId: _cipherId, ...entry }) => entry)
      window.localStorage.setItem(
        getConversionHistoryStorageKey(cipherId),
        JSON.stringify(stored),
      )
    } catch {
      // Storage can be unavailable in private mode or when quota is full.
    }
  }

  return normalized
}

export function clearConversionHistory(cipherId: string): void {
  if (typeof window === 'undefined') return

  try {
    window.localStorage.removeItem(getConversionHistoryStorageKey(cipherId))
  } catch {
    // Clearing should remain safe when localStorage is unavailable.
  }
}

export function filterConversionHistory(
  history: ConversionHistoryEntry[],
  query: string,
): ConversionHistoryEntry[] {
  const normalizedQuery = query.trim().toLowerCase()
  if (!normalizedQuery) return history

  return history.filter((entry) =>
    [entry.input, entry.output, entry.action, entry.timestamp, entry.key].some(
      (value) => value.toLowerCase().includes(normalizedQuery),
    ),
  )
}

function escapeCsvValue(value: string): string {
  return `"${value.replace(/"/g, '""')}"`
}

export function serializeConversionHistoryToCsv(
  history: ConversionHistoryEntry[],
): string {
  const header = [
    'cipherId',
    'input',
    'key',
    'direction',
    'output',
    'timestamp',
  ]

  const rows = history.map((entry) =>
    [
      entry.cipherId,
      entry.input,
      entry.key,
      entry.action,
      entry.output,
      entry.timestamp,
    ]
      .map(escapeCsvValue)
      .join(','),
  )

  return [header.join(','), ...rows].join('\n')
}

export function serializeConversionHistoryToJson(
  history: ConversionHistoryEntry[],
): string {
  return JSON.stringify(history, null, 2)
}

export function formatConversionHistoryRecord(
  entry: ConversionHistoryEntry,
): string {
  return [
    `Cipher: ${entry.cipherId}`,
    `Direction: ${entry.action}`,
    `Input: ${entry.input}`,
    `Key: ${entry.key || '—'}`,
    `Output: ${entry.output}`,
    `Timestamp: ${entry.timestamp}`,
  ].join('\n')
}

export function downloadTextFile(
  filename: string,
  contents: string,
  mimeType: string,
): void {
  if (typeof window === 'undefined') return

  const blob = new Blob([contents], { type: mimeType })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)
}

import { DeviceInfo } from '@/types/benchmark'

/**
 * Collects browser and device information for benchmark context
 */
export function getDeviceInfo(): DeviceInfo {
  const navigator = typeof window !== 'undefined' ? window.navigator : null
  const screen = typeof window !== 'undefined' ? window.screen : null

  return {
    userAgent: navigator?.userAgent || 'Unknown',
    hardwareConcurrency: navigator?.hardwareConcurrency || 1,
    deviceMemory: (navigator as any)?.deviceMemory,
    language: navigator?.language || 'Unknown',
    platform: navigator?.platform || 'Unknown',
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    screen: {
      width: screen?.width || 0,
      height: screen?.height || 0,
      colorDepth: screen?.colorDepth || 0,
      pixelDepth: screen?.pixelDepth || 0,
    },
  }
}

/**
 * Formats device info for display
 */
export function formatDeviceInfo(info: DeviceInfo): Record<string, string> {
  return {
    'CPU Cores': String(info.hardwareConcurrency),
    'Device Memory': info.deviceMemory ? `${info.deviceMemory} GB` : 'Unknown',
    'Platform': info.platform,
    'Language': info.language,
    'Timezone': info.timezone,
    'Screen': `${info.screen.width}x${info.screen.height}`,
    'User Agent': info.userAgent,
  }
}

import { PaddingOracle, recoverBlock, type AttackStep, BLOCK_SIZE } from '../attacks/paddingOracle';

const workerScope = self as unknown as Worker;

workerScope.addEventListener('message', (event: MessageEvent) => {
  const { type, payload } = event.data;

  if (type === 'recoverBlock') {
    const { key, mode, prevBlockBuffer, targetBlockBuffer, blockOffset, blockIndex } = payload;

    try {
      const prevBlock = new Uint8Array(prevBlockBuffer);
      const targetBlock = blockOffset !== undefined
        ? new Uint8Array(targetBlockBuffer, blockOffset, BLOCK_SIZE)
        : new Uint8Array(targetBlockBuffer);

      const oracle = new PaddingOracle(key, mode);

      const plaintext = recoverBlock(
        oracle,
        prevBlock,
        targetBlock,
        (step: AttackStep) => {
          // Send progress updates back to the main thread
          workerScope.postMessage({ type: 'progress', payload: step });
        },
        blockIndex
      );

      workerScope.postMessage({
        type: 'done',
        payload: {
          plaintext: plaintext.buffer,
          queryCount: oracle.queryCount
        }
      });
    } catch (error: any) {
      workerScope.postMessage({
        type: 'error',
        payload: { message: error.message }
      });
    }
  }
});

